window.__D("text/torat-chaim/c013",{"p":[[2300540891,"ולהסבירם בפרטו' באורך ורוחב או בקיצור שיובן ויושג גם לתלמיד קטן (כענין שישנה אדם לתלמידו בדרך קצרה<sup data-n=\"598\">587</sup> כמשי\"ת, לפי שהוא עצמו הוא שידע היטב מה שהעלים והלביש מעומק דח\"ע באותיות הללו ע\"כ לא יוכל חכם אחר זולתו להביא האותיות בביאור ופירוש בגילוי הדבור בפה רק הסופר עצמו שכתב הספר כו'. וזהו וחכם בבינה בתשבע\"פ שיבא מאין דחכמה ליש בהשגה שכלי' בדיבור בפרטו' להורות בין טו\"ט כו' שזהו הכל בפנימי' בינה שנק' מקום המתברר בעיון השכל כנ\"ל, שבא כח זה ממקור דח\"ע דמשפיע באותיות דתושב\"כ, וזהו ענין הסיפור דתושבע\"פ שמקבל מספר דתושב\"כ ע\"י התנאי' בעלי המדברי' במשנה כנ\"ל שנק' ממוצעי' ששרשם מבחי' סופר [ש]למעלה מספר וסיפור דח\"ע וח\"ת ע\"כ יכולים להביא מהעלם דח\"ע לגילוי באותיות דספר שנק' סופר העליון כמשה כנ\"ל, ולהיפוך מה שהעלים והלביש באותיות דתושב\"כ הוא שמגלה הכל בלי נטי' כלל אפי' כקש\"י כנ\"ל ולכוין לאמיתי' הרצה\"ע שבח\"ע ממש לפי שהן למעלה במקור הרצון (שהוא פותח את צנור דכתר בחכ' שנקרא טעם כמוס לרצה\"ע כידוע).\n<b>וזהו</b> שא' לבך יהגה אימה בתושבע\"פ שהיא שרש היראה (שזהו שהקדים יראה באם, איש אמו ואביו<sup data-n=\"599\">588</sup> כו' ובכיבוד הקדים אב דתושב\"כ כו' כמ\"ש במ\"א), איה סופר פי' איה א' די\"ה שלמעלה מי\"ה דחו\"ב ספר וסיפור, לכך יכול הוא לחבר ספר לסיפור בכל דרשו' של ד\"ס שסופרי' כל אותיות ודורשי' ומוסיפי' על התורה כמו זמד\"ר כנ\"ל ודקדוקי סופרי' [ו]כברכות המצות כנ\"ל <span data-k=\"pg\">יח</span> ּ עד שא' עריבים עלי ד\"ס יותר מיינה ש\"ת [ב]סוד הפנימי' דרצה\"ע (שנק' ח\"ס שמקבל מרצה\"ע שמורכב בטעם הכמוס כו'), והוא לפי ששרש הסופרי' הללו בעצמו' בעל הרצון והחכ' כמו שהוא במקורם העצמי' ממש כנ\"ל לכך מכונין היטב לנקוד' האמת אפי' בריבוי הדיבור בפה בכל פרטי ההלכות [ש]בש\"ס משנה לא יטו ימין ושמאל כו' (ואפי' מוטעי' נעשה כרצונם (כמשי\"ת). וזהו שא' פיה פתחה בחכ' שבדיבור שנק' סיפור כענין חכם בבינה כנ\"ל ותורת חסד ממילא על לשונה שזהו בא מבחי' סופר שלמעלה מספר וסיפור שממנו נמשך תורת חסד דח\"ע באותיות הכתב כנ\"ל והכל א' (וכנ\"ל בענין הצרופי' שבדבור שבאי' ממילא מעצמות מקור דחכ' שבראש שממנו בא אופן גילוי נביע' החכ' מאין ממש והכל א' כנ\"ל וד\"ל). וזהו ג\"כ ענין וכל בניך למודי הוי' שמלמדי' [ל]שם הוי' דח\"ע להתמשך בח\"ת כו'<sup data-n=\"600\">589</sup> בספר וסיפור. ורב שלום בניך שעושי' שלום וחיבור בין חו\"ב בספר וסיפור דחו\"ב בי\"ה דשם הוי' הנק' פמשמ\"ע וגם שלום בו\"ה בקול ודבור לחברם יחד כו' שזהו בקול ודיבור דמשנה דוקא שהן התנאי' ששונים הלכות שנק' ממוצעי', כמו משה ממש שנק' סופר ומחוקק למעלה לעשות שלום בי\"ה, כך הן עושי' שלום בו\"ה להיות נגלה מן",[["598","587","<b>שישנה אדם. . בדרך קצרה</b>: פסחים ג, ב."],["599","588","<b>איש אמו ואביו</b>: קדושים יט, ג. ראה זהר קדושים פא, ב. מאמרי אדה\"א בראשית ע' ב. ע' טו ואילך."],["600","589","<b>בח\"ת כו'</b>: יא: בדיבור כנ\"ל. יז: בחכ' כו'. 7"]]],[2300540900,"ההעלם דתושב\"כ בדיבור למעשה להיות הבירור בפו\"מ בין או\"ה וכו\"פ. וזהו ורב שלום בניך בוניך שעוסקי' בבנינו ש\"ע שהוא ע\"פ מא' דקו המדה שנק' סופר בוי\"ו ושוקל במתקלא<sup data-n=\"601\">590</sup> כו' כמ\"ש מי מדד בשעלו מים<sup data-n=\"602\">591</sup> דח\"ע, מי אסף רוח בחפניו והמשיך מח\"ע בח\"ת בקול ודיבור (מי הקים<sup data-n=\"603\">592</sup> כל אפסי ארץ שהן שנק' איתנים מוסדי ארץ שהן התנאי' שנק' סופרי' שסופר ושוקל ומודד כל מדה ושיעור בתושבע\"פ כו'), מה שמו זה משה כנ\"ל שהוא ממוצע הראשון מאור א\"ס בח\"ע, מה שם בנו כי תדע זהו ח\"ת דתושבע\"פ שנק' בניך ובוניך שעוסקי' בבנינו ש\"ע בקו המדה ואמת הבנין שלא לגרוע ולהוסיף על דבריהם בכל בנין בית דבחכמה יבנה בית<sup data-n=\"604\">593</sup> בבחי' הפנימי' דחיי עולם דתורה שממנו נמשך בנין העולמות בפנימי' וחיצוני' בי\"ה דחו\"ב ובו\"ה בפמשמ\"ע ופמשמ\"ט כנ\"ל וד\"ל).\n[כ] <b>ועוד</b> יתפרש מה שא' וכל בניך למודי [ה'] ורב שלום כו', על מה שארז\"ל שאין הגליות מתכנשות<sup data-n=\"605\">594</sup> אלא בזכות המשניות דוקא שנא' גם כי יתנו בגוים<sup data-n=\"606\">595</sup> עתה אקבצם כו', דהנה ענין הקיבוץ גליות זהו ממה שישראל נתפזרו בד' רוחות [העולם כמ\"ש כי כד' רוחות] השמים<sup data-n=\"607\">596</sup> כו' וכתיב אם יהי' נדחך בקצה השמים משם אקבצך<sup data-n=\"608\">597</sup> כו', וענין הפיזור הזה יש בזה ב' דברים הא' בשביל הבירור דניצוצי הקדושה שנעשה ע\"י נש\"י בתו\"מ ותשו' ותפלה בכל מקומות שנתפזרו שם בגוי' כמו גלו לאדום כו' וכתיב יצב גבולות עמים<sup data-n=\"609\">598</sup> למספר בנ\"י כו', שכפי אופן הצריך לברר מק\"נ בבחי' הטוב שנפל שם מז\"מ דתהו כך הוא בחי' הגלות והפיזור שם ממדרגה דכנ\"י אם בבחי' החסדי' או הגבו' כו', כדי שאחר הבירור יעלו משם בתוס' וריבוי גדול כזריעה שעולה צמיחה בתוס' גדול כמ\"ש אז יאמרו בגוים<sup data-n=\"610\">599</sup> דוקא הגדיל ה' לעשות עם אלה כו' בהגדלה וריבוי גדול (עד שיהי' למעלה מן המספר כמ\"ש והי' מספר בנ\"י<sup data-n=\"611\">600</sup> כחול הים כו' (כמשי\"ת), וכמו שא' בנוהי דאברהם שבבחי' החסד בגלותא דאדום ובנוהי דיצחק בגלותא דישמעאל<sup data-n=\"612\">601</sup> כו' (כמ\"ש במ\"א). והענין הב' בפיזור זה הוא מה שנתחלק לחלקי' מציור אדם כמו שהוא <span data-k=\"pg\">38</span> ּ בקומה שלימה כידוע בכללו' נש\"י נק' אדם אחד בקומה א'<sup data-n=\"613\">602</sup> ברמ\"ח אברים כלולי' זע\"ז כמו דגלי' די\"ב שבטי' חוני' כא' כו' שזה השבט במדרגת החסד כלול עם היפוכו כיד ימין ושמאל וכן שאר האברי' שכולם עוזרי' ז[א]\"ז ומתכללי' כא', וכללותם",[["601","590","<b>מא' דקו המדה. . מתקלא</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. וראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' ב. מאמרי אדה\"א נ\"ך ע' עא. לקמן פ' בשלח קסה, א."],["602","591","<b>מי מדד בשעלו מים</b>: ישעי' מ, יב."],["603","592","<b>מי אסף. . מי הקים</b>: משלי ל, ד."],["604","593","<b>דבחכמה יבנה בית</b>: משלי כד, ג."],["605","594","<b>שאין הגליות מתכנשות</b>: באוה\"ת שמות כאן ע' יז מציין ברבות פ' צו פ\"ז [, ג]. ראה הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תסו [ושם צ\"ל: תו\"א מט, ג]. לקמן פ' ויקהל תמ, ב."],["606","595","<b>גם כי יתנו בגוים</b>: הושע ח, י."],["607","596","<b>כי כד' רוחות] השמים</b>: זכרי' ב, י."],["608","597","<b>אם יהי' נדחך. . אקבצך</b>: נצבים ל, ד [ושם: יקבצך וכ\"ה בטזיז. אקבצך — ראה בסמוך בפנים. מאמרי אדה\"א בראשית ע' תקנז]."],["609","598","<b>יצב גבולות עמים</b>: האזינו לב, ח."],["610","599","<b>אז יאמרו בגוים</b>: תהלים קכו, ב."],["611","600","<b>והי' מספר בנ\"י</b>: הושע ב, א."],["612","601","<b>בנוהי דאברהם. . דישמעאל</b>: ראה זהר (רע\"מ) פינחס ריח, סע\"ב. לקמן פ' בשלח רל, ג. תצוה שנב, ד. מאמרי אדה\"ז תקס\"ט ע' פה וע' צז. פרשיות התורה ח\"א ע' רמח ואילך. שע\"ת פה, ג ואילך. מאמרי אדה\"א דברים ח\"א ע' קט."],["613","602","<b>נש\"י. . בקומה א'</b>: ראה גם לקמן מה, ד. וש\"נ."]]],[2300540907,"הוא במדות שבחכ' שבראש שנמשך למדות שבלב ומו\"ד שהן ו' מדות כלול[י'] כל א' מק' אלף ומתחלקי' לאין שיעור כמו יוסף ה' עליכם<sup data-n=\"614\">603</sup> כו', כמו נשמות שבכל הדורות שנמשכי' מת\"ר אלף נשמו' שבמ\"ת<sup data-n=\"615\">604</sup> כידוע. וענין קיבוץ גליות הזה זהו דוקא לאחר שלימות הבירורי' דק\"נ מן הניצוצי' דקדושה שנפלו במדו' וחכ' דק\"נ ע\"י מדו' וחכ' דקדושה שהוא ו' מדות דח\"ע שבאי' בהתלבשות בהעלם בו' מדות דו\"ס משנה שהן ס' מסכתות שנק' ס' מלכות לברר וללבן הלכתא להבדיל בין טו\"ט כו\"פ או\"ה כנ\"ל ע\"י הלימוד וגירסא בפה ששוני' המשניות דוקא שהן הלכו' ברורו' שיוצאי' מן הליבון (כמו שיניך כעדר הרחלים<sup data-n=\"616\">605</sup> שעל[ו] מן הרחצה כו') דמתני' מלכתא כנ\"ל, אז זה יגרום ב' דברים א' שלימות הבירור מע\"ש דנוגה שנתפזרו שם שיעלו משם בכי טוב בתוס' וריבוי גדול כנ\"ל (כמו וינצלו את מצרים<sup data-n=\"617\">606</sup> כו') ברכוש גדול מן העלאו' ריבוי הניצוצי' כו' שממילא יתקבצו ויעלו משם. והב' מה שמן הפיזור העצום הזה יתקבצו כולם יחד ו[י]הי' מהם ציור קומה שלימה בבחי' אדם שלם כו' וכמ\"ש משם אקבצך, שהוא בחי' ההתעוררו' להתקבץ ולהתכלל יחד אע\"פ שרחוקי' זמ\"ז ומפורדי' בתכלית כמו פירוד ב' הפכים כאש ומים דחו\"ג וכה\"ג יתעורר השלום ואחדו' להתחבר יחד דוקא כמו אפרי' לא יצור את יהודה<sup data-n=\"618\">607</sup> כו', וכמו עץ יוסף וכ\"י חביריו ועץ יהודה כו' יחדיו ידובקו<sup data-n=\"619\">608</sup>, למהוי אחד באחד, וכמ\"ש ואתם תלוקטו לאחד אחד<sup data-n=\"620\">610</sup> כו' להיות יחו\"ע ויחו\"ת<sup data-n=\"621\">609</sup> דיוסף צ\"ע ויהודה צ\"ת הכל א' [ב]מוח ולב שיתחברו יחד כשהוא בהתכללו' בקומה א' (וכתי' ואולך אתכם קוממיות<sup data-n=\"622\">611</sup> ב' קומות דאו\"י ואו\"ח דצ\"ג ובע\"ת וכה\"ג יחדיו). וכל זה ההתכללות מפיזור ופירוד גדול כזה (כענפי' מתפרדי' כמו בשנאת חנם זת\"ז כו'), יהי' מסיבת היחוד והבירור דש' מ\"ה דח\"ע במ\"ה דח\"ת בו' מדות דח\"ע בו' מדות דח\"ת בו\"ס משנה דוקא כנ\"ל<sup data-n=\"623\">612</sup>, דכל בחי' שם מ\"ה מלגיו<sup data-n=\"624\">613</sup> עושה יחוד והתכללו' גם מפיזור ופירוד להיותו בבחי' אין ומ\"ה בעצם היפך הישות והגסות ע\"כ עושה מגסות ויש אין כב' הפכי' לחברם, כענין עושה השלום במרומיו<sup data-n=\"625\">614</sup> כו' מבחי' אין ומ\"ה העליון כו'.\n<b>וזהו</b> וכל בניך לימודי הוי' בו\"ס משנה מהוי' דח\"ע בח\"ת כנ\"ל ע\"כ ורב שלום בניך בשלום והתחברו' בהתכללו' א' ממש בפמשמ\"ע במדו' דח\"ע ובפמשמ\"ט במדו' דח\"ת, וענין ריבוי",[["614","603","<b>יוסף ה' עליכם</b>: תהלים קטו, יד."],["615","604","<b>מת\"ר אלף נשמו' שבמ\"ת</b>: ראה שבת פח, א. לקמן פ' תרומה שיא, ד הערה 33. תניא פל\"ז. מאמרי אדה\"ז תקס\"ו ס\"ע קצ ואילך."],["616","605","<b>שיניך כעדר הרחלים</b>: שה\"ש ו, ו."],["617","606","<b>וינצלו את מצרים</b>: בא יב, לו."],["618","607","<b>אפרי' לא יצור את יהודה</b>: ישעי' יא, יג [ושם: ויהודה לא יצר את אפרים]."],["619","608","<b>עץ יוסף וכ\"י </b>[יא: ובנימין כו'. יז: ובנימין. יח: וכל]<b>. . ידובקו</b>: ראה יחזקאל לז, טז-יט."],["620","610","<b>ואתם תלוקטו לאחד אחד</b>: ישעי' כז, יב."],["621","609","<b>למהוי אחד באחד. . יחו\"ע ויחו\"ת</b>: ראה זהר תרומה קלג, סע\"ב ואילך. קלה, סע\"א. תו\"ח וישב רי, א."],["622","611","<b>ואולך אתכם קוממיות</b>: בחוקותי כו, יג. ראה בבא בתרא עה, א. מאמרי אדה\"א שמות ח\"ב ע' תרמו. וש\"נ. לקמן פ' תשא שפג, ג."],["623","612","<b>כנ\"ל</b>: יזיח: ליתא."],["624","613","<b>שם מ\"ה מלגיו</b>: ראה ת\"ז בהקדמה (יז, א). הדרת מלך שם (ע' קיב). סידור אדה\"ז סדר מנחת ערב שבת."],["625","614","<b>עושה השלום במרומיו</b>: איוב כה, ב [ושם: שלום — ראה לקמן פ' בשלח ריב, ד. יתרו ערה, ג. משפטים רצ, ד. הנסמן במ\"מ לשע\"ת נב, ג]."]]],[2300540914,"השלום זה ריבוי מיני התכללו' שיהי' בקיבוץ הגליות שיתחברו כמה מיני הפכי' יחד ויהי' להם לב אחד ומוח ורצון א' כאיש א' חבירי'<sup data-n=\"626\">615</sup> לאביהם שבשמים, כמו שהי' במ\"ת בת\"ר אלף דיעות [כו'] שא' ויחן ישראל כאיש ישראל א'<sup data-n=\"627\">616</sup> כו', וכן אומרי' ברכנו כולנו כא'<sup data-n=\"628\">617</sup> כו', וזה הי' רק בת\"ר אלף ולע\"ל יהי' קיבוץ גליות בכפלי כפליי' מס\"ר (עד שלא יספר וכמ\"ש ועלמות אין מספר (כמשי\"ת) וד\"ל. וזהו שא' אין הגליות מתכנשות אלא בזכות המשניות דוקא, שבלימוד המשנה מטעם הנ\"ל שהוא בירור דשם מ\"ה דאדם עילאה באדם תתאה דמל' ממילא יהי' קיבוץ הגליות יחד בב' דברים הנ\"ל בשלימות הבירור מניצוצי' שנפלו שם להפוך חשך לאור וענין ההתכללות וחיבור יחד מאליהם כנ\"ל וד\"ל. וזהו ג\"כ יוכל להיות ע\"י ב' דברים בתשובה ובצדקה כמ\"ש אם ישראל עושי' תשובה נגאלים<sup data-n=\"629\">618</sup>, וכן א' אין <span data-k=\"pg\">יט</span> ּ ישראל נגאלי' אלא בצדקה<sup data-n=\"630\">619</sup>, כמ\"ש בצדקה תכונני<sup data-n=\"631\">620</sup>, צדקה תרומם גוי<sup data-n=\"632\">621</sup> כו'. והענין הוא דכמו שא' גם כי יתנו בגוים כו' בפיזור הגופי' כך בפיזור הנפש החוטא' בקליפו' בז\"מ הרעות שהן ע\"ש<sup data-n=\"633\">622</sup> ד[קליפ'] נוגה, והתשובה היא הקיבוץ של הטוב מן הרע שלא יפרד ולא ידח ממנו נדח<sup data-n=\"634\">623</sup>. וזהו ענין קיבוץ גליות כשיעשו תשובה שלימה שעי\"ז יעלו מן הרע ויקבצו הטוב שנפל לשם ויוכללו כא' ע\"י ביטול רצון שיהי' בכולם כא' לשוב אל ה' אחד באמת למהוי אחד באחד ממש כנ\"ל ע\"י בירור דשם מ\"ה דח\"ע וח\"ת כו' וד\"ל. וזהו ג\"כ מה שא' שאין נגאלי' אלא בצדקה, כי הצדקה ה[י]א הפיזור לאביונים להחיות רוח שפלים<sup data-n=\"635\">624</sup> כידוע, [ו]זהו כזריעה זורע צדקו' שמצמיח ישועות<sup data-n=\"636\">625</sup> בריבוי גדול כו' כמו והלך לפניך צדקך כו', כך הוא בצדקה שעושי' ישראל בגלות כמו זריעה שעושה צמיחה רבה, והוא מה שא' שצדקה עשה ה' עם ישראל שפיזרן<sup data-n=\"637\">626</sup> בין אוה\"ע כזורע צדקות וכמ\"ש וזרעתי את ב\"י<sup data-n=\"638\">627</sup> כו' כי כד' רוחו' כו', ופיזור זה דצדקה הוא הגורם הצמיחה וגידול שהגדיל ה' לעשות עם אלה בקיבוץ הגליות שיגאלו בזכות הצדקה כמ\"ש צדקה תרומם גוי כו' בצדקה תכונני, שהן בכלל כל מעשה המצות שנק' צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"639\">628</sup> כו' כידוע שהוא הבירור בסוף מעשה דוקא, שלא המדרש עיקר<sup data-n=\"640\">629</sup> כו' וד\"ל.\n[כא] <b>והנה</b> מעתה יש להבין בענין שמונים פלגשי' שהן הברייתות ועלמות אין מספר אלו ההלכו' כו', דהנה מ\"ש וימררו את חייהם בעבודה קשה בחו\"ל זהו בעמל דתושבע\"פ כנ\"ל שזהו בעבודה קשה בקושיות וקו\"ח ובלבינים בליבון הלכתא כו', ומ\"ש ובכל עבודה בשדה זהו הברייתו' שהן",[["626","615","<b>כאיש א' חבירי'</b>: ס' שופטים כ, יא."],["627","616","<b>ויחן ישראל כאיש ישראל </b>[טז: ליתא]<b> א'</b>: יתרו יט, ב וברש\"י שם [ושם: ויחן שם ישראל — ראה לקמן כא, ד. פ' בשלח רל, ג. תרומה שטו, ג. תצוה שנג, ד. שסג, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תרמז]."],["628","617","<b>ברכנו כולנו כא'</b>: ע\"פ סיום תפלת העמידה."],["629","618","<b>אם ישראל עושי' תשובה נגאלים</b>: נסמן לקמן לז, א."],["630","619","<b>אין ישראל נגאלי' אלא בצדקה</b>: נסמן לקמן מו, ג."],["631","620","<b>בצדקה תכונני</b>: ישעי' נד, יד."],["632","621","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["633","622","<b>ע\"ש</b>: נסמן לקמן לז, ג."],["634","623","<b>ולא ידח ממנו נדח</b>: ע\"פ שמואל-ב יד, יד."],["635","624","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["636","625","<b>זורע צדקו' שמצמיח ישועות</b>: ע\"פ ברכת יוצר. ראה גם מאמרי אדה\"א שמות ח\"א ס\"ע יב ואילך."],["637","626","<b>שצדקה עשה. . שפיזרן</b>: ראה פסחים פז, ב."],["638","627","<b>וזרעתי את ב\"י</b>: ירמי' לא, כו. יאטזיז: בנ\"י — ראה לקמן פ' בשלח קלג, ג. משפטים רפא, ג. רפב, ב. מאמרי אדה\"א שמות ח\"ב ע' תקצט. הנחות תקע\"ז ע' יד ובהנסמן בהנ\"ל."],["639","628","<b>המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה לקמן פ' וארא פב, א. בשלח קסט, ד. קעה, ג. רמה, א. יתרו רנד, ד. משפטים רצו, א. תצוה שלה, ד. ויקהל תלב, ד. מאמרי אדה\"א ויקרא ח\"ב ע' עדרת־ נ\"ך ע' צה־ הנחות תקע\"ז ע' יט־ ש\"א יא, א. ובהנסמן בהנ\"ל."],["640","629","<b>שלא המדרש עיקר</b>: אבות פ\"א, מי\"ז [כגי' אדה\"ז בסידורו]."]]],[2300540921,"בחוץ [כ]עבודה בשדה שחוץ לעיר כו'. דהנה מבואר למעלה בענין סופר וספר וסיפור דסופר זהו שמביא בספר בכתב מן ההעלם דחכמה לגילוי באותיות מצומצמי' באופן שלא יהי' בו נטי' כלל אפי' כקש\"י מנקודת העומק והאמת ברצון ומקור החכ' כו', וכך הוא בסופרי' שסופרי' כל האותיות שבתורה ודורשי' עליהם שמביאי' מן ההעלם דאותיות הכתובי' בספר לגילוי אור בריבוי דברי' בע\"פ שנדרש על כל קוץ כו' ו[כ]ן במדו' שבתורה כו' כמו גם כל דקדוקי סופרי' וגזירות וסייגי' וכה\"ג. וכך יובן עוד בסופרי' אלה בתושב\"כ כך הן בח\"ת דתושבע\"פ בו\"ס משנה ששנו חכמים בלשון המשנה הרי שנו לתלמידי' בדרך קצרה מאד, דהיינו מה שהלבישו והעלימו בעומק חכמתם כל העומק ורוחב שיש בסברות וטעמי' בכל דין והלכה כמו שנמסרה בסיני ונדרשת מן המקראו' בכמה פנים שונים הכל בלשון קצר וק[ל] הזה השנוי בל' המשנה שיובן לתלמידי' הקטני' פסקי ההלכות בקצרה, אע\"פ שנעלם מן התלמיד כ[ל] מה שיש בהעלם והלבשה בתוך דברי' קצרים אלה, מ\"מ כאשר שונה המשנה הרי כלול בזה כל מה שיש בדברי' אלה כל פרטי הטעמי' וסברות ודרשו' שונים, כמו שהקורא באותיות שבתשב\"כ המצומצמי' יש בהן בהעלם והלבשה כל אור ושפע דח\"ע העליונה וגם מה שבא לגילוי בכל הדרשו' של התנאי' ואשר נמסר בע\"פ למשה כו' כמו מה שהי' ר\"ע דורש על כל קוץ כו', וכדוגמא זו יש באופן הלשון המצומצם וקצר בהלכו' דו\"ס משנה כל מה שיש בזה בהעלם מכל עומק ורוחב הפלפול וסברות ודרשות שמחדשי' הכל בלשון המשנה נכלל בקצרה כענין שא' לעולם ישנה אדם לתלמידו דרך קצרה<sup data-n=\"641\">630</sup> דוקא, דהיינו שבדרך קצרה זו יעלים וילביש כל הדרך הארוכה <span data-k=\"pg\">40</span> ּ העולה התמצית ומובחר מכל הפלפול כו'. ונמצא דלשון זה השנוי במשנה בקצרה נק' ג\"כ דברי סופרים כמו הסופרי' שכותבי' האותיות בספר כך הן מלמדי' דברי' בע\"פ ג\"כ בלשון וצרופי' בדבורים קצרים דוקא שהן מכווני' לאור האמת כמו שהוא בקיצור זה דוקא רק שזהו בבחי' סיפור בדברים בע\"פ כמו שנק' סופר באותיות שבכתב (ודוגמא לזה בספר וסיפור הנ\"ל הי' למעלה בח\"ע וח\"ת דעצמו' אא\"ס ממש דלתבונתו אין מספר כלל בי' הדברות שהי' מדבר בע\"פ שנכלל בזה ח\"ע הגנוזה בעצמותו ממש, וגם י' הדברות הללו הביאם בכתב בלוחות שהי' מכתב אלקי' ממש כמ\"ש והמכתב<sup data-n=\"642\">631</sup> כו', וא\"כ הרי הי' הקב\"ה בעצמו ובכבודו ממש בבחי' סופר להביא באותיות בכתב ומכתב חרות על הלוחות אותן י' הדברים שדיבר בע\"פ רק שקדם בחי' סיפור לספר כו' וד\"ל). ונמצא מובן דבחי' [סופר] שבתושב\"כ כמשה [ש]הי' סופר ומחוקק ותנאי' שסופרי' כל",[["641","630","<b>לעולם. . דרך קצרה</b>: פסחים ג, ב."],["642","631","<b>והמכתב</b>: תשא לב, טז."]]],[2300540928,"אותיות כו', זהו עצמו בחי' סופרי' בסיפור בתשבע\"פ שמדברי' בלשון קצרה מכוון לכל אור האמת כמו שהוא בח\"ע שבראש לענין סוף מעשה בהלכו' אלה דו\"ס משנה דוקא ע\"ד שנעוץ תחב\"ס וסב\"ת<sup data-n=\"643\">632</sup> והיו לאחדי' ממש (וכמו שמבואר למעלה דבחי' הממוצעי' האלה שמחברי' מח\"ע לח\"ת ספר וסיפור שרשם למעלה משניהם כו', דהיינו בעצמו' בעל הרצון והחכ' כו' כמשה שהי' ממוצע הראשון לחבר אוא\"ס בח\"ע, כך ממוצע זה השני דת\"ח במשנה שמחברי' מח\"ע דאותיות התושב\"כ לתושבע\"פ גבוהים משניהם כמשה עצמו כו', וע\"כ יש ביכולתם להלביש במשנה כפי נקודת האמת שבתושב\"כ ובתושב\"כ מלובש מנקוד' החכמה העצמי' כמו שהיא בעצמו' ממש).\n<b>והנה</b> כ\"ז הוא באמצעו' החיבור והקשר דמדות דח\"ע במדו' דח\"ת שבדבור שהן ו' מדות שבמל' שהן ו\"ס משנה שהוא בבחי' חג\"ת כו' שנק' גופי תורה והיינו במדות שבאי' בגילוי בדבור שמתאחד במוחי' דחו\"ב כו', אבל הברייתות ל' בראי שהן לבר מגופא שהן המדו' שבעצם כחג\"ת כו' שהן בלב שנק' גופא ולבר מגופא זהו כמו הירכיים שהן טפלי' לגוף ומשמשי' אליו להוליך האדם ממקום למקום ואינם מעיקר האדם כ\"כ (והוא בחי' חיצוני' דנו\"ה, דגם שו\"ס משנה הן ו' מדות דהיינו חג\"ת נה\"י שהן ו' סדרים בפרט חסד בס' זרעים כו' זהו פנימי' דנו\"ה, כידוע שמדות הנמשכים בלב מן השכל שבמוח לחסד או לדין או לממוצע והכרעה זהו המדות כמו שהן בעצם, אבל בחי' נו\"ה זהו בחי' התפשטותן לפסוק למעשה אם מחסד זה ראוי לעשות כך שבודאי מיד שיטה לבו ודעתו לחסד ידון למעשה כך וכן להיפוך במדה\"ד וזהו נו\"ה שבפנימי' שמתאחד בגופא כו'. אבל נו\"ה החיצוני' הוא כאשר יבא לד[ו]ן למעשה בפו\"מ כמו להורות לזולתו שהביא לפניו שאלה אז צריך שיתיישב מחדש בדעתו ולבו אם יורה לו למעשה כך אם לאו, וזהו שנק' כליות יועצות בנו\"ה<sup data-n=\"644\">633</sup> הן או לאו ונק' מאזני צדק<sup data-n=\"645\">634</sup>, ששוקל מחדש במאזני השכל ומדות שבלב בנו\"ה ועדיין לא בא להורות למעשה אלא מתייעץ אם יפסוק למעשה, נק' כליו' שלמעלה מן הירכיי'. וצריך לזה ג\"כ בחי' ממוצע להביא ולחבר העליון בתחתון שזהו מבחי' המדות שבדיבור כששונה הלכה לעצמו לפסוק כך וכך כשבא להביא לענין המעשה בפו\"מ (כמו הממוצע מן מדו' שבחכ' בראש למדות שבלב בדיבור שנק' תנאי' וסופרי' כנ\"ל), והן הברייתות שהן באי' לפרש המשנה איך שיופסק להלכה למעשה שהן כמו הירכיי' שלבר מגופא כנ\"ל שהן מוליכי' לאדם כו', <span data-k=\"pg\">כ</span> ּ והילוך נק' מעשה שאינו הולך רק לעשות כך המדו'",[["643","632","<b>שנעוץ תחב\"ס וסב\"ת</b>: נסמן לקמן מד, ד."],["644","633","<b>כליות יועצות בנו\"ה</b>: ברכות סא, א. ראה זהר [אד\"ז] האזינו רצו, א. הנסמן במאמרי אדה\"א קונטרסים ע' רכד."],["645","634","<b>בנו\"ה. . מאזני צדק</b>: קדושים יט, לו. ראה ת\"ז בהקדמה [יז, ב ובניצוצי זהר שם]. שעה\"י קכה, א ובהערה 4. פיה\"מ עח, רע\"א."]]],[2300540935,"שבנו\"ה שבחיצוני' הוא להביא להורות למעשה מן המשנה זהו<sup data-n=\"646\">635</sup> הברייתות בעבודה בשדה שמביא מן העיר לשדה (כמשי\"ת).\n<b>דהנה</b> הברייתות זהו שחידשו ר\"ח ור\"א<sup data-n=\"647\">636</sup> מפי רבי<sup data-n=\"648\">637</sup> ולא קבעום רבי במשנה אלא ר\"ח ור\"א הוסיפו אותם על המשנה ונשנו בלשון קצר כמו המשנה ונק' תניא כמו המשנה שהוא בלה\"ק, ובל' תרגום תני[א] ומתני', לפי שהמשנה אינו אלא שאו' דבר ששמע ונאמר כבר נק' שונה בלה\"ק כשונה הדבר ומכפל (כמו ויצוק וישנה וישלש<sup data-n=\"649\">638</sup> כו' וכמו משנה למלך<sup data-n=\"650\">639</sup> כו', דהיינו שני לו שהשני זהו לפי שכופל כמו ועל השנות החלום פעמי'<sup data-n=\"651\">640</sup> כו', וכן משנה תורה לפי שהואיל משה לבאר את התורה לחזור פעם שנית כו', כך השם דמשנה ששונין הלכות לפי שחוזרי' ע\"ד שכבר כתוב בתושב\"כ ולומדי' משם (ובל' ארמי תני או מתני, ולכך נק' המשנה מתנית' והשוני' משנה נק' תנאים כידוע), ומבואר למעלה דתניא אותיות איתן כמו תנאי' הן א[י]תני' מוסדי ארץ (כמו אברהם שנק' איתן כמ\"ש משכיל לאיתן האזרחי<sup data-n=\"652\">641</sup> כמ\"ש בדרז\"ל (וזהו שמעו הרים ריב ה', הרים עליונים שהן מדות<sup data-n=\"653\">642</sup> דח\"ע ורצה\"ע דתושב\"כ, ואתני' מדות דח\"ת דארץ תושבע\"פ), דאיתן ל' תוקף וחוזק כמו איתן מושבך וכתרגומו תקיף מותבך כו' וכן נחל איתן<sup data-n=\"654\">643</sup> שהוא קשה ותקיף כו') וכתיב משכיל לאיתן שהוא אותיות דתניא בבחי' ברייתות, לפי שתוקף גדול זה שבתנאי' שנק' אתנים מבחי' סופר הנ\"ל נמשך הוא גם בברייתות שלבר מגופא שנק' תניא אותיות איתן שמפני זה אמר משכיל לאיתן כמו משכיל אל דל כו' שמפקח למרחוק ושפל ממנו כדל ועני כו', כך לבר מגופא בבחי' נו\"ה<sup data-n=\"655\">644</sup> נמשך בשביל חיצוני' במעשה ממקור הח\"ע העצמי' הנ\"ל שנק' משכיל כנ\"ל וד\"ל. וכמו שבירכיי' שהן נו\"ה החיצוני' כנ\"ל יש בהן כח וחיזוק [ה]גדול שבמקור החכ' ורצון העצמי' ואדרבה נעוץ תחב\"ס דוקא (וכמ\"ש במ\"א עמ\"ש וגם נצח ישראל<sup data-n=\"656\">645</sup> כו' שזהו נשמ' שמואל הנביא שתיקן לפגם דירך יעקב שהוא כמו [ב]גלות האחרון הזה שנפגם הנצחון באוי\"ר ששייך למעשה לבד כענין ברייתות הנ\"ל שנק' פלגשים (כמשי\"ת). ובדרך כלל זהו כמו ההפרש בין אברי' הפנימי' לאברי' החיצוני' כך הוא ההפרש בין משנה לברייתא, שהמשנה היא בבחי' אברים הפנימיי' (כריאה ולב שהקול ודיבור יוצא משם, וגם מה שנמשל למזון ולחם הרי ידוע דהגירסא זהו שטוחן בשיניו<sup data-n=\"657\">646</sup> ומתעכל במעיו כמ\"ש ותורתך בתוך מעי שנעשה מזה אור וחיות פנימי' לנשמה כידוע), אבל הברייתא הוא בבחי' אברי' החיצוני' כרגל וירכיי' שמוליכי' לגוף להביא למעשה כנ\"ל (שהוא מה שא' דאיהו בנצח",[["646","635","<b>זהו</b>: יאיז: והן. יח: וכן."],["647","636","<b>הברייתות. . ר\"ח ור\"א</b>: ראה חולין קמא, סע\"א ואילך. רש\"י ולקו\"ש שבהערה הבאה."],["648","637","<b>הברייתות. . מפי רבי</b>: ראה רש\"י תענית כד, א ד\"ה דבי ר' חייא. וראה גם לקו\"ש עקב [כרך יט] ע' 111 ובהנסמן לשם."],["649","638","<b>ויצוק וישנה וישלש</b>: מלכים-א יח, לד [ושם: ויצקו. . וישנו. . וישלשו]."],["650","639","<b>משנה למלך</b>: אסתר י, ג."],["651","640","<b>ועל השנות החלום פעמי'</b>: מקץ מא, לב [בדילוג]."],["652","641","<b>אברהם. . משכיל לאיתן האזרחי</b>: תהלים פט, א. בבא בתרא טו, א. וראה רש\"י תהלים שם. מלכים-א ה, יא."],["653","642","<b>שמעו הרים. . מדות</b>: מיכה ו, ב [בדילוג]. ראה זהר (סבא) משפטים קט, ב ובמפרשים שם. מאמרי אדה\"א שמות ח\"ב ע' תיב. וש\"נ. שה\"א פס\"ח. לקמן פ' בא צ, ג, קט, ד. קיז, א. בשלח קצא, ב. קצט, ד."],["654","643","<b>נחל איתן</b>: ראה סוטה מה, ב (במשנה). מו, סע\"א. רש\"י פ' שופטים כא, ד."],["655","644","<b>נו\"ה</b>: זיח: נה\"י."],["656","645","<b>וגם נצח ישראל</b>: שמואל-א טו, כט. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' תכ ואילך. תקס\"ח ע' שסה. מאמרי אדה\"א שמות ח\"ב ע' תקד ובהנסמן שם."],["657","646","<b>דהגירסא זהו שטוחן בשיניו</b>: ראה גם לקמן פ' וארא סז, ב. בא קכה, א. מאמרי אדה\"א בראשית ס\"ע תפד ואילך."]]],[2300540942,"ואיהי בהוד<sup data-n=\"658\">647</sup>, דכמו שאיהו אמת בתושב\"כ ואיהי אמונה במדו' שבחכ' שבדיבור בתושבע\"פ שלא יוסיף ויגרע מנקוד' האמת כאיש אמונה לשולחו או לאדונו, כך איהו בנצח שנמשך הרצה\"ע וח\"ע שבתו' לסוף מעשה בנצח דימין ואיהי בהוד שהן הברייתות כנ\"ל), וכמו שמאיר אור דח\"ע בח\"ת במדות שבדבור בפנימיות שנק' תורת האדם בפנימי' דנש\"י כך הוא נמשך מן הפנימי' דאדם לחיצוני' האברים שהן הברייתות שזהו כמו שאדם הולך מעיר לשדה (כמשי\"ת). ולכך נק' הברייתות פלגשים שאין היחוד בהן רק לפרקים כנ\"ל ובלא חופו\"ק, והלכות דמשניות מאיר בהן מח\"ע ביחוד תמידי וכאשה מאורסה בחופו\"ק כמ\"ש תורה צוה לנו משה מורשה מאורסה<sup data-n=\"659\">648</sup> כו'.\n<b>וביאור</b> ענין זה מובן מכל הנ\"ל דבלשון המשנה נשנה בדרך קצרה <span data-k=\"pg\">42</span> ּ ויש בלשון זה בהעלם כמה הלכות ועניני' חדשי' והן הן ההלכות השנויות כברייתות שחיברו ר\"ח ור\"א, ואין זה חידוש מעיקרו ממש אלא מה שכבר שנוי במשנה רק שלא נא' בפירוש אלא נכללי' בדברי המשנה בהעלם והלבשה בדרך קצרה ור\"ח ור\"א הוא שהוציאו לאור בגילוי מבחי' ההעלם שבמשנה להיות במהות דבר בפ\"ע כאלו הן דברים חדשים ממש (וזהו כמו שהולך השפע מאברי' הפנימי' כריאה ולב וכבד ומעיי' לאברים החיצוני' אחר עיכול המאכל כו' ע\"י גידי' רוחניי' להתפשט בדם האברי', וזהו כמו שהירכיים שמוליכי' למקום אחר כך הברייתות מוציאי' מהעלם המשנה שנשנה שם להלביש הדבר באופן אחר כמו שמוליכי' התבואה מאוצר שבביתו לשדה לעבוד עבודה בשדה כו'. וראי' לזה ממה שא' באילפא שהי' תלמיד רבי<sup data-n=\"660\">649</sup> שכל מאן דתני לי' בברייתא דר\"ח ור\"א פשיטנא לי' ממתני'<sup data-n=\"661\">650</sup> כו', וענין פשיטנא לי' היינו שימצא דבר זה מופשט לבירור דבר מן המשנה, שיוציא לאור דבר זה מן העלם דברי המשנה ואין כל חדש בבריית' זו דר\"ח ור\"א כי ימצא הלכה זו במשנה, כי שרש הברייתו' נכללי' במשנה בהעלם מטעם הנ\"ל וד\"ל (וכמו שחיות האברי' חיצוני' נכללי' ונגררי' אחר חיות פנימי' האברים כלב וריאה וכבד וכה\"ג כנ\"ל) והיינו לפי שבחי' מקור הח\"ע שבראש שמאיר בו' מדות שבדבור בו\"ס משנה הוא שנמשך גם לברייתו' שהן בירכיים בבחי' נו\"ה החיצוני' שלבר מגופא כנ\"ל). ולכך הי' שמו אילפא לשון אולפנא<sup data-n=\"662\">651</sup> תרגום דלימוד, כמ\"ש וכל בניך למודי הוי' מח\"ע לח\"ת, ואילפא זה הי' שרשו מנשמ' רבי שקיבל איש מפי איש עד הזוגו' מאכה\"ג עד משה שציוה לנו כו' כנ\"ל, לכך הי' בקי ומבין במקור דח\"ע שנדרש בהלכו' דמשנה להביא זה בגילוי בהלכו' דברייתות",[["658","647","<b>דאיהו בנצח ואיהי בהוד</b>: ראה ע\"ח (שער אנ\"ך) שי\"ט, פ\"ט. מאמרי אדה\"ז הקצרים ע' ה. תקס\"ז ע' נט ואילך. לקו\"ת שה\"ש כח, ב ובהנסמן במ\"מ לשם."],["659","648","<b>תורה צוה. . מאורסה</b>: ברכה לג, ד. ברכות נז, א."],["660","649","<b>באילפא שהי' תלמיד רבי</b>: ראה תענית כד, א. מאמרי אדה\"א ויקרא ח\"א ע' קטו."],["661","650","<b>באילפא. . פשיטנא לי' ממתני'</b>: ראה תענית כא, א."],["662","651","<b>אילפא לשון אולפנא</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קטז."]]],[2300540949,"מתוך המשנה שלא הי' זה ביכולת לתלמיד אחר זולתו וזהו אאלפך חכמה<sup data-n=\"663\">652</sup> (כמ\"ש במ\"א באריכות). וזהו ובכל עבודה בשדה אלו הן הברייתות שזהו כמו עבודה קשה בשדה חוץ לעיר שהיא עבוד' נכרי' חוץ לביתו כמו שמביא חטים מביתו וזורע בשדה שצריך עבודה בפ\"ע, משא\"כ ברכת הון ביתו וכל אשר לו בביתו, שברכת של עבודה בשדה נבדלת מעבוד' שבביתו ששם עיקר הברכה כמ\"ש להביא ברכה אל ביתך<sup data-n=\"664\">653</sup>, כך התורה נק' בית ואהל ונק' הון ביתו והיינו תשב\"כ ושבע\"פ ומה שיוציא חוץ לבית דתורה לשדה זהו ענין הבירורי' שבחוץ כמו בבחי' נו\"ה שלבר מגופא שנמשך בריחוק מקום וגם<sup data-n=\"665\">654</sup> חוץ למקומו כו', ולכך אע\"פ שגם לימוד המשניות נק' עבודה קשה בחו\"ל, אבל זהו במקומו דהיינו כמו שהוא בעצם אור דחכ' שבחכ' יבנה בית כו' והון ביתו ורכושו שנתברך ממקור דח\"ע כמו בחכ' שבדיבור שמתאחד עם חכ' שבראש כנ\"ל אע\"פ שצריכי' גם הן בירור ונק' ליבון הלכתא (כמשי\"ת). משא\"כ [ה]עסק בברייתו' שהן הלכות שמסתעפי' מן המשנה שבהעלם נק' עבודה בשדה (כמו והנה אנחנו מאלמים אלומים בשדה<sup data-n=\"666\">655</sup> כו' כמ\"ש בזהר ע\"פ ואם בשדה מצאה<sup data-n=\"667\">656</sup> שיש שדה חרובי'<sup data-n=\"668\">657</sup> דק\"נ ויש שדה אשר ברכו<sup data-n=\"669\">658</sup> ה'). ולפי הנ\"ל בענין הירכיי' שהן בחיצוניו' דנו\"ה שמביא לידי מעשה כו' זהו עכשיו בגלות האחרון הזה שהוא בבחי' ירכיי'<sup data-n=\"670\">659</sup> כמ\"ש בזהר והוא לתקן הפגם דירך יעקב בג\"ה<sup data-n=\"671\">660</sup> כנ\"ל, והיינו ענין הנצחון בעבודה אלקי' באוי\"ר שאינו רק למעשה המצות בלבד כידוע, וזהו שנק' עבודה בשדה דוקא בהילוך חוץ למקומו כנ\"ל.\n<span data-k=\"pg\">כא</span> ּ[כב] והנה מעתה יש להבין מ\"ש ועלמות אין מספר אלו ההלכות, ובודאי אין הכוונה על הלכות שבמשנה וברייתא שיש להן מספר כמ\"ש ס' מלכות ופ' פלגשי' כו', אלא הלכות אלו שמחדשי' בתלמוד שלנו שהוא תלמוד בבלי והן מימרות האמוראי' וחידושי דינין שמחדשי' ע\"י הפלפול בקושיות ותירוצי' רבים כמו ת\"ש ורמינהי מתקיף לה וכה\"ג, שע\"ז א' במחשכי' הושיבני זה תלמוד בבלי וכנ\"ל. וביאור הדבר<sup data-n=\"672\">661</sup> הנה מבואר למעלה דכל הלכות דמשנה שסידר רבי הכל הי' מקובל איש מפי איש עד הזוגות ואנכה\"ג עד יהושע מפי משה שתורה צוה לנו כו', דהיינו שהי' נמסר בע\"פ ברור וצלול כל דין והלכה כמו שה[ו]א בלי נצרך לזה עיון ופלפול<sup data-n=\"673\">662</sup> כלל, והגם שהי' להם דרשות רב[ות] בכתובי' ודיני המדות שבתורה הכל הי' בבירור גמור בלי בלבול ותערובות ובלי מחלוקת כלל, לפי שאור דח\"ע מאיר בח\"ת בתשבע\"פ אפי' בדקדוקי סופרי' שהן הוסיפו על",[["663","652","<b>אאלפך חכמה</b>: איוב לג, לג [ושם: ואאלפך — ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו. לקמן פ' בשלח רמו, ד]. ראה מאמרי אדה\"א דברים ח\"א ע' רכד ואילך ובהנסמן לשם."],["664","653","<b>להביא ברכה אל ביתך</b>: יחזקאל מד, ל [ושם: להניח — ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשמה]."],["665","654","<b>וגם</b>: יאטזיז: ליתא."],["666","655","<b>והנה אנחנו. . בשדה</b>: וישב לז, ז [ושם: בתוך השדה]."],["667","656","<b>ואם בשדה מצאה</b>: תצא כב, כה [ושם: ימצא — ראה מאמרי אדה\"א דברים ח\"ב ע' תרג]. כב, כז [ושם: כי בשדה]. ראה זהר ח\"ש קכב, סע\"א [ושם ע\"ב מובא הכתוב בי בשדה מצאה]."],["668","657","<b>חרובי'</b>: יאטז: חרוב. בזהר שם: חירוב."],["669","658","<b>שדה אשר ברכו ה'</b>: תולדות כז, כז."],["670","659","<b>בגלות. . ירכיי'</b>: ראה זהר פקודי רנח, א."],["671","660","<b>בג\"ה</b>: בגיד הנשה. יאיזיח: בנו\"ה."],["672","661","<b>וביאור הדבר</b>: ראה גם להבא להלן מאמרי אדה\"א ויקרא ח\"א ע' קו ואילך."],["673","662","<b>כל דין והלכה. . בלי. . ופלפול</b>: ראה גם לקמן פ' ויקהל תכד, א. שע\"ת קלו, ד. ש\"א כד, א. מאמרי אדה\"א ויקרא שם. וש\"נ. קונטרסים ס\"ע תקמב ואילך."]]],[2300540956,"התורה [כ]עירובין ונט\"י כו' כמו אור המאיר למרחוק ובהדלקת נר מנר שלא יפול שינוי ותערובו' כלל עד שמאי והלל שהיו מחולקי' בקצת דברים<sup data-n=\"674\">663</sup> ותלמידיהם אחריהם שנחלקו ברוב דברים<sup data-n=\"675\">664</sup>. ולזאת סידר ר' את המשנה לכל מחלוקת שהי' עד דורו והעמיד בל' קצרה וברורה והן ס' מסכתות שנק' ס' מלכות כנ\"ל דמתני' מלכתא כו' כמלך שגוזר וכן יקום למעשה. אך גם במשניות עדיין אין הלכה פסוקה וברורה לגמרי כי יש ריבוי קושיות וסתירות מזו לזו ובמחלוקת שנוי' ולא ידוע הלכה כמי וגם הדברים סתומים וקצרים וצריך לבאר ולפרש המשנה להעמיד כל הלכה ומחלוקת בתירוצי' וחילוקי' שונים עד שכל דבר דין והלכה יעמוד על מקומו באופן ברור למעשה, וזהו כל עיקר ענין התלמוד שנק' שמוש ת\"ח כידוע שמקשה ומפרק הרבה וממילא יתורץ ויוברר כל דין והלכה על בורי' בלי קושיא ובלבול כלל. וזהו שנק' באמת ליבון הלכתא שמלבן מן העכרורי' שהוא הבלבול מתערובות זר ושקר וטעות שהן הקושיות ומתרץ הכל ע\"י היגיעה ועמל רב שנק' עמל תורה [כנ\"ל] שמטריח כל עצמיות כח השכל בעיון ופלפול רב עד שיבא ע\"ד האמת ממש, שזהו מה שיוציא לאור מן החושך, והאמת מן השקר וטעות ובלבול, שהוא כאור שמאיר לחשך דוקא, או כדבר שמלבנו מן העכרורי' כפשתן בליבון וגיהוץ ברחיצה ושפשוף כו' עד שמתלבן ביותר וזהו ליבון הלכתא (כמ\"ש כעדר הרחלים שעלו מן הרחצה בליבון ביותר כך הלכו' נק' נימין ושערות כידוע, ושיניך הן ל\"ב שיני'<sup data-n=\"676\">665</sup> טוחני' בגירסא ובעיון כו') וכמ\"ש במ\"א במ\"ש ולבן שינים מחלב<sup data-n=\"677\">666</sup> כו'. ונמצא שע\"י היגיעה ועמל בפלפול שבתלמוד (שהי' זה אחר המשניו' דר' וברייתות דר\"ח ור\"א והוא בימי רב ושמואל ור' יוחנן שהיו מיד בתחלת אלף החמישי<sup data-n=\"678\">667</sup> בחי' הוד<sup data-n=\"679\">668</sup> דאיהי בהוד ובינה עד הוד<sup data-n=\"680\">669</sup> כו' (ובתחלת אלף הששי היו הרמב\"ן ורשב\"א ורא\"ש<sup data-n=\"681\">670</sup> אחר הרמב\"ם ובע\"ת הראשוני') ועד רב ושמואל הי' עדיין אור המאיר בח\"ת בנו\"ה שלבר מגופא כברייתות שנק' פלגשי' כנ\"ל) נהפך מחשך לאור, כי הפלפול בריבוי הקושיו' מעלים כחושך ממש וזהו במחשכים הושיבני כו', והבירור וליבון הלכות מתוך הפלפול כהויו' דאו\"ר ורבינא ורב אשי זהו כאור היוצא מן החשך ממש והוא כאור המאיר בלילה וחושך (וכלבינה שנעשה מעפר שנשרף בכבשן כנ\"ל במ\"ש ותהי להם הלבינה לאבן כו' והוא מדיבורי' <span data-k=\"pg\">44</span> ּ של חול בכל לשון כו' משא\"כ אותיות [דתושב\"כ] שנק' אבני קדש בעצם כו' וד\"ל).",[["674","663","<b>שמאי והלל. . בקצת דברים</b>: ראה שבת יד, ב. טו, א. לעיל יא, סע\"ג. מאמרי אדה\"א ויקרא שם."],["675","664","<b>ותלמידיהם. . ברוב דברים</b>: ראה סוטה מז, סע\"ב."],["676","665","<b>ל\"ב שיני'</b>: ראה ע\"ח (שער העיבורים) שכ\"ח, פ\"ה. מבוא שערים ש\"ה, ח\"ב פ\"ו. פע\"ח (שער העמידה) ש\"ט, פ\"א. אוה\"ח לזהר (רע\"מ) פינחס רנו, ב ד\"ה והרח\"ו (קה, סע\"ג ואילך). עמה\"מ שער עולם התהו פל\"ח (כב, ד). פס\"ח (לט, א). של\"ה שער האותיות אות ק' עב, א. מדרש תלפיות מערכת אברים (י, א) ד\"ה אמר המאסף. תו\"ח ויחי רלט, ג ובהערה 51. לקמן פ' בא קכה, א. ויקהל תטז, ד."],["677","666","<b>ולבן שיניים מחלב</b>: ויחי מט, יב. ראה מאמרי אדה\"א בראשית ע' תקעד."],["678","667","<b>רב ושמואל ור' יוחנן. . אלף החמישי</b>: ראה סדר הדורות בערכם."],["679","668","<b>אלף החמישי בחי' הוד</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' תיט ואילך. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. ח\"ג ע' תתה ובהנסמן בהנ\"ל. לקמן פ' בשלח רכא, ב ואילך."],["680","669","<b>ובינה עד הוד</b>: ראה זהר (רע\"מ) פינחס רכג, ב. לקמן פקודי תנא, א. אמ\"ב שער התפילין קכ, ד. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקפה."],["681","670","<b>אלף הששי. . הרמב\"ן ורשב\"א ורא\"ש</b>: ראה סדר הדורות בערכם."]]],[2300540963,"<b>והנה</b> לפ\"ז הרי יובן עכ\"פ שמאור דח\"ע שבתושב\"כ אינו מאיר רק למדות דח\"ת שבו\"ס משנה בהלכות שיש להן שרש ומקור ממשה במה שציוה לנו תורה זו מורשה מאורסה כו', וכן מתגלה עוד למטה בברייתות שנמשך מהעלם דמשנה (ונק' נו\"ה כירכיי' כנ\"ל) שזהו שנק' מלכות ופלגשי' שיש גם בהן יח\"ע לפרקי'. אבל הלכות אלו שמתחדשי' ע\"י פלפול בתלמוד בקושיות ופירוקי' וכמימרות האמוראי' עד רבינא ור\"א סוף הוראה<sup data-n=\"682\">671</sup>, לא מאיר בהן מאור דח\"ע ולא נק' מלכות ולא פלגשי' כברייתו' דר\"ח ור\"א (וראי' לזה ממה שא' בכמה דוכתי בגמ' דממתני' וברייתא מותבינן תיובתא אבל ממימרו' האמוראי' (וגם מברייתא דלא מיתניי' בי ר\"ח ור\"א<sup data-n=\"683\">672</sup> לאו מתניתא היא) לא מותבינן תיובתא כלל, וכמו שא' בכמה דוכתי גברא אגברא קא רמית<sup data-n=\"684\">673</sup> כו'), אלא נק' בשם עלמות כמ\"ש ועלמו' אין מספר אלו ההלכו' סתם שלא נזכרו במשנה וברייתא כלל וכמימרות האמוראי' שחידשו מעצמם (אע\"פ שדורשי' גם הם מן המקראו' כתנאי' ממש כמו מנלן א' קרא כו' מ\"ט דר\"פ כו' ולא נחשבו כהלכות דמתני') (ולא נק' אמוראי' אתנים ולא [כ]תנא[י'] דברייתא ולא סופרי' כו'). וזהו פלא גדול לכאורה דהלא עיקר ההוראה האמיתי' להלכה למעשה אף בהלכות ודיני' שנז' במשנה וברייתא אינו אלא ע\"פ סוף המסקנא שבגמ' אחר שמברר ומלבן ההלכו' שבמשנה מכל קושיא וסתירה כנ\"ל כמו ורמינהי ומתרץ ל\"ק כו'. וראי' לזה שאין מורין מן המשנה<sup data-n=\"685\">674</sup> אלא ממסקנא דשמעתתא שנק' שמוש ת\"ח שזהו העיקר ויסוד דמשנה כידוע. ומזה הטעם אמרו דעוסק במקרא מדה ואינו מדה במשנה מדה ונוטלי' עלי' שכר אבל בתלמוד אין לך מדה גדולה הימנה<sup data-n=\"686\">675</sup> כו' (וגם בס' הקבלה א' דמקרא בעשי' ומשנה ביצי' ותלמוד בבריאה<sup data-n=\"687\">676</sup> כו' וידוע דמעלת הבריאה למעלה מיצי' שבחי' חב\"ד בבריאה דאימא מקננא בכורסיי' כו' וחג\"ת ביצי' (דז\"א מקנן ביצי'<sup data-n=\"688\">677</sup> ) ונה\"י בעשי' כו', וא\"כ התלמוד גדול מן המשנה והמקרא (וגם נמנו וגמרו דתלמוד גדול מן המעשה<sup data-n=\"689\">678</sup> לפי שהתלמוד מביא לידי מעשה שאינו רק בתלמוד בבלי שהוא עיקר ויסוד ההוראה אף בדיני המשנה וכ\"ש במה שחידשו הם בפלפול עד רבינא ור\"א שנק' סוף הוראה שנקבע לדורות כהלמ\"מ ממש כו').\n[כג] <b>אך</b> הנה מבואר למעלה בבחי' ספר וסיפור דתושב\"כ ושבע\"פ שזהו בבחי' איש ואשה משפיע ומקבל כמו שא\"א לאשה להזריע ולהוליד כ\"א ע\"י איש שממשיך מ\"ד כח",[["682","671","<b>רבינא ור\"א סוף הוראה</b>: ראה בבא מציעא פו, רע\"א."],["683","672","<b>דלא מיתניי' בי' ר\"ח ור\"א</b>: ראה חולין קמא, סע\"א ואילך. ירושלמי עירובין פ\"א, ה\"ו."],["684","673","<b>גברא אגברא קא רמית</b>: עירובין פב, א."],["685","674","<b>שאין מורין מן המשנה</b>: סוטה כב, א."],["686","675","<b>דעוסק במקרא. . גדולה הימנה</b>: ראה בבא מציעא לג, א."],["687","676","<b>דמקרא בעשי'. . בבריאה</b>: נסמן לקמן כא, א הערה 858."],["688","677","<b>דז\"א מקנן ביצי'</b>: ראה ת\"ז ת\"ו (כג, א). מאמרי אדה\"ז הקצרים ע' תקנב. הנסמן במאמרי אדה\"א נ\"ך ע' יד."],["689","678","<b>דתלמוד גדול מן המעשה</b>: קידושין מ, ב. ראה גם לקמן פ' תצוה שלו, א."]]],[2300540969,"העצם של הולד וגם כח הבירור וגידול כו' ובנוק' הוא המקבל הוא<sup data-n=\"690\">679</sup> בחי' כח המגדל ומצמיח ומברר כו', וכך הוא באור ושפע דתושב\"כ שנק' פנים מאירות באותיות שנק' אבני קדש העליון שמאירי' לתושבע\"פ שנק' אשה בחי' מקבל שהוא חכ' שבדיבור שנק' סיפור ונק' פנים מסבירות שמסביר להרחיב הדברים שיצאו בקיצור ותמצית מפני' מאירות אור דתושב\"כ, והיינו בדרשות שלהם שסופרי' כל אות ואות כו' כנ\"ל ומבררי' כל המצות בפרט עד דקדוקי סופרי' כו'. וזהו ששים המה מלכות ס' מסכתות שההשפעה הזאת הנמשכת מן המשפיע שהוא אותיות דתושב\"כ הוא רק מבחי' המדות דח\"ע בחו\"ג שהן רמ\"ח מ\"ע ושס\"ה ל\"ת בכלל והוא שנק' תורה אור להורות ולהבדיל בין טו\"ט בכלל, והן מדות דח\"ע (שנק' טורי <span data-k=\"pg\">כב</span> ּ נהורא<sup data-n=\"691\">680</sup> דאור דח\"ע) ומאירי' לדבור במדות שבה שהן ו\"ס משנה שכל א' כלול מי' שהן ס' מסכתות ופ' פלגשים בנו\"ה החיצוני' כנ\"ל, ובחי' הממוצע המחבר מח\"ע לח\"ת מספר [ל]סיפור זהו שנק' סופרי' כנ\"ל ששרשו בבחי' סופר שלמעלה מספר כנ\"ל. אך כ\"ז בבחי' שפע דאור הח\"ע במדות לבד, אבל למעלה מן האור ושפע דחכמה מאין ליש באותיות ומדות הרי היא בבחי' ההעלם דעצמו' ומקור החכ'<sup data-n=\"692\">681</sup> כמו שהוא בבחי' אין והעלם ממש שאינו נק' אור כלל, דמ\"ש ותורה אור זהו שבא מבחי' מאור מקור כל אור שבא בדרך העלם וחשך תחלה שמעלים אור העצמו' ואח\"כ א' יהי אור<sup data-n=\"693\">682</sup>, אור דח\"ע שיתגלה מן ההעלם וכמ\"ש ישת חשך סתרו וכן א' ומשה נגש אל הערפל<sup data-n=\"694\">683</sup> אשר שם האלקי', ומה שיורד אור דחכ' זהו בחי' צמצום לגבי העלם כח המקור דכל חכ' שכלול בהעלם העצמו' ממש שא' בזה לתבונתו אין מספר כלל וחכים ולא בחכ' ידיעא כלל, רק שעכ\"ז אור זה המצומצם בא בדרך בירור שהוברר בחי' תמצית הנבחר כאור בהיר, שזהו כחכם גדול בעומק העלם החכ' שמברר איזה שכל ומביאו לאור בגילוי אותיות שבהן מכוון בחי' עומק דחכ' זו, וכמו הענין דסופר שמביא בספר באותיות מצומצמי' מכווני' לנקוד' אור האמת הנברר מכל העומק וההעלם דמקיף דחכ' זו כו' (והוא קו המדה שמודד כל אור בכלי רק כפי האר' אור דח\"ע).\n<b>ו</b>[ז]הו שרש ענין התלמוד שהוא בבריאה שנק' חשך שלמעלה מן המשנה שהוא ביצי' שנק' אור כמ\"ש יוצר אור ובורא חשך<sup data-n=\"695\">684</sup>, הרי האור ביצי' שבאה בגילוי מן ההעלם כאותיות הדיבור מן המח' שבהעלם, והחשך הנעלם בבריאה כו'. והענין הוא לפי שעיקר ענין התלמוד הוא בבחי' הפלפול שבא להעלים האור דחכ' שכבר האיר מספר לסיפור במשנה ומקשה ומפרק כנ\"ל, שזהו שמעלה לשכל ואור זה שבא במדות טו\"ט או\"ה כו\"פ מח\"ע דתשב\"כ למעלה מן השכל שבמדות, כי גם אור דחכ' דתושב\"כ אינו רק במדות להורות ולהבדיל כו', והוא כמו שמעייני' בעצם כח המושכל בשרש וטעם הענין כמו שהוא טרם",[["690","679","<b>הוא</b>: יאיזיח: ליתא."],["691","680","<b>טורי נהורא</b>: ראה זהר פינחס רמט, ב. מאמרי אדה\"א שמות ח\"א ע' פח. וש\"נ. שעה\"י קכז, ב ובהערה 31. לעיל ה, ב. לקמן פ' בא קט, ד. בשלח קצט, ד. משפטים ש, ג. תצוה שסא, סע\"א ואילך."],["692","681","<b>החכ'</b>: יח: הח\"ע."],["693","682","<b>יהי אור</b>: בראשית א, ג."],["694","683","<b>ומשה נגש אל הערפל</b>: יתרו כ, יח."],["695","684","<b>יוצר אור ובורא חשך</b>: נסמן לקמן פ' בשלח קמד, ג הערה 41."]]],[2300540975,"שיפס[ו]ק מזה לחסד או לדין כו' שה[ו]א עצם המושכל שיכולי' לדון ממנו דבר והיפוכו, וזהו עיקר הפלפול שמקשה על עצם הדבר למה הוא כך ולא היפוכו (כמו ר\"מ שהי' או' על טמא טהור ומראה לו פנים<sup data-n=\"696\">685</sup> (כמו שהי' לתלמיד א' ש' תשובות בצרת הבת<sup data-n=\"697\">686</sup> כו') והוא בבחי' מקור השכל והחכ' כמו שהוא בבחי' אין והעלם עדיין קודם שיצא לאור, ע\"כ יש ביכולת חכמי התלמוד לברר וללבן ולתרץ כל קושיא המסתיר ומנגד להוציא לאור מן החשך דוקא כנ\"ל, שהוא האמת מן השקר וטעות ובלבול כנ\"ל, והוא לפי ששרש העיון ופלפול בעמל ויגיעה דבירור זה מן החושך גמור שלמטה הוא בא מצד הכח דהעלם דחשך העליון שלמעלה מאור דח\"ע שהוא המברר לאור דח\"ע שיצא בבחי' בירור בעצם כנ\"ל כמו הסופר שמעמיק בהעלם כח החכ' בכמה אופני' הפכי' ומנגדי' עד שיוציא לאור לכתוב בספר רק כפי העולה בבחי' בירור ותמצית המכוון בלי נטי' לימין ושמאל באותיות מצומצמי' דוקא כנ\"ל. וכך הוא ממש בבירור התחתון שמבררי' ומלבני' הלכות דמשנה בפלפול שבתלמוד דהגם שהמשנה כבר יצא מבורר מאור דח\"ע שבספר אבל צריך שיבורר בירור שני מכל קושיא וטעות וסתירה כמו שמלבני' ומצרפי' במצרף כו' עד שיצא כל דבר על בוריו להלכה למעשה כנ\"ל שזהו בא <span data-k=\"pg\">46</span> ּ מכח ההעלם דמקור הח\"ע שבראש דתושב\"כ (ואע\"פ שכבר הוברר במקור הח\"ע שזהו בבחי' סופר ונקרא קו המדה ע\"י הסופרי' שסופרי' כל אות כו' ושוקלי' ומודדי' כו', אך זהו האור ושפע שהולך מלמעלה למטה בבחי' משפיע ומקבל דחכ' בראש לדיבור במשנה, אבל כשצריך להביא לידי מעשה בפו\"מ צריך להתיישב ולעיין מחדש אולי יש מנגד וסותר לבירור זה דח\"ע בח\"ת, לפי כשבא החכ' במעשה יש כח דאו\"ח למעלה מכח החכ' שבראש, והוא שמעלה לחכ' זו למעלה מבירור הקודם שנק' העלם החכ' ומוציא לאור מחדש מכל סתירה ומנגד כו' עד שנק' חידוש גמור מאין ממש שלא הי' כלל באור דח\"ע וח\"ת וד\"ל). וזהו שא' במחשכים הושיבני זה ת\"ב כו' שאין הכונה בחשך גמור, שהרי אדרבה כל עיקר אור הוראה דטו\"ט כו\"פ או\"ה למעלה ממש אינו אלא מפלפול דתלמוד שמביא לידי מעשה דוקא אחר המסקנא כנ\"ל, אלא הכוונה שחשך זה בבלבול דקושיו' ותירוצי' הוא מק\"נ ממש דכל קושיא מסט' דק\"נ שמסתיר אור האמת לגמרי עד שנבוך ומבולבל אבל נהפך חשך זה לאור בהתרת הספיקות ותי' כל קושיא המנגד שנק' ליבון הלכתא, שזהו ממש בחושך עצמו שנהפך לאור (שהוא למעלה בבחי' חושך העליון שנעשה אור, שגדול הרבה יותר בכפלי כפלים מבחי' האור המצומצם דאותיות שמביא הסופר בספר אע\"פ שהוא ברור כנ\"ל וד\"ל).\n<b>ובזה</b> יתורץ מה שא' דתלמוד בבריאה שה[ו]א בבחי' חושך והעלם דמקור החכ' קודם שבאה לברר ולהבדיל במדות",[["696","685","<b>ר\"מ. . ומראה לו פנים</b>: ראה עירובין יג, ב. מאמרי אדה\"א נ\"ך ריש ע' שמא. וש\"נ. תורת חיים בראשית יד, ד ובהערה 52."],["697","686","<b>ש' תשובות בצרת הבת</b>: יבמות טז, א."]]],[2300540980,"ומשנה היא ביצי' שהוא בגילוי אור דחכ' שבמדות בדבור, וע\"כ יש כח בתלמוד לברר וללבן דברי המשנה להוציאה מכל סתירה ומנגד שנק' ליבון הלכתא כנ\"ל וכמ\"ש במ\"א ע\"פ כאהלי קדר כיריעות שלמה דאהלי קדר שהן תכלית השחרורי' נעשי' לביני' בעצם בתכלית כיריעות שלמה שזהו או\"מ דח\"ע כמו שהיא למעלה שא' עוטה אור כשלמה<sup data-n=\"698\">687</sup> נוטה שמים כו' שנק' יריעות שלמה, ולעשות משחור לבן זהו כעושה מחושך אור שאין אור בעצם יכול לעשות מחושך אור רק לדחות החשך, משא\"כ כשחושך והעלם עצמו יאיר שאין שיעור לאורו כלל (ודוגמא לזה במשיח שא' בו ישכיל עבדי<sup data-n=\"699\">688</sup> כו' שיתגלה לו כל העלם דח\"ע שנק' פלאו' חכמה ורזי' וסודות התורה שזהו מבחי' תעלומו' דמקיף דאור תורה (שמאיר בו מבחי' מאור עצמו שממנו מקור כל אור כמ\"ש במ\"א בענין מאור שבה מחזירו<sup data-n=\"700\">689</sup> כו') וכמו שמן למאור<sup data-n=\"701\">690</sup> כו'<sup data-n=\"702\">691</sup> ע\"כ ירום ונשא וגבה מאד בלי שיעור כלל למעלה מעלה כו', ואין זה אלא מבירור האחרון להפוך מחשך דשקר לאור אמת שע\"י פלפול (שזהו כהכאת סלע [וצור] שיזובו מ\"ח שיעלה למעלה מיה\"ק דתוה\"ק). וזהו שא' דעוסק במשנה מדה ונוטלי' עלי' שכר בעוה\"ב ובתלמוד אין לך מדה גדולה הימנה, לפי שמדה זו שמהפך חשך לאור מכל תערובו' זר למטה אין לו שיעור למעלה ונק' מדה גדולה (שלמעלה מן המדה דקו המדה דבחי' סופר וסיפור הנ\"ל וכמ\"ש ארוכה מארץ מדה<sup data-n=\"703\">692</sup> ורחבה מני יה\"ק כו' אחר הבירור האחרון דאו\"ח הזה, שזהו ענין למחכה לו למאן דדייק כו', שהוא מדרגה הב' דעוה\"ב שאחר תחה\"מ שת\"ח דוקא אין להם מנוחה לעלות למעלה עד אין שיעור כלל מטעם הנ\"ל וד\"ל).\n[כד] <b>וזהו</b> מ\"ש ועלמות אין מספר אלו ההלכות שנק' עלמות שהן כמו הבתולות שנק' עלמו'<sup data-n=\"704\">693</sup> כידוע שלא ידעו איש כלל ולא כמלכות ופלגשי' שמקבלים מאיש משפיע כנ\"ל, והענין דהלכות אלה <span data-k=\"pg\">כג</span> ּ זהו שבאי' מתוך עומק הפלפול בקושיות ותירוצים רבים שממילא רו[ו]חא שמעתת' ונפיק מילתא חדתא, שהן הלכות ודיני' חדשים לגמרי שלא יובן ויושג בדברי המשנה כלל, וכמו הצמיחה מאין ממש שלא ע\"י זריעה כלל, וכמ\"ש לע\"ל והי' שארית יעקב<sup data-n=\"705\">694</sup> כו' אשר לא יקוה לאיש כו' שלא יצטרכו לקבל מאיש בחי' משפיע אור דח\"ע כו', והיינו שנק' עלמות ובתולות שאינם מקבלי' [ב]יחוד איש משפיע מ\"ד כי רחמה אטום ואין בה בחי' כלי קיבול לקבל ולקלוט מאיש כו', אבל זהו המעלה שמקבלת ממקור כל החכ' שהוא בחי' מאור עצמ[ו] שלמעלה מבחי' אור משפיע (והוא שנק' הלכה סתם מלשון הליכות אלי<sup data-n=\"706\">695</sup> כו' הליכות עולם לו<sup data-n=\"707\">696</sup> שזהו בחי' הילוך ונתיב",[["698","687","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["699","688","<b>במשיח. . ישכיל עבדי</b>: נסמן לקמן מג, ד."],["700","689","<b>מאור שבה מחזירו</b>: ראה ירושלמי חגיגה פ\"א, סה\"ז. לקמן פ' תצוה שלו, ד. וש\"נ. ויקהל תמ, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רכד. תקס\"ב ח\"ב ע' שנ. מאמרי אדה\"א בראשית ע' תט וע' תיח."],["701","690","<b>שמן למאור</b>: תרומה כה, ו. ראה גם לקמן פ' תצוה שמא, ג. שמו, ד. מאמרי אדה\"א נ\"ך ע' רפג. וש\"נ. ש\"א נט, א ובהערה 16."],["702","691","<b>כו'</b>: יאיז: כו'). ואולי סיום החצע\"ג הוא בשורה הבאה אחרי תיבת כו'."],["703","692","<b>ארוכה מארץ מדה</b>: איוב יא, ט."],["704","693","<b>הבתולות שנק' עלמו'</b>: ראה רש\"י שה\"ש א, ג. ת\"ז תכ\"א מג, ב: ועלמות. . דאינון בתולות הובא באוה\"ת כאן ס\"ע כא. וראה גם (כרך ח) ע' ב'תתכד (פ\"ד)."],["705","694","<b>והי' שארית יעקב</b>: מיכה ה, ו. ראה גם לקמן פ' בשלח רלה, א."],["706","695","<b>הליכות אלי</b>: תהלים סח, כה."],["707","696","<b>הליכות עולם לו</b>: חבקוק ג, ו."]]],[2300540985,"פרטי שהולך מעצמו' ומקור החכ' הקדומה שהיא בהעלם העצמו' שנק' חשך סתרו שנהפך חשך לאור (כסוד ה' שנתגלה שא\"א לבוא באו\"פ בכלי כאותיות דתושב\"כ שנק' ספר כו'), וכמו בחי' צמיחת השערות שיונקי' מגומא שבמוחי' שלמעלה מגוף המוחי' עצמם כמזל ונוצר כו'), וכך הלכות דתלמוד שבאי' מהעלם דחשך שלמטה ובוקעי' ויוצאי' לאור ששרשו למעלה בחשך העליון שלמעלה<sup data-n=\"708\">697</sup> מאור דתורה שנק' משפיע וכנ\"ל שמטעם זה התלמוד בבריאה ומשנה ביצי' שזהו חשך שקדם לאור כו' וד\"ל. ונמצא דגם שהעלמו' שהן ההלכות אינם מקבלי' מאור דח\"ע דתושב\"כ הנק' איש כמו המשנה, כי הן מחודשי' לגמרי כמימרות האמוראי' ומה שמחדשי' מן הפלפול כנ\"ל, עכ\"ז שרשו למעלה יותר בעצמו' בעל החכמה ורצה\"ע כנ\"ל. וזהו שא' דעלמות אין מספר כלל כמו שאנו רואי' בצמיחה חדשה שבאה מכח הארץ עצמה שאין לה שיעור כלל (וכצמיחת השערות שהלכות נק' נימין ושערות כמו כעדר הרחלי' כו' וכתיב קווצותיו תלתלים<sup data-n=\"709\">698</sup> כו' וכמ\"ש סלסלה כו' כמ\"ש במ\"א). ושרש הענין הוא בהיות שאור ושפע דחכ' שהוא שם מ\"ה דאדם אינו נמשך למטה רק במספר קצוב המתחלק במדות שבחו\"ב שהן ששה חג\"ת נה\"י ומתחלק כל א' לי' וי' לי' כו' במל' שהוא בחי' הדיבור כנ\"ל, וזהו שהיו ישראל במ\"ת ת\"ר אלף נגד ו' מדות דחכ' ששרשם מחכ' שנמשך במל' כמו שו' מדות דחכ' דתורה נמשך לחכ' שבדבור בתושבע\"פ שזהו עיקר בחי' אדם והתורה נק' תורת האדם<sup data-n=\"710\">699</sup> שהוא שם מ\"ה דבחכמה אתברירו, והטעם הוא לפי שעיקר ענין הבירור הוא לבחי' המדות דתהו שנפלו בשבה\"כ כידוע ואין בירור המדות אלא בחכ' דמ\"ה דתיקון שזהו בחי' אדם דתורה דאוריי' מח\"ע נפקת והוא תושב\"כ ח\"ע ותושבע\"פ ח\"ת כנ\"ל, ולכך יש מספר באותיות דתושב\"כ ס\"ר נגד ו' מדות שמתחלקי' עד ת\"ר אלף, וכן בתושבע\"פ ס' מסכתות שהן ו' מדות דמל' שנק' אדם תתאה, וכן נש\"י שנק' אדם<sup data-n=\"711\">700</sup> כידוע, אבל בחי' העלמו' שהן ההלכות שמתחדשי' מאין ליש ממש מלמטה למעלה בבירור דפלפול בעמל תורה בהיפך דחשך עצמו לאור, ה\"ז עולה למעלה עד אין שיעור ומספר כלל, להיותו למעלה מבחי' אור ישר דחכ' ומדות והיינו בבחי' ההעלם דעצמות בעל הרצון והחכ' (שלכך נק' עלמות בחי' העלם כנ\"ל) שאין שם בחי' מספר כלל. וזהו ועלמות אין מספר שהן חידושי ההלכות של האמוראי' דוקא במה שמחדשי' בפלפולם בבירור כל פסולת שהוא הקושיא וטעות דממילא יצמח <span data-k=\"pg\">48</span> ּ מזה דינין חדשי' לרוב שזהו כמו הצמיחה מאין ממש בארץ (וכבקיעת השערות מנקבי העור שבוקע מלמעלה מגוף המוחי' כו' דהיינו מה שלא יוכל לבא",[["708","697","<b>שלמעלה</b>: בתו\"ח הוכפלו כאן עוה\"פ התיבות מלעיל שו\"ה בחי' — מגוף. . שלמעלה."],["709","698","<b>קווצותיו תלתלים</b>: שה\"ש ה, יא."],["710","699","<b>והתורה נק' תורת האדם</b>: חוקת יט, יד. שמואל-ב ז, יט."],["711","700","<b>נש\"י שנק' אדם</b>: יבמות סא, א."]]],[2300540990,"בגילוי או\"פ בכלי במוחי' עליוני' בח\"ע באותיות שבכתב וגם בח\"ת בדיבור יוצא בבחי' צמיחה דשערות (וכמ\"ש סלסלה ותרוממך כו'), וזהו כמו<sup data-n=\"712\">701</sup> שהתלמוד בבריאה שנק' חשך והעלם ומשנה ביצי' שנק' אור שהוא אור דחכ' במח'<sup data-n=\"713\">702</sup> ובדיבור אבל בחי' העלם דמקיף דחכ' שלא יוכל לבא בגילוי או\"פ ומדות ודבור זהו שיוצא בפלפול שהוא בחי' הצמיחה דאין<sup data-n=\"714\">703</sup> והעלם דחושך עצמו שיאיר אור שאין לו מספר כלל וד\"ל (וזהו למעלה גם מסופר שממשיך ומביא לספר במספר אותיות וכן סופרי' שסופרי' ודורשי' כו' שיש בזה שיעור ומדה עכ\"פ וכן תנאי' שממשיכי' מח\"ע לח\"ת בדיבור שנק' איתנים יש לזה מספר בסיפור בס' מסכתות וברייתות שהן פ' פלגשי', אבל עלמות דחידושי הלכות בפלפול א\"א שיכילו במספר אותיות בכתב ואותיות בדבור, להיותו למעלה ממקור האור דח\"ע וח\"ת הנק' ספר וסיפור מטעם הנ\"ל וד\"ל. ועכ\"ז א' שאין הגליות מתכנשות אלא בזכות המשניות דוקא כי הקיבוץ דגליות זהו שמתכללי' בבחי' אדם שהוא שם מ\"ה דח\"ע וח\"ת כנ\"ל, שיש לזה מספר (אפי' כמה פעמי' ס\"ר הן בציור קומה עכ\"פ דאדם ותורת האדם שזהו במשיח שהוא אדה\"ר<sup data-n=\"715\">704</sup> הכולל כל הנשמות<sup data-n=\"716\">705</sup> כו') אבל למעלה מזה הוא בעלמות שהן הלכות דפלפול ששרשו במקיף דנר\"נ שיהי' זה בעוה\"ב שא' למחכה לו למאן דדייק כו', וזהו אז תשמח בתולה במחול<sup data-n=\"717\">706</sup> בבחי' מקיף דוקא כמ\"ש במ\"א) וד\"ל.\n[כה] <b>אחת</b> היא יונתי תמתי כו', כי הנה כל מה שמבואר למעלה בענין ס' מלכות ופ' פלגשי' ועלמות הכל הוא בתושב\"כ ושבע\"פ ח\"ע וח\"ת שנק' תורת האדם וגם עלמו' באי' מבחי' מקיף דחכ' ומדות דאדם כו', רק שבתושב\"כ נק' מוסר אביך ותושבע\"פ נק' תורת אמך כו' בבחי' עיבור והריון כמ\"ש להורותם להרתם כתי'<sup data-n=\"718\">707</sup>, והוא מה שנש\"י מתקשרי' בס\"ר אותיות דתושב\"כ בבחי' אור דח\"ע (שנק' אור אבא שזהו מוסר אביך), ומה שנמשכים לבינה הנק' אם הבנים<sup data-n=\"719\">708</sup> שזהו תושבע\"פ שנק' תורת אמך וחדר הורתי<sup data-n=\"720\">709</sup> שהן ס' מסכתות הכלולי' בו' מדות דמל' שמשם מקור מחצב תולדות נש\"י בהתחלקו' דס\"ר במהו' בריאה בפ\"ע כמו אתה בראת יצרת<sup data-n=\"721\">710</sup>, וכתי' כל הנק' בשמי<sup data-n=\"722\">711</sup> שהן נש\"י שעלו במח' ולכבודי באור החכ' בראתיו יצרתיו כו' במח' ודבור בהעלם וגילוי דספר וסיפור הנ\"ל, אף עשיתיו זהו לרבותא יתירה דאף לרבותא וריבוי [שהוא בא] בחידוש גמור יותר מבריאה [ו]יצי', דבריאה בהעלם דחכ' ויצי'",[["712","701","<b>כמו</b>: יאיזיח: ליתא."],["713","702","<b>במח'</b>: יח: במדות. וראה ההמשך בפנים."],["714","703","<b>דאין</b>: יח: דארץ."],["715","704","<b>במשיח שהוא אדה\"ר</b>: ראה גם לקמן פ' בשלח קס, ד. מאמרי אדה\"ז תקס\"ז ע' לט. מאמרי אדה\"א דברים ח\"ג ע' תתטו."],["716","705","<b>אדה\"ר הכולל כל הנשמות</b>: ראה אגה\"ק ס\"ז. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצא. מאמרי אדה\"א דברים ח\"ג ע' תתיא. ח\"ד ע' א'שצה ובהנסמן בהנ\"ל. לקמן פ' בשלח קנט, ב. קפ, ג."],["717","706","<b>אז תשמח בתולה במחול</b>: ירמי' לא, יב. ראה סידור שחרית לשבת סח, ב ואילך. מאמרי אדה\"ז מארז\"ל ע' תטז ואילך. תקס\"ה ח\"א ע' רכ. מאמרי אדה\"א דברים ח\"ד ס\"ע א'שסא ואילך."],["718","707","<b>להורותם להרתם כתי'</b>: משפטים כד, יב. זהר שמיני מ, ב. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קפב."],["719","708","<b>לבינה הנק' אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. מאמרי אדה\"א נ\"ך ע' שיב. וש\"נ. שעה\"י קי, ב ובהערה 19."],["720","709","<b>וחדר הורתי</b>: שה\"ש ג, ד."],["721","710","<b>אתה בראת יצרת</b>: ברכת אלקי נשמה [בדילוג]."],["722","711","<b>כל הנק' בשמי</b>: ישעי' מג, ז."]]],[2300540995,"באור בבחי' עיבור דנש\"י בתושבע\"פ שמקבל מתושב\"כ שכל זה עדיין אינו מהות ברי' בפ\"ע כלל כו', כמו עד\"מ עובר במעי אמו שנכלל בה ונחשב כא' מאבריה כמו שא' עובר ירך אמו<sup data-n=\"723\">712</sup> כו', אבל כשנולד ויצא לאויר העולם נק' ברי' בפ\"ע לגמרי ואינו נכלל באמו והוא בחי' אדם דעשי' ברמ\"ח אברי' שיש בו בצלם אדם דבריא' ויצי' שהוא ח\"ע וח\"ת, וזהו אף עשיתיו שעולה למעלה הרבה יותר מפנימי' דתורת האדם בח\"ע וח\"ת דתושב\"כ ושבע\"פ שנק' אב ואם כנ\"ל. וז\"ש אחת היא יונתי כו' בחי' אחת שהיא בחי' כלי לאחד פשוט<sup data-n=\"724\">713</sup> שלמעלה מן המספר דחכ' ומדות דאדם כו', והוא בחי' יחיד שלפני אחד<sup data-n=\"725\">714</sup> מה אתה סופר<sup data-n=\"726\">715</sup>, ולכך הכלי שמקבלת לאח\"פ דלאו מכל אינון מדות כו' נק' בשם אחת דוקא כידוע וד\"ל.\n<b>וביאור</b> הענין הנה ידוע דכנ\"י <span data-k=\"pg\">כד</span> ּ נק' אחת והוא בבחי' יחידה<sup data-n=\"727\">716</sup> שלהם שלמעלה מהשכל ורצון ומדות שהוא עצמיות הנשמה ממש שלמעלה מבחי' כח החכ' ומדות דאדם שמקבלי' מח\"ע וח\"ת כנ\"ל שה[ו]א בחי' כלי ממש לקבל בתוכה בחי' אח\"פ שלמעלה מחכ' ומדות דאדם כנ\"ל, ולכך א' אחת היא יונתי כו' למעלה מס' מלכות ופ' פלגשי' כו' דתושבע\"פ בדבור דתורה. והענין הוא כמו שא' דאיהו אמת ואיהי אמונה דמשמע מזה דבחי' אמונה דכנ\"י כשנק' אמונה היא כלי קיבול לאמת שהיא אמתת מהו\"ע ית' כנ\"ל דאנת הוא חד ולא בחושבן י\"ס אפי' בהעלם כו', והיינו כמארז\"ל דתרי\"ג מצות ניתנו למשה בסיני ובא חבקוק והעמידן על אחת<sup data-n=\"728\">717</sup> שהוא מ\"ש וצדיק באמונתו יחי'<sup data-n=\"729\">718</sup>, שזהו בחי' האמונה הפשוטה דכנ\"י שנטוע ומושרש בנפשם בבחי' התקשרות עצמיות ממש דבחי' יחידה (שזהו שנק' נקוד' יהדותם כו'), זהו בחי' כלי להכיל לאמתת מהו\"ע ית' שהוא בעל הרצון והחכ' דתו\"מ, דזהו איהו אמת בחי' אח\"פ איהי בחי' מל' בחי' כלי לקבל זה האמת דאח\"פ ממש, ע\"כ נק' אחת בחי' נוק' לקבל זה האור דאמת שהוא בבחי' יחידה שבה כמו שהוא יחיד לבדו כו' למהוי אחד באחד ממש, ולכך העמיד כל התרי\"ג מצות באחת זו שהיא בחי' האמונה הפשוטה ועצמיות דכנ\"י הנ\"ל שהיא בחי' יסוד כולל לכל התרי\"ג מצות שבאי' בהתחלקו' דחכ' ומדו' בדרך פרט. וז\"ש דאע\"פ שס' המה מלכות בו' מדות דח\"ת דתושבע\"פ ששרש יסודם במדות דח\"ע שהוא ספר וסיפור כנ\"ל, מ\"מ אחת היא כו' שכוללת כולם להיותה למעלה מן המספר וההתחלקות דחכ' ומדות, שהוא בחי' יחידה דכנ\"י שנק' התקשרות עצמיות שלמעלה גם מהרצון (וזהו והי'",[["723","712","<b>עובר ירך אמו</b>: גיטין כג, ב."],["724","713","<b>אחת. . כלי לאחד פשוט</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"א. לקמן פ' בשלח רב, ב. הנסמן במאמרי אדה\"א קונטרסים ע' שצא. שע\"ת ס, ג."],["725","714","<b>יחיד שלפני אחד</b>: נסמן לקמן מז, א."],["726","715","<b>שלפני אחד. . סופר</b>: ראה ס\"י פ\"א, מ\"ז. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכב."],["727","716","<b>אחת. . יחידה</b>: ראה תוד\"ה עד אחת מנחות יח, א."],["728","717","<b>דתרי\"ג מצות. . על אחת</b>: ראה מכות כג, סע\"ב ואילך. שה\"א ד, א. יא, א. לקמן פ' תצוה שמה, א."],["729","718","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."]]],[2300541000,"מספר בנ\"י כחול הים כו' למעלה מן המספר דס\"ר למעלה [ב]שרשם בח\"ע וח\"ת, וכמו על צבאותם<sup data-n=\"730\">719</sup> למעלה ממספר צבאותם בשם הוי' כאשר הן בבחי' אדם לקבלת התורה דמ\"ה דחכ' כו', והוא בעצם הרצון כמו שאמר תחלה כל אשר דיבר ה' נעשה<sup data-n=\"731\">720</sup> שהקדימו נעשה לנשמע<sup data-n=\"732\">721</sup> שזהו בעצמיו' דמקור הרצון כידוע שממילא עי\"ז קיבלו אח\"כ בשמיעה בהתחלקות הרצון לחו\"ג במ\"ע ול\"ת באנכי ולא<sup data-n=\"733\">722</sup> כו'). וזהו וצדיק באמונתו יחי' באמונה הפשוטה יחי' חיי עולם במהו\"ע א\"ס ב\"ה שלמעלה גם מן המצות, וזהו העמידן על אחת, וזהו אחת היא כו' וד\"ל.\n<b>וזהו</b> אף עשיתיו שהוא בסוף מעשה בקבלת עומ\"ש שבכל מצוה ע\"י אמונה הפשוטה לבד לפי שנתחב\"ס דוקא, כי בקבלת עול זה לבטל רצונו מפני רצון ה' (כמו כל אשר דבר כו' כנ\"ל) זהו עולה בבחי' התקשרות העצמיו' דיחידה שבאמונה העצמי' שלמעלה מהתפעלו' רצון וחכ' כו', ובזה יש עלי' לכל התחלקו' הרצה\"ע בח\"ע וח\"ת שאין זה רק גילוי האורו' בחכ' ומדות ודבור לבד, אבל להקים את דברי התו\"מ האלה למעשה בפו\"מ זהו ע\"י ביטול הרצון לקיים רצה\"ע דהיינו רק בנש\"י בגופי' כשמניח התפילין בראשו וציצית בבגדו ועושה צדקה בפו\"מ וכה\"ג בכל המצות, וז\"ש ועשיתם אותם כו' כאלו עשאוני<sup data-n=\"734\">723</sup> ברמ\"ח כו' וד\"ל. וזהו כמשל הלידה שאחר העיבור שנעשה ברי' חדשה ממש וכך רמ\"ח מ\"ע ושס\"ה ל\"ת שכתובי' בתושב\"כ ומתגדלי' באו\"כ בתושבע\"פ זהו כעיבור הולד בבטן עדיין, אבל בהתגלות שלהם בנש\"י בגופי' במעשה נק' לידה וזהו שנק' אחת בחי' כלי לאחד עצמו בעל הרצון והחכ' דתו\"מ לפי שנתב\"ס דוקא מטעם הנ\"ל. ואמנם זהו דוקא אחר גידול הולד בבטן ברמ\"ח אברי' שהוא <span data-k=\"pg\">50</span> ּ שנק' תורת אמך כו' שהן בו\"ס משנה אז כאשר בא הכל למעשה בנש\"י ע\"ז א' אף עשיתיו שהוא בבחי' לידה שאחר העיבור כו' וכמו הולד שהולך וגדל בחכ' ומדות בלידתו בבחי' גדלות המוחי' (אע\"פ שמלמדי' אותו כל התורה בעיבור בהעלם כו'), (ושלימו' דגידול בנש\"י שנק' אדם דעשי' כנ\"ל הוא בימי משיח שא' בנ\"י היום ילדתי\"ך כו' וכתי' בי' ישכיל עבדי כו' וגב\"ה מאד ואז א' אחת היא כו' כנ\"ל שיהי' כלי לאח\"פ [ממש] אחר הגלות האחרון הזה שהי' בעב\"ק [בחו\"ל ] כו' בליבון הלכתא כו' (בבחי'<sup data-n=\"735\">724</sup> עיבור, דכל גלות נק' עיבור כמו אפי' אתה מתמלא עליהם עברה כאשה עוברה<sup data-n=\"736\">726</sup> כו', וזהו עד יעבור אותיות עיבור<sup data-n=\"737\">727</sup> כו' כידוע). אך התחלת ענין הגאולה שנק' לידה<sup data-n=\"738\">725</sup> הי' ביצ\"מ כמ\"ש ואומר לך בדמייך חיי<sup data-n=\"739\">728</sup> כו'",[["730","719","<b>על צבאותם</b>: וארא ו, כו. בא יב, נא. ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' קכח ואילך. ע' קלח. תו\"א בא ס, סע\"ג. לקמן עח, ד. קטו, ג."],["731","720","<b>כל אשר דיבר ה' נעשה</b>: יתרו יט, ח. משפטים כד, ז."],["732","721","<b>שהקדימו נעשה לנשמע</b>: שבת פח, א."],["733","722","<b>במ\"ע ול\"ת באנכי ולא</b>: ראה זח\"ב (יתרו) צא, א. (תוספות) רעו, א. של\"ה ר\"פ יתרו שטו, ב. תניא רפ\"כ."],["734","723","<b>ועשיתם. . עשאוני</b>: בחוקותי כו, ג. ראה זהר שם קיג, סע\"א. מאמרי אדה\"א הנחות תקע\"ז ע' רלה. וש\"נ."],["735","724","<b>(בבחי'</b>: יזיח: בבחי'."],["736","726","<b>אפי'. . כאשה עוברה</b>: נסמן לקמן לא, ג הערה 215."],["737","727","<b>עד יעבור אותיות עיבור</b>: בשלח טו, טז. ראה פע\"ח (שער הסליחות) שי\"ב, פ\"ג. לקמן פ' וארא סו, א. מאמרי אדה\"א שמות ח\"א ע' סא. וש\"נ. שה\"א פו, א ובהערה 11."],["738","725","<b>גלות נק' עיבור. . הגאולה שנק' לידה</b>: ראה תו\"א ר\"פ וארא. מאמרי אדה\"א שמות ח\"א ע' פא ואילך. קונטרסים ע' רכג. תו\"ח נח נח, ב בהערה 28. לקמן כה, א. לא, ג. וארא סו, א. ויקהל שצט, ב."],["739","728","<b>ואומר לך בדמייך חיי</b>: יחזקאל טז, ו."]]],[2300541005,"וגלות מצרים נק' עיבור והי' בעבו\"ק בחו\"ל בנש\"ט<sup data-n=\"740\">729</sup> דקלי' מצרים, וגם אז א' ס' מלכות כו' אחת היא יונתי כו' שהן כנ\"י שיצאו מנש\"ט דמצרים בבחי' אמונה הפשוטה ועצמ[י'] ולא נשתקעו בטומאת מצרים, וכמ\"ש זכרתי לך<sup data-n=\"741\">730</sup> חסד נעוריך דוקא לכתך אחרי כו' באמונה עצמי' דבחי' יחידה הנ\"ל, ולכך זכו ממילא למ\"ת פב\"פ כנ\"ל וד\"ל.\n<b>והנה</b> ע\"י בחי'<sup data-n=\"742\">731</sup> עב\"ק בכל משך זמן הגלות בחו\"ל ליבון הלכתא בעמל תורה הנ\"ל (ובעמל תפלה שנק' שיחה<sup data-n=\"743\">732</sup> כמו לפני ה' ישפוך שיחו<sup data-n=\"744\">733</sup> במרירות ומיצוי הנפש כנ\"ל, ובעמל מלאכה בלחץ ודחק הפרנסה שפעל אברהם אבינו להיות במקום גיהנם כנ\"ל), עי\"ז דוקא יזכו כנ\"י לבחי' אור גדול בגילוי פנימי' ועצמו' אור א\"ס בפנימי' וסודות התורה שנק' טעמי תו\"מ שיתגלו בימות המשיח כו', ובעלי' עוד למעלה מזה בעוה\"ב שנק' עדן העליון דעין לא ראתה רק למחכה לו כו' וכנ\"ל בעליו' עדי עד שמו הגדול דבחי' מל' דא\"ס מקור כל התענוגים כו'. והענין הוא כמ\"ש כימי צאתך מאמ\"צ אראנו נפלאות, דכמו שע\"י הגלות דוימררו את חייהם בעב\"ק במצרים שנק' כור הברזל כנ\"ל ז[כ]ו לקבלת התורה הנגלית לנו פב\"פ כנ\"ל בענין ג' דברים באו ע\"י יסורים תורה וא\"י ועוה\"ב כו', כך לפ\"ע הזה ע\"י גלות זה האחרון בעמל תורה ותפלה כו' וע\"י בחי'<sup data-n=\"745\">734</sup> העוני בלחץ ודחק הפרנסה דוקא כנ\"ל עי\"ז דוקא יזכו לקבלת התורה הפנימי' בימות המשיח עד שכולם ידעו אותי<sup data-n=\"746\">735</sup> כו' (שזהו כמו העלי' דנשמות מגיהנם ונה\"ד לגעה\"ת, ועלי' הב' מגעה\"ת לגעה\"ע הוא לעוה\"ב שנק' ארץ החיים דעדן, ועלי' ג' בתחה\"מ כנ\"ל).\n[כו] <b>והנה</b> מעתה אחר כל הנ\"ל יובן שרש ענין הירידו' בגליות שהוא בשביל העליו' בכלל שאם אין ירידה אין עלי' (וכידוע דד' גליות הן לנגד ד' נהרות<sup data-n=\"747\">736</sup> שיצאו מג\"ע בבחי' פירוד כמ\"ש ומשם יפרד<sup data-n=\"748\">737</sup> והי' לד' ראשים כו' שזהו מנהר שיוצא מעדן שמשם<sup data-n=\"749\">738</sup> יפרד לד' נהרות שם האחד פישון הוא נהר נילוס<sup data-n=\"750\">739</sup> דמצרים שהוא גלות הראשון כו' עד ונהר הרביעי פרת<sup data-n=\"751\">740</sup> גלות האחרון הוא דמעיקרא נהר הראשון שיוצא מעדן שהוא להשקות ג\"ן סדרים דאורייתא כו', שע\"ז א' עד יעבור, בנהר יעברו ברגל<sup data-n=\"752\">741</sup> שם נשמחה בו, שהוא העדן דעוה\"ב למעלה משם הוי' דתו\"מ אלא עם זו קנית קנין עצמי' ונצחי' וזהו אשר אהי' כנ\"ל). ושרש הענין הוא מובן ע\"פ הנ\"ל בענין",[["740","729","<b>בנש\"ט</b>: נסמן לקמן מא, ד."],["741","730","<b>זכרתי לך</b>: ירמי' ב, ב."],["742","731","<b>בחי'</b>: יאיזיח: ליתא."],["743","732","<b>תפלה שנק' שיחה</b>: ראה מכילתא בשלח יד, ו. ברכות כו, ב. ע\"ז ז, ב. מאמרי אדה\"ז תקס\"ז ס\"ע רסב ואילך. ע' רסז. לקו\"ת חוקת סו, א. סז, ב."],["744","733","<b>לפני ה' ישפוך שיחו</b>: תהלים קב, א [ושם: ולפני — ראה שע\"ת כה, ד הערה 39]."],["745","734","<b>בחי'</b>: יאיזיח: כור."],["746","735","<b>שכולם ידעו אותי</b>: ירמי' לא, לג."],["747","736","<b>דד' גליות. . ד' נהרות</b>: ראה ב\"ר פט\"ז, ד."],["748","737","<b>ומשם יפרד</b>: בראשית ב, י."],["749","738","<b>שמשם</b>: יאיזיח: שממנו."],["750","739","<b>שם האחד פישון. . נילוס</b>: בראשית ב, יא. נסמן לקמן לו, ד."],["751","740","<b>ונהר הרביעי פרת</b>: ראה בראשית שם, ד."],["752","741","<b>בנהר יעברו ברגל</b>: תהלים סו, ו."]]],[2300541010,"משובח ומפואר עדי עד שמו הגדול שהוא בחי' מל' דא\"ס שהוא מקור כל העונג העליון שנמשך לעוה\"ב וג\"ע כו' ויש בו עליות עד אין קץ במדרגות התענוג העליון, ולהיות שא\"א לעלי' במדרגה העליונה <span data-k=\"pg\">כה</span> ּ יותר אם לא בחי' הצמצום והחשך שהוא ההעלם בתחלה שזהו ביטול היש הראשון כענין מה פשפשת<sup data-n=\"753\">742</sup> כו' ואח\"כ יעלה למעלה יותר, וכמו הצמצום הראשון דמק\"פ וחלל<sup data-n=\"754\">743</sup> כו' שלפני האור דקו\"ח (כענין גולל אור מפני חשך<sup data-n=\"755\">744</sup> וחשך מפני אור כו' כמ\"ש במ\"א), וכמו ויהי ערב ואח\"כ ויהי בקר<sup data-n=\"756\">745</sup>, ברישא חשוכא<sup data-n=\"757\">746</sup> צמצום ואח\"כ נהורא התפשטות אור (וכעיבור שלפני הלידה כנ\"ל). וכך הוא למטה בכל ענין העליו' שאחר ירידה דוקא עלי', והוא ענין ד' גליות שכל גלות הוא בחי' ירידה ואח\"כ עלי' שהוא הגילוי אור דגאולה אחר החשך והעלם כו' (וכמ\"ש בגמ' מ\"ט עזי מסגי ברישא<sup data-n=\"758\">747</sup> כו'), וכך א' יעקב יעבר נא אדוני<sup data-n=\"759\">748</sup> לפני עבדו כו', וכל שהירידה נמשכת יותר בגלות האחרון הזה העלי' למקום ומדרג' יותר שהוא קבלת התורה בפנימי' ע\"י משיח כמ\"ש כימי כו' אראנו נפלאות בגילוי ההעלם דסדכ\"ס כו' וד\"ל.\n[כז] <b>ומעתה</b> יש להבין ענין ירידת גלות מצרים שנז' בפ' ויגש ומה שכפל כאן עוד פעם שני' בא' ואלה שמות בנ\"י כו' כנ\"ל, דהנה בגלות מצרים א' אנכי ארד עמך מצריימה ואנכי אעלך גם עלה הרי יש כאן ב' עליות זו למעלה מזו כמ\"ש אעלך גם עלה כו', ומוכרח לומר שהיו ב' ירידות בבחי' ירידה זו בגלות מצרים, והוא כמ\"ש אנכי ארד עמך, אנכי ירידת הנשמה<sup data-n=\"760\">749</sup> עם ירידה דיעקב עצמו כו' (וכמ\"ש השבטי' ליוסף ירד ירדנו<sup data-n=\"761\">750</sup> לשבר אוכל כו' ב' ירידות ירידה אחר ירידה דיוסף צ\"ע וב' יריד' דשבטי' כו'), ולזה א' אעלך גם עלה ב' עליות עילוי אחר עילוי כמו שהי' ירידה אחר ירידה כנ\"ל. ולהבין ביאור זה יש להקדים תחלה בשרש ענין ישראל ויעקב ולאה ורחל והשבטי' בדרך כלל, דהנה ידוע דאותיות המחשבה הוא בהעלם בחי' עלמא דאתכסי' והוא בחי' לאה שילדה ששה בנים<sup data-n=\"762\">752</sup> שהן המדות שנולדים לחוץ כו' והדיבור הוא באותיו' שבאי' בצירופי' בהבל הפה בהתגלות כו' נק' עלמא דאתגליא<sup data-n=\"763\">751</sup> והמדות שהן בלב משם נובע לאותיות המח' בהעלם [הנ\"ל] וגם להבל הפה באותיות הדבור. וזהו הקל קול יעקב<sup data-n=\"764\">753</sup>, ב' מיני קול",[["753","742","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["754","743","<b>הצמצום הראשון דמק\"פ וחלל</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["755","744","<b>גולל אור מפני חשך</b>: תפלת ערבית. ברכות יא, ב. ראה גם מאמרי אדה\"ז על ענינים ע' שיז. ע' תיג. מאמרי אדה\"א בראשית ע' תד. וש\"נ. תו\"ח תולדות קסא, סע\"ג ואילך. וישלח קפה, ב."],["756","745","<b>ויהי ערב. . בקר</b>: בראשית א, ה. ראה גם מאמרי אדה\"א נ\"ך ע' תטז. תו\"ח בראשית יד, ב. לקמן מט, ג."],["757","746","<b>ברישא חשוכא</b>: שבת עז, ב [כגי' רש\"י]. ראה לקמן מט, ג."],["758","747","<b>מ\"ט עזי מסגי ברישא</b>: שבת שם. ראה גם מאמרי אדה\"א בראשית ע' קעט. וש\"נ. שעה\"י קמז, א ובהערה 6."],["759","748","<b>יעבר נא אדוני</b>: וישלח לג, יד."],["760","749","<b>הנשמה</b>: יאיזיח: השכינה."],["761","750","<b>ירד ירדנו</b>: מקץ מג, כ [בדילוג]."],["762","752","<b>לאה שילדה ששה בנים</b>: ויצא ל, כ. ראה ע\"ח (שער מ\"ן ומ\"ד) של\"ט, ד\"ח. לקו\"ת להאריז\"ל ויצא (ענין בני לאה). לקמן פ' משפטים רפז, ד. חצר, א. פקודי תמד, א. תמז, א. שעה\"י קלה, א. מאמרי אדה\"א נ\"ך ע' קפח. וש\"נ."],["763","751","<b>ולאה ורחל. . עלמא דאתכסי'. . דאתגליא</b>: ראה זהר (ס\"ת) ויצא קנב, א. וארא כט, ב. ע\"ח (שער מוחין דצלם) שכ\"ג, פ\"ד."],["764","753","<b>הקל קול יעקב</b>: תולדות כז, כב."]]],[2300541015,"א' המשכות המדות שבלב למח' והב' המשכות המדות שבלב לדבור. וזהו שיעקב נשא ב' אחיות<sup data-n=\"765\">*754</sup> לאה ורחל המח'<sup data-n=\"766\">754</sup> ודבור<sup data-n=\"767\">755</sup> שמקבלי' מן הלב (וזהו ג\"כ ענין ב' חכמות ח\"ע דתושב\"כ שנק' אמת ליעקב זהו קול יעקב בהעלם דמח' שנק' ספר, וקול יעקב שנמשך לסיפור בתושבע\"פ ח\"ת חכ' שבדבור שנק' סיפור והן כמו י\"מ (כמשי\"ת). ואמנם הנה בחי' ישראל הוא למעלה מיעקב, דיעקב יו\"ד עקב<sup data-n=\"768\">756</sup> זהו מה שהחכ' יורדת במדות שבלב למו\"ד שנק' עלמין סתימין ואתגליין אבל ישראל לי ראש<sup data-n=\"769\">757</sup> זהו כמו שהחכ' היא למעלה בראש שכלולי' שם גם המדות (ונק' יש\"ס ויש\"ז<sup data-n=\"770\">758</sup> במל' דתבונה באותיות מחשבה עיוני' באור השכל עצמו כו') וא' לא יעקב יקרא עוד<sup data-n=\"771\">759</sup> כו', כי ישראל זה שהוא ח\"ע שבראש יורד הוא ומתלבש במדות שבלב להיות מאיר גם במו\"ד דוקא, שהרי אנו רואי' בחוש שגם שהמו\"ד נמשכים מן המדות שבלב כנ\"ל מ\"מ עודנה קשורי' ומיוחדי' המו\"ד באור השכל וחכ' שבראש שמאיר ומלובש בהן בהעלם, כי הרי כל אופן צירופי אותיות המח' שבהעלם וגם מה שמשתלשל ויורד מן המח' באותיות הדבור הכל הוא דוקא לפי אופן הארת אור השכל והכוונה<sup data-n=\"772\">760</sup> שבמוח החכ' ובינה שבראש לא יטו ימין ושמאל כלל כו', וכמו שניכר במחשבתו ודבורו של אדם בכלל שהמה רק <span data-k=\"pg\">52</span> ּ לפי שכלו לבד אע\"פ שנמשכים מהבל הלב כנ\"ל, כי גם המדות חג\"ת שבלב נמשכים ומקבלי' המה מן המוחי' שבראש שזהו בחי' ישראל מדות דחו\"ב עצמן כנ\"ל וד\"ל.\n<b>ויובן</b> כ\"ז בדרך כלל ופרט במע\"ב שנברא שמים וארץ וכל צבאם בדבר ה' כמ\"ש בדבר ה' שמים נעשו<sup data-n=\"773\">761</sup> וברוח פיו כל צבאם, והדיבור הוא אותיות שבאים ויורדים למטה להיות בחי' המעשה כמ\"ש ויאמר אלקים יהי אור ויהי אור בפו\"מ וכמ\"ש כי הוא אמר ויהי<sup data-n=\"774\">762</sup> וכתיב כולם בחכ' עשית<sup data-n=\"775\">763</sup>, א\"כ זהו בחי' החכ' שבדיבור בי\"מ שנמשך בהן מח\"ע שנק' חכ' בראש, וז\"ש בראשית בחוכמתא<sup data-n=\"776\">764</sup>, דבראשית נמי מאמר<sup data-n=\"777\">765</sup> הוא, דחכ' בראש נמשך לדבור שא\"א לדבור בלא חכ' ושכל שבמוח (ואבא יסד ברתא שצרופי' שבדבור ממילא מתהוי' ע\"פ אופן השכל שבראש כידוע), אך זהו בחי' עלמין דאתגליין. וכמ\"כ יש אותיות שבהעלם המחשבה (שהדבור מתנהג ע\"פ אותיות המח', דעקבי",[["765","*754","<b>שיעקב נשא ב' אחיות</b>: ויצא כט, טז ואילך."],["766","754","<b>לאה. . המח'</b>: ראה סידור שחרית ס, ג. סט, א. לקמן פ' בשלח קפו, רע\"ג. ויקהל תד, ד. מאמרי אדה\"א נ\"ך ע' קג. וש\"נ."],["767","755","<b>ורחל. . ודבור</b>: ראה ע\"ח (שער אח\"פ) ש\"ד, פ\"א. לקמן פ' בשלח קפו, רע\"ג. ויקהל תד, ד. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רכז."],["768","756","<b>דיעקב יו\"ד עקב</b>: ע\"ח (שער סדר אצי') ש\"ג, פ\"ב. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קכז וע' קלא. ש\"א ה, א. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח בראשית לא, ד בהערה 39."],["769","757","<b>ישראל לי ראש</b>: ראה פע\"ח (שער הלולב) שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה־ שע\"ת צד, ד הערה 26."],["770","758","<b>יש\"ס ויש\"ז</b>: [ ישראל סבא וישראל זוטא]. ראה זהר ויקהל רטז, א. לקמן פ' בשלח קצח, ד ואילך. שעה\"י קלג, א."],["771","759","<b>לא יעקב יקרא עוד</b>: וישלח לה, י [ושם: לא יקרא שמך עוד יעקב — ראה מאמרי אדה\"א דברים ח\"ג ע' א'נו ובהערה שם]."],["772","760","<b>והכוונה</b>: יח: והבנה."],["773","761","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["774","762","<b>כי הוא אמר ויהי</b>: תהלים שם, ט."],["775","763","<b>כולם בחכ' עשית</b>: שם קד, כד."],["776","764","<b>וז\"ש </b>[יאיזיח: שז\"ש]<b> בראשית בחוכמתא</b>: בראשית א, א. וראה תרגום ירושלמי שם."],["777","765","<b>דבראשית נמי מאמר הוא</b>: ר\"ה לב, א."]]],[2300541020,"לאה שהיא המח' נכנסי' תוך ראש רחל<sup data-n=\"778\">766</sup> שהוא עולם הדיבור (וכמ\"ש עקב ענוה<sup data-n=\"779\">767</sup> כו' מה שעשתה ענוה<sup data-n=\"780\">768</sup> שהוא מח' עקב לסוליתא עשתה יראה שהוא הדבור עטרה לראשה) כמ\"ש במ\"א), ומאותיות מחשבתו ית' שבהעלם שנק' מאמר סתום<sup data-n=\"781\">769</sup> נבראו עלמין סתימין דלא אתגליין (כמו שהים יש בו כל הברואי' שיש ביבשה<sup data-n=\"782\">770</sup> כמ\"ש במ\"א), וכל מה שבא בגילוי מאין ליש בדיבור בי\"מ כמא' תדשא הארץ תוצא הארץ<sup data-n=\"783\">771</sup> כו' כ\"ז יש בעלמין סתימין<sup data-n=\"784\">772</sup> במח', וכידוע שגם במח' העליונה יש צרופי אותיות שנבראו בהן שמים העליונים וכרקיע ע\"ג ראשי החיות<sup data-n=\"785\">773</sup> במלאכי' דבריאה ו[ל]נשמו' שבגעה\"ע והיכלות [וחי וצומח ודומ'] כמו שיש בגעה\"ת ובעוה\"ז בגשמיות כו'). וזהו ברוך ה' מן העולם<sup data-n=\"786\">774</sup> ועד העולם, מעלמא דאתכסי' שבמח' עליונה לעלמא דאתגליא שבדבור בי\"מ שמאיר ומלובש בהן מאור דח\"ע שבראש שנמשך במדות שבלב אדם העליון וכנ\"ל דגם שהמו\"ד מקבלי' מן המדות שבלב בבחי' קול הגרון בהבל הפה מ\"מ עיקר מקורם דמו\"ד וגם המדות שבלב נמשך מחו\"ב שבראש ומדות הכלולי' שם שנק' ישראל לי ראש כנ\"ל ובירידת אור דח\"ע במדות שבלב (שנק' ז\"א והוא בחי' יעקב איש תם<sup data-n=\"787\">775</sup> שנק' בריח התיכון<sup data-n=\"788\">776</sup> כו' הכולל לחו\"ג דאצי' שמבריח מן הקצה העליון דכתר וחכ' שבראש לבחי' מו\"ד שנק' לאה ורחל עלמין דאתכסיין ועלמין דאתגליין כנ\"ל וד\"ל) (ועכ\"ז הרי אותיות המח' נכללי' ומתאחדי' בשכל שבמוח החכ' ובינה אע\"פ שמקבלי' גם מהבל מדות שבלב, והדיבור מתאחד ונכלל יותר במדות שבלב ע\"י הקול דגרון שיוצא מהבל הלב דוקא אע\"פ שמתנהג הדיבור ע\"י צרופי אותיות המח' דוקא כידוע וד\"ל). ונמצא מובן מכ\"ז דרך כלל בהפרש שבין ישראל ליעקב דבחי' ח\"ע כמו שהיא במוחי' ומדות עליוני' (שכלולי' במח') נק' ישראל לי ראש (וזהו זיווג ישראל ולאה או יש\"ס ותבונה שזהו אותיות דתושב\"כ שנמשך מח\"ע בספר בחילוק דמדות להבדיל בין טו\"ט כו' כנ\"ל וכמו כי חק לישראל הוא כו', ובחי' ח\"ע שיורד במדות ודיבור להיות התהוות עלמין אפי' עלמין סתימין כו' נק' בחי' יעקב יו\"ד עקב (והוא זווג יעקב ורחל ולאה במו\"ד כנ\"ל), וזהו ענין מדות שבתושב\"כ שיורדי' להאיר בתשבע\"פ כקול יעקב בקול דתורה שכולל ב' קולות דאותיות תשב\"כ שבהעלם ונק' קלא פנימאה כו' ובחי' קול בדיבור דחכ' תתאה דתשבע\"פ מל' קרינן לה כמו בעלמא דאתגלייא שנגלה למעשה דוקא בו\"ס משנה <span data-k=\"pg\">כו</span> ּ שנק' ס' מלכות [כו'] כנ\"ל, וזהו משפט לאלקי יעקב<sup data-n=\"789\">777</sup>",[["778","766","<b>דעקבי לאה. . ראש רחל</b>: ראה ע\"ח (שער לאה ורחל) של\"ח, פ\"ג. מאמרי אדה\"א ויקרא ח\"א ע' רנג ואילך. הנחות תקע\"ז ע' לה. וש\"נ. לקמן פ' בשלח קמג, ד."],["779","767","<b>עקב ענוה</b>: משלי כב, ד."],["780","768","<b>מה שעשתה ענוה</b>: ראה ע\"ח שם. שעה\"י קלט, א. תו\"ח ויצא קעג, ג הערה 20."],["781","769","<b>מאמר סתום</b>: נסמן לעיל יב, ב הערה 543."],["782","770","<b>שהים. . שיש ביבשה</b>: ראה חולין קכז, א. ירושלמי שבת פי\"ד, ה\"א. לקמן פ' בשלח קלט, סע\"א. קסב, א (ובהנסמן בריש המאמר שם). קפו, ג. מאמרי אדה\"ז תקס\"ב ח\"ב ע' ת ואילך. פרשיות התורה ח\"א ע' רנה ואילך וע' רסז ואילך. שער האמונה פד, א ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' נה. וש\"נ."],["783","771","<b>תדשא הארץ תוצא הארץ</b>: בראשית א, יא. כד."],["784","772","<b>בעלמין סתימין</b>: יאיז: בעלמ' דאתכסי'."],["785","773","<b>וכרקיע ע\"ג ראשי החיות</b>: יחזקאל א, כב."],["786","774","<b>ברוך ה' מן העולם</b>: תהלים קו, מח. דהי\"א טז, לו [בדילוג]. ראה גם מאמרי אדה\"א דברים ח\"א ע' קכד. וש\"נ. ש\"א עה, א. צג, ב. שה\"א פד, ב בהערה 11. לקמן לג, א. פ' וארא עה, ד. בשלח קלד, ג. קמג, ד. קסב, א. תצוה שלט, ג. שסז, א."],["787","775","<b>יעקב איש תם</b>: תולדות כה, כז."],["788","776","<b>יעקב. . בריח התיכון</b>: ראה זהר תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט."],["789","777","<b>כי חק. . משפט לאלקי יעקב</b>: תהלים פא, ה."]]],[2300541025,"וא' תתן אמת ליעקב דוקא לפי שהי' איש תם יושב אוהלים אהל דתושב\"כ ושבע\"פ<sup data-n=\"790\">778</sup> לפי שמבריח רת\"ס מן הקצה לקצה כנ\"ל וד\"ל).\n[כח] <b>ואחר</b> הקדמה זו יובן בדרך כלל בענין הירידה בגלות מצרים הנ\"ל שהי' בו ב' ירידות ירידה אחר ירידה כמ\"ש אנכי ארד עמך כו' (וכענין ירד ירדנו כו' כנ\"ל) ובחי' ירידה הא' זהו שא' בפ' ויגש ואלה שמות בנ\"י הבאים מצרימה יעקב ובניו כו', דהנה מבואר למעלה בבחי' ח\"ע שבראש כמו שהיא מתלבשת במוחי' דבינה (שזהו ספר וסיפור דתושב\"כ ושבע\"פ כמו שהן בחו\"ב, דספר בחכ' וסיפור בבינה, שזהו מוסר אביך ותורת אמך בחי' אימא עילאה דבינה ה\"א ראשונה כו', וזהו ג\"כ יחוד יש\"ס ותבונה בחיצוניות דבינה במל' דתבונה, שהן מדות דחכ' שנק' יש\"ס שיורדי' בפנימי' דמח' עיונית כנ\"ל) כשאינה יורדת במדות דמחשבה דבינה נק' ישראל לי ראש, אבל כשיורדת הח\"ע בבינה (כמו בראשית ברא אלקי'<sup data-n=\"791\">779</sup> דאבא א' לאימא<sup data-n=\"792\">780</sup> שהוא אלקי' אימא<sup data-n=\"793\">781</sup> עילאה דבינה) עד שמדות דח\"ע מתלבשי' גם בפנימי' דמח' בהעלם (שנק' מל' דתבונה) או גם במח' עצמה שמתאחד עם השכל יותר כנ\"ל זהו בחי' ירידה הא' שהוא ירידה דחכ' [ש]בראש לבחי' העלם דאותיות המח' דבינה בכלל. וזהו שנק' ג\"כ גלות מצרים למעלה שהוא בחי' מצר מ\"י<sup data-n=\"794\">782</sup> דבינה, שים דחכ' מתעלם ומתלבש במח' דבינה שנק' גבול ומיצר וצמצום דהשג' [ד]בינה כידוע, וכ\"ש מה שיכול להיות ממחשבה זו עלמין סתימין זהו בחי' צמצום והעלם גמור, דעלמין ל' העלם<sup data-n=\"795\">783</sup>, כמו אותיות המח' שהן אותיות מגבילים ומעלימים על גילוי אור א\"ס שבחו\"ב כו', וא\"כ ה\"ז בחי' ירידה וצמצום גדול עכ\"פ לבחי' עצמות אור דח\"ע כמו שהיא בעצם וגם בפנימי' בינה שנק' קדש העליון ויורד ומתצמצם במיצר וגבול דאותיות המח' (אפי' בפנימי' דמח' הנק' מל' דתבונה נק' מיצר מ\"י כו'), (וזהו כמו שמצמצם הסופר להביא גילוי אור דח\"ע באותיות דתשב\"כ שנק' ספר להיות מתלבש באותיות דתושבע\"פ כמו שהוא בהעלם במח' דבינה עדיין שנק' תורת אמך אימא עילאה (ונש\"י מתקשראי' בבחי' עיבור בבינה ה\"א עילאה (כמו רגל הקצר שבה\"א דאושיט פסיעה לבר שהן המדות דמל' שכלול בבינה כו' (כמ\"ש בזהר ע\"פ מראש צורים<sup data-n=\"796\">784</sup> כו' דמסט' דאימא אתמתח כו'). וזהו נובלות חש\"מ",[["790","778","<b>יושב אוהלים. . ושבע\"פ</b>: תולדות כה, כז. ראה מאמרי אדה\"א דברים ח\"א ע' ו. וש\"נ. תו\"ח בראשית מה, ג הערה 34."],["791","779","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["792","780","<b>דאבא א' לאימא</b>: ראה זהר בראשית כב, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרכה ואילך. וש\"נ. דברים ח\"ב ע' תרנא ואילך."],["793","781","<b>אימא</b>: יאיזיח: ליתא."],["794","782","<b>מצרים. . מצר מ\"י</b>: נסמן לקמן לז, ב."],["795","783","<b>דעלמין ל' העלם</b>: ראה ס' הבהיר (ס\"ח) ס\"י. פע\"ח (שער השופר) שכ\"ו, פ\"ה. לקו\"ת שלח לו, ג. מאמרי אדה\"א במדבר ח\"ג ע' תתקצה. נ\"ך ע' רב. וש\"נ."],["796","784","<b>רגל הקצר שבה\"א. . מראש צורים</b>: בלק כג, ט. זהר בלק רג, ב. ביאוה\"ז לשם קג, ג. תו\"ח נח נז, ג הערה 39. לקמן פ' תצוה שסז, ב. פקודי תנה, ג."]]],[2300541030,"דח\"ס וחכ' הקדומה תורה<sup data-n=\"797\">785</sup> שבחכ' דאבא ונובלות בינה ש\"מ שכינה עילאה דבינה [כו'] (ויש בזה ב' מדרגו' ג\"כ א' בחי' או\"א עילאי' שזהו חו\"ב בפנימי' ממש ואו\"א תתאין שהן יש\"ס ותבונה<sup data-n=\"798\">786</sup> בספר וסיפור דתושב\"כ ושבע\"פ ובשרש נש\"י שם בבחי' עיבור ולידה כנ\"ל). וזהו ענין הירידה הראשונה שהי' בחיי יעקב ובניו שירדו [ל]מצרים בע' נפש שא' בפ' ויגש ואלה שמות בנ\"י הבאים מצריימה, פי' בני ישראל דלעילא שנק' יש\"ס שזהו במדות דח\"ע שמלובש בבינה [ו]במל' דתבונה ביחוד פנימי שירדו ירידה גדולה במצרי[ם] שהוא מיצר מ\"י דבינה דהיינו להיות בבחי' עיבור בהעלם דמח' דבינה כו' כנ\"ל (וכ\"ז עדיין למעלה מבחי' המדות שנולדי' מן השכל ומח' הפנימי' הנ\"ל) ונק' ירידה א'. וז\"ש בירידה זו ואלה שמות בנ\"י כו' יעקב ובניו כו', פי' שגם בחי' יעקב בשם בני ישראל יכונה שנכלל בהם אע\"פ שנק' בנ\"י מאחר שמפרש מי הן בנ\"י יעקב ובניו כו'. והענין הוא כי בחי' יעקב זה היינו יו\"ד דחכ' כמו שהוא בעקב דנה\"י שזהו בחי' מדות שבלב שמקבלי' מיו\"ד דח\"ע שנק' קול יעקב שנמשך למו\"ד בהבל הלב שזהו לחיצוני' דאותיות מחשבה (שנק' קלא פנימא' כנ\"ל) <span data-k=\"pg\">54</span> ּ ולגילוי אותיות הדבור בפה שיוכל להיות התהוות העלמין סתימין ואתגליין שזהו א\"א כ\"א כאשר בחי' יעקב זה מקבל מחכ' ומדות בראש שנק' ישראל לי ראש (בחי' יש\"ס). וזהו שמפרש שבגלות וירידה הא' דח\"ע ומדות שבה שיורדי' ומתלבשי' עד מח' הפנימי' דבינה שנק' מיצר מ\"י (שזהו ספר וסיפור דחיצוני' דחו\"ב שנק' או\"א תתאי' כו') (וענין יצ\"מ זהו שיוצאי' המדות דז\"א שהוא יעקב ממיצר מ\"י דבינה כמבואר בכוונות דעבדים היינו כו' אנו בני ז\"א כו' כמ\"ש במ\"א בפי' בצאת ישראל ממצרים<sup data-n=\"799\">787</sup> כו') מי הן יעקב ובניו, שהן המדות שבלב שיוצאים בלידה וגילוי מן המיצר שבתחלה שהיו בירידה [ו]גלות במיצר מ\"י במח' בהעלם דבינה (וכמו אוי\"ר שכליי' שבבינה בהעלם שגם המדות שבלב ודיבור ומח' נכללי' שם בהעלם), ולכך כולל יעקב עם בניו יחד כי זהו בשרש המדות כמו שהן בהעלם במח' דבינה מח\"ע, שכל מה שיולד במדות שבלב גם במו\"ד שהן לאה ורחל שנק' בני יעקב נכללי' שם בבחי' עיבור והעלם כמו הבאים ישרש יעקב כו'. והיינו מה שבפ' ויגש אינו מונה כלל מספר השבטים כסדרן אלא רק יעקב ובניו בכלל, והוא לפי שמדבר בשרש המדות שהן בבינה ה\"א עילאה דמח' ששם הן רק בהעלם ועיבור דהיינו שכוללי' ע' נפש דיעקב בלבד שהן ז' מדות שכל מדה נחלקה לעשרה כו', ולכך בפ' ויגש שמדבר בביא' בנ\"י דלעילא ביריד' הא' במצרימה בלבוש שק [דמקיף] דז' מדות דק\"נ שבבינה לא מנה עדיין תולדות ושמות היב\"ש<sup data-n=\"800\">788</sup>",[["797","785","<b>נובלות חש\"מ. . תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["798","786","<b>ואו\"א תתאין. . יש\"ס ותבונה</b>: ראה שעה\"י קכו, ב הערה 10."],["799","787","<b>בצאת ישראל ממצרים</b>: תהלים קיד, א. ראה שה\"א קא, א ובהערה 7."],["800","788","<b>היב\"ש</b>: הי\"ב שבטים."]]],[2300541035,"כסדרן רק משפחת כל א' שכולל כל מה שעתיד להוליד אח\"כ כו' כמו בכור יעקב ראובן עד כל הנפש<sup data-n=\"801\">789</sup> כו', כמו שלמעלה בהעלם דמח' דבינה כלולי' [ה]ז' מדות ותולדות שלהם. וזהו ירידה הא' שבגלות מצרים שירדו יעקב ובניו במיצר מ\"י דמח' פנימי' והוא מה שנתלבשו שם בהעלם ועיבור (רק יוסף הוא השליט<sup data-n=\"802\">790</sup> כו' בחי' יסוד<sup data-n=\"803\">791</sup> צ\"ע שנק' מלך הגוים<sup data-n=\"804\">792</sup> אף בגלות זה כמ\"ש במ\"א), וזהו אנכי ארד עמך ירידה זו דאנכי הוא בחי' כתר<sup data-n=\"805\">793</sup> שבחכ' ומדות דיש\"ס שיורד עם בחי' יעקב במיצר מ\"י דמח' כנ\"ל וד\"ל.\n<b>אך</b> הנה בחי' ירידה הב' אחר ירידה זו שהי' בחיי יעקב ובניו ומשפחתו בראשית ביאתם למצרים כנ\"ל הוא שא' כאן ואלה שמות בנ\"י הבאים מצרימה את יעקב איש וביתו באו ראובן שמעון לוי<sup data-n=\"806\">794</sup> כו'. והענין הוא דהגם שלא הי' צריך לכפול עוד פעם ב' שבנ\"י באו למצרים אחר שכבר הזכיר בפ' ויגש בזמן ביאת יעקב ובניו למצרים ועתה מדבר בזמנו של משה ואהרן שכבר מתו כל הדור ההוא כו' כנ\"ל וא\"כ למה צריך להזכיר עוד הפעם לומר ואלה שמות בנ\"י הבאים כו', ואיך א' הבאים ל' הוה שבאים כעת ובאמת הלא כבר באו אבותיהם יעקב ובניו בע' נפש ואלה הנמצאי' עתה הן בני בניהם במספר רב יותר מת\"ר אלף כו'. אך הנה באמת הוצרך להזכיר פעם זה הב' ואלה שמות בנ\"י הבאים ממש כו', והוא ענין בחי' ירידה הב' אחר ירידה הא' שבחיי יעקב ובניו ע' נפש, [ש]בגלות הראשון הי' רק בחי' יריד' הח\"ע ומדות דישראל דלעילא בהעלם דמח' דבינה ולא יצאו המדות בגילוי בלב כלל שנק' מיצר מ\"י דבינה (וכידוע במ\"ש עבדים היינו לפרעה<sup data-n=\"807\">795</sup> שהוא עורף<sup data-n=\"808\">796</sup> דכתר<sup data-n=\"809\">*797</sup> דק\"נ שמעכב ומונע להיות הלידה דאוי\"ר שכליי' בלב ונשארו בהעלם במח' דבינה כו'). אבל ירידה ב' זהו לאחר שכבר יצאו המדות שכליי' דבינה ללב שנק' יעקב (או ז\"א ויש\"ז ) ונולדו בריבוי ענפי' <span data-k=\"pg\">כז</span> ּ בגילוי במו\"ד העליונים (שנק' עלמ[ין] כו' כנ\"ל), ולמטה הן ת\"ר אלף מספר בנ\"י שנולדי' מו' מדות דחיצוני' מח' שנק' לאה ודבור שנק' רחל (ששרשם הראשון אינו רק ע' נפש יוצאי ירך יעקב בהיותו בעיבור באימא עילאה דבינה כנ\"ל). אך ירידה זו באה במיצר הגרון שמתעכב שם ומתעלם ואינו בוקע ויוצא בה' מוצאו' הפה כלל, כמו אלם שא\"י לדבר דגם שיש בו מח' ודיבור בהבל הלב א\"י להוציא בפה, והוא מ\"ש נאלמתי דומי'<sup data-n=\"810\">797</sup> כו' בזמן גלות השכינה תתאה שהוא בחי' הדבור שהוא בבחי' אלם. וזהו שהי' משה כבד פה וכבד לשון<sup data-n=\"811\">798</sup>, ששרשו הי' בח\"ע<sup data-n=\"812\">799</sup> שבראש כמ\"ש מה שמו כו', וא\"ל ה' מי שם פה לאדם כו' (כמשי\"ת), וזהו ירידה הב'",[["801","789","<b>כל הנפש</b>: ויגש מו, כו. כז."],["802","790","<b>יוסף הוא השליט</b>: מקץ מב, ו."],["803","791","<b>יוסף. . יסוד</b>: נסמן לקמן פ' וארא פה, א."],["804","792","<b>יוסף. . שנק' מלך הגוים</b>: ראה מאמרי אדה\"א בראשית ע' רצד. תו\"ח וישב ריב, ד ובהערה 42."],["805","793","<b>דאנכי. . כתר</b>: ראה זהר (רע\"מ) פינחס רנו, ב."],["806","794","<b>ראובן שמעון לוי</b>: שמות א, ב."],["807","795","<b>עבדים היינו לפרעה</b>: ואתחנן ו, כא."],["808","796","<b>לפרעה. . עורף</b>: ראה לקו\"ת להאריז\"ל ר\"פ שמות. פע\"ח (שחה\"מ) שכ\"א, פ\"ז. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקיג. סידור סדר הגדה רצג, ג."],["809","*797","<b>לפרעה. . דכתר</b>: נסמן לקמן לב, ד."],["810","797","<b>נאלמתי דומי'</b>: תהלים לט, ג."],["811","798","<b>משה כבד פה וכבד לשון</b>: שמות ד, י."],["812","799","<b>משה. . ששרשו הי' בח\"ע</b>: נסמן לעיל יב, ד."]]],[2300541038,"דגלות מצרים במיצר מ\"י דמח' ודיבור במיצר הגרון בקול יעקב דוקא וד\"ל.\n<b>וביאור</b> הענין ידוע שזהו ענין הצמצום של המדות שבלב ומוח כאשר באים בקול הגרון בב[ו]או להתמשך בצירופי אותיות הדיבור כמו אחה\"ע מהגרון<sup data-n=\"813\">800</sup> וגיכ\"ק מהחיך כו', שהבל היוצא מן הלב הוא בחי' קול פשוט ממוזג מאש ומים ורוח<sup data-n=\"814\">801</sup> גשמיי' שמורכבי' אמ\"ר רוחני' שבמדות חד\"ר<sup data-n=\"815\">802</sup> שבחיצוני' המדות ושם מאיר גם מבחי' המחשבה שיוצא בגילוי בלב בגרון והגרון הוא מקום מיצר המצמצם הקול הרוחני שבלב ומוח להיות בהתחלקות בה' מוצאות [הפה] לבא בצרופים שונים והן ה\"ג מנצפ\"ך<sup data-n=\"816\">803</sup> דשם אלקים המחלק לאותיות בה' מוצאות ומצרפם באופנים שונים כמ\"ש במ\"א. וכך הוא למעלה בדיבור העליון כמו בי\"מ ויא' אלקי' יהי אור יהי רקיע<sup data-n=\"817\">804</sup> תדשא הארץ שיש בזה הרכבה מאמ\"ר דקול העליון שיוצא מבחי' הבל הלב דאדם העליון שהוא המדבר י\"מ כו' שמתחלק לה' מוצאות הפה העליון וכמ\"ש בס\"י וקבען בפה<sup data-n=\"818\">805</sup> וכמ\"ש ואתה מחיה<sup data-n=\"819\">806</sup> כו' א\"ת כ\"ב וה' מוצאות הכוללם כו'. ואמנם כמו שמבואר למעלה ביריד' דח\"ע ומדות בהעלם דמח' דבינה שמתעלם ומתעכב שם בלי יצא בגילוי בלב שנק' מיצר מ\"י, כך הוא ביציאה הב' מן המדות שבלב לאותיות הדבור ע\"י הקול הב' דיעקב שמתגלה בדיבור (וכמח' שמתלבשת בדיבור) שנק' מאמר פתוח (וכמ\"ש אך יצא יצא יעקב<sup data-n=\"820\">807</sup> ב' יציאות דיעקב אותיות יבקע<sup data-n=\"821\">808</sup>, דיציאה ובקיעה הא' דקול פנימאה דיעקב שכלול במח' דבינה שנולד בלב ויציאה ובקיעה הב' בקול יעקב ממדות שבלב לקול הגרון כו') שמתצמצם ומתעכב בקול דמיצר הגרון, וזהו ענין יצ\"מ בימי משה ואהרן שהוא בצאת ישראל ויעקב ממיצר הגרון כו'. וכך הוא בגלות האחרון שנק' אלם שהוא אותיות מאלקים<sup data-n=\"822\">809</sup> כמו נאלמתי כו' וא' אין כמוך באלמי'<sup data-n=\"823\">810</sup> כו' שהשכינה שהוא הדבור במיצר וגלות דע\"ש שנק' לבוש שק וכמו כרחל לפני גוזזי' נאלמה<sup data-n=\"824\">811</sup> כמ\"ש במ\"א. וזהו אלביש שמים קדרות במח' דבינה שהוא ירידה הא', ושק אשים כסותם בלבוש שק דעור דהיינו גבו' קשות דמ\"ח צירופי' האחרוני'<sup data-n=\"825\">812</sup> דשם אלקים שנאחזים במל' בזמן הגלות שזהו באלם<sup data-n=\"826\">813</sup> [מ]אלקים והוא נש\"ט דמצרים שהי' בחי' הסתר גמור לאלקי' שהוא שם ב\"ן<sup data-n=\"827\">814</sup> דמל' ה\"א תתאה כו' (משא\"כ בימי יעקב ובניו ביריד' הא' הי' הגלות",[["813","800","<b>אחה\"ע מהגרון</b>: ראה ס\"י פ\"ב, מ\"ג. הנסמן במאמרי אדה\"א דברים ח\"א ע' קה."],["814","801","<b>שהבל. . מאש ומים ורוח</b>: ראה זהר תצוה קפד, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תרנא. דברים ח\"ג ע' תתק. קונטרסים ע' תקמט ובהנסמן בהנ\"ל."],["815","802","<b>חד\"ר</b>: חסד דין רחמים."],["816","803","<b>ה\"ג מנצפ\"ך</b>: ראה שער היחוה\"א ספ\"ד. סה\"מ ליקוט ח\"ב ע' מא. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רלז."],["817","804","<b>יהי רקיע</b>: בראשית א, ו."],["818","805","<b>וכמ\"ש בס\"י וקבען בפה</b>: ראה שם פ\"ב, מ\"ג."],["819","806","<b>ואתה מחיה</b>: נחמי' ט, ו. ראה זהר בראשית טו, ב. (היכלות) פקודי רסא, א. שער היחוה\"א פ\"ב."],["820","807","<b>אך יצא יצא יעקב</b>: תולדות כז, ל. ראה ע\"ח שבהערה הבאה."],["821","808","<b>דיעקב אותיות יבקע</b>: ראה ע\"ח (שער הארת המוחין) של\"ב, פ\"א. תו\"ח וישלח קפה, ב בהערה 17."],["822","809","<b>אלם. . מאלקים</b>: ראה ע\"ח (שער מוחין דקטנות) שכ\"ב, ספ\"ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תפו."],["823","810","<b>אין כמוך באלמי'</b>: ראה גיטין נו, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרז. מאמרי אדה\"א קונטרסים ס\"ע תקעב ואילך. וש\"נ."],["824","811","<b>כרחל לפני גוזזי' נאלמה</b>: ישעי' נג, ז [ושם: וכרחל — ראה תו\"ח ויצא קסו, ג הערה 53]."],["825","812","<b>דמ\"ח צירופי' האחרוני'</b>: נסמן לקמן ל, ב."],["826","813","<b>באלם</b>: יח: ב' אל\"ם."],["827","814","<b>לאלקי' שהוא שם ב\"ן</b>: ראה רמ\"ז לזהר משפטים צז, א (ע' קפא ואילך בדפי הספר). תו\"ח ויצא קסו, א הערה 9. שם ח\"ש קכז, רע\"ב. ש\"א י, ב. שע\"ת מח, ג הערה 28. לעיל י, א. לקמן פ' בשלח קנו, ג. יתרו רסג, ד. ערב, ב. תרומה שיג, א. תצוה שכה, ד. שכט, א. ויקהל תה, ד. תכה, א."]]],[2300541041,"בהעלם לבד כי יוסף חי ומושל בכל אמ\"צ<sup data-n=\"828\">815</sup> וכל טוב מצרים היו אוכלי'<sup data-n=\"829\">816</sup> ומברכי' כו' כמ\"ש ויברך יעקב את פרעה<sup data-n=\"830\">817</sup> כו'). אבל בגלות זה בדור החדש <span data-k=\"pg\">56</span> ּ שקם מלך חדש כו' לא ידע את הוי' כלל וא' מי הוי' אשר<sup data-n=\"831\">818</sup> כו', כי שם הוי' דחכ' ומדות דאצי' נתעלם לגמרי בצמצום דחיצוני' ואחוריי' דאלקי' באותיות הדבור כנ\"ל). (וזהו ג\"כ ענין ירידה וגלות ב' בתשבע\"פ בחי' חכ' שבדיבור שחוגרת שק דק\"נ כנ\"ל בעמל תורה בפלפול שנק' עב\"ק בחו\"ל כו' וימררו חייהם דכנ\"י בשרשם במל' בו\"ס משנה שהן ס' מלכות כו' כנ\"ל שהוא ג\"כ ענין צמצום דקול יעקב דתורה בקול החיצון שנמשך [ממדות ד]חכ' דתושב\"כ שנק' ספר לדיבור דתושבע\"פ (כידוע שתושב\"כ ושבע\"פ הן בב' מדרגות בחו\"ב ויש\"ס ותבונה הנ\"ל שנק' או\"א עילאי' ותתאי' כנ\"ל, ובזו\"נ דז\"א הוא יעקב במדות דאצי' שבא באותיות דתושב\"כ לנוק' שהוא בחי' שם ב\"ן דמל' בדיבור דו\"ס משנה, וזהו הקל קול יעקב ב' קולות שהן ב' בקיעות ויציאות הנ\"ל וד\"ל).\n<b>וזהו</b> שהי' משה כבד פה וכבד לשון כו' דבגלות מצרים בירידה הב' כנ\"ל הרי הי' אור דח\"ע בח\"ת שהוא בא ונמשך בדיבור בצמצום והעלם כמו בבחי' אל\"ם כמו נאלמתי דומי' כו', ושרש משה הי' בח\"ע דתושב\"כ ובע\"פ שזהו פה ולשון כמ\"ש בר\"מ כבד פה בתושבע\"פ וכבד לשון בתושב\"כ כו', והוצרך להיות [אהרן] אחיו לו לפה וכמ\"ש אהרן אחיך יהי' לך לפה<sup data-n=\"832\">819</sup> ואתה תהי' לו לאלקי' כמו שאלקי' מדבר בפי הנביא שאלקי' עצמו הוא בבחי' העלם והסתר בדיבור זה, וזהו לאלקי' דוקא בבחי' הצמצום דשם אלקי' כמו שהוא במיצר הגרון בהעלם כנ\"ל וד\"ל. וזהו שטען משה הן אני ערל שפתים<sup data-n=\"833\">820</sup> כו' שבנ\"י לא שמעו ואיך ישמע אלי פרעה לפי שעצם אור דח\"ע א\"א לבא בדיבור בגילוי רק ע\"י לבוש שק המסתיר וא\"כ איך ישמע אלי פרעה, אך השיבו ה' מי שם פה לאדם כו' דאע\"פ שמיצר הגרון מפסיק ומעלים להיש בו'<sup data-n=\"834\">821</sup> המדות דח\"ע שבמו\"ד מ\"מ גם בדיבור מאיר מאור דח\"ע שבראש עם המדות שבלב בקול יעקב, כי שרש האותיות דדיבור קשורים ואחוזי' ומיוחדים במקורן ושרשן בח\"ע, דאבא יסד ברתא שזהו בחי' ישראל לי ראש, והוא לפי שיש בצירופי' דאותיות הדיבור מהעלם דח\"ע בגילוי ממש וכמ\"ש לא יעקב יאמר עוד<sup data-n=\"835\">822</sup> כו' כ\"א ישראל וכן א' ולא יקרא עוד כו', הרי גם בבחי' יציא' וירידה דיעקב בקול הגרון בה\"מ<sup data-n=\"836\">823</sup> הפה נק'",[["828","815","<b>יוסף חי ומושל בכל אמ\"צ</b>: ע\"פ ויגש מה, כו."],["829","816","<b>טוב מצרים היו אוכלי'</b>: ראה שם מה, יח. יט. מז, יא."],["830","817","<b>ויברך יעקב את פרעה</b>: ויגש מו, ז."],["831","818","<b>מי הוי' אשר</b>: שמות ה, ב."],["832","819","<b>אהרן אחיך יהי' לך לפה</b>: שמות ד, יד. טז."],["833","820","<b>הן אני ערל שפתים</b>: וארא ו, ל. יב."],["834","821","<b>להיש בו'</b>: יזיח: להמשכות."],["835","822","<b>לא יעקב יאמר עוד</b>: וישלח לב, כט."],["836","823","<b>בה\"מ</b>: בה' מוצאות."]]],[2300541044,"ישראל לי ראש כמו שהח\"ע בראש ממש בלי שינוי כלל. וזהו שגם שהי' משה כבד פה כ[נ\"ל] הרי הי' על ידו דוקא כל גילוי האורות מבחי' נפלאות העליוני' באותות ומופתי' גדולים ונוראים שהראה לפני פרעה וחרטומי מצרים שא\"א להיות נסים ונפלאות כאלה להפוך הטבע החושיי' ואנושי' כמו להפוך ממים לדם וממטה לנחש וכה\"ג אם לא ע\"י שינוי הצירופי' דאותיות שבדבור העליון דוקא, כמו ברחב\"ד שהיפך מחומץ לשמן א' מי שא' לשמן וידליק<sup data-n=\"837\">824</sup> הוא יאמר לחומץ, דמי שאמר בצרופי אותיות האלקי' המטביעי' כל טבע דאלקי' גימ' הטבע דד\"י<sup data-n=\"838\">825</sup> הוא ישנה הצירוף דחומץ להיות בצירוף דשמן וממילא ידליק כו'. וכך הוא בכל הנסים שנעשי' בהיפוך הטבע שהוא לשנות הצירופי' שבאותיות הדבור שנמשך בי\"מ וצרופי צרופיהן הבא בריבוי ההשתלשלו' וכללותם הן ק\"ך צירופי' דשם אלקי'<sup data-n=\"839\">826</sup> כידוע, א\"א להיות זה כ\"א ע\"י שינוי אור הח\"ע שבראש שנמשך במדות שבלב בקול הגרון באותיות הדיבור העליון לשנות בצרופי' דשם אלקי' בכלל ובפרט, וא\"כ שרש שינוי הזה בשם הוי' דח\"ע שנמשך בח\"ת דדיבור שזהו ע\"י משה דוקא ששרשו <span data-k=\"pg\">כח</span> ּ בח\"ע ונמשך בדבור דוקא וכמו ואתה תהי' לו לאלקי' דוקא לשנות הצירופי' שבדבור [ב]י\"מ כמו להפוך ממים לדם, והיינו לפי שא\"ל ה' מי שם פה לאדם כו' ואנכי אהי' עם פיך<sup data-n=\"840\">827</sup> כו' דמה שהי' משה כבד פה מצד הגלות ביריד' הב' אבל גם חשך לא יחשיך<sup data-n=\"841\">828</sup> ממנו ויאיר גם בלבוש שק דנוגה בלתי יסתיר כלל ומטעם הנ\"ל דח\"ע יורד בגילוי גם בח\"ת בדיבור כו' (וכה\"ג הוא בהמשכו' דח\"ע בח\"ת בתושבע\"פ אפי' בעמל דתורה שחוגרת שק דק\"נ בהסתר בקושיו' כו' שמסתירי' אור האמת כנ\"ל, מ\"מ מתברר מחשך לאור ומטעות ושקר לאמת כו' ונק' ליבון הלכתא כנ\"ל, וזהו הכל ע\"י משה שתורה ציוה לנו בע\"פ כו' כנ\"ל).\n<b>ובכ\"ז</b> יובן מה שבימי הגלות דיעקב ובניו לא הוצרכו לאותות ומופתים כלל<sup data-n=\"842\">829</sup> לפני פרעה הראשון כי הי' גילוי דאור ח\"ע ומדות דישראל ויעקב ובניו במח' דבינה שלמעלה מאותיות הדבור בי\"מ, ואע\"פ שהי' בהעלם דמיצר מי כנ\"ל מ\"מ הרי הי' כל ברכה ושפע האלקי' בפרעה ובנהר נילוס ע\"י יעקב וישראל העליון דוקא כמ\"ש ויברך יעקב את פרעה. ולזאת הי' ביטול גדול בפרעה וזקניו לפני יעקב ויוסף וכל הדור ההוא והאמינו בהוי', ואע\"פ שמרחוק הוי' נראה להם<sup data-n=\"843\">830</sup> ע\"י לבוש ומקיף דבינה שז\"ש אלביש שמים כו', משא\"כ בירידה זו הב' בלבוש שק דאותיות הדבור בחיצוניו' ואחוריים דשם אלקים במ\"ח צירופי'",[["837","824","<b>מי שא' לשמן וידליק</b>: תענית כה, א (כגי' הע\"י). ראה לקמן פ' בשלח קצה, ג. יתרו רסד, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קעח. ע' ערב ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"ב ע' שלב. וש\"נ. שע\"ת יד, ג ובהערה 28."],["838","825","<b>דד\"י</b>: דד' יסודות."],["839","826","<b>ק\"ך צירופי' דשם אלקי'</b>: ראה ע\"ח (שער הזיווגים) שט\"ו, פ\"ו. (שער השמות) שער מ\"ד, פ\"ה. הנסמן במאמרי אדה\"א שמות ח\"א ע' קלז."],["840","827","<b>ואנכי אהי' עם פיך</b>: שמות ד, יב."],["841","828","<b>גם חשך לא יחשיך</b>: תהלים קלט, יב."],["842","829","<b>לא הוצרכו לאותות ומופתים כלל</b>: ראה תנחומא נשא כו הובא ברש\"י ויגש מז, י. תוספתא ספ\"י דסוטה הובא ברש\"י שם, יט."],["843","830","<b>שמרחוק הוי' נראה להם</b>: ע\"פ ירמי' לא, ב."]]],[2300541047,"האחרוני' שנק' ארץ חם<sup data-n=\"844\">831</sup> כידוע, לא האמינו בהוי' כלל ועבדו בבנ\"י בפרך והיו כל האותות ומופתים בפרעה רק למען ידעו את שם הוי' דוקא כמ\"ש וידעו מצרים כי אני הוי'<sup data-n=\"845\">832</sup> כו' (כמ\"ש במ\"א). וזה הי' ענין האותות ומופתים בכלל בי' מכות דמצרים רק להיות היפך הצירופי' דטבע בשם אלקים עצמו, כי פרעה דק\"נ שמסתיר בלבוש שק דטבע גימ' אלקים א' מי הוי' אשר אשמע בקולו, כ\"א שם אלקים בצמצום האחרון שמלובש ומוסתר במ\"ח צירופי' האחרוני' דוקא כנ\"ל במ\"ש ושק אשים כסותם. אך ע\"י בחי' הארה דמ\"ה דח\"ע דמשה בפה דאהרן שהוא מקור הראשון דמו\"ד ומדות למעלה בחכ' שבראש כנ\"ל משם דוקא יוכל להיות שינוי הצירופי' בשם אלקי' לשנות סדרי מע\"ב מן הקצה, וכמו עד\"מ באדם למטה שיוכל לשנות הצירופי' שבדבור ע\"י הארת אור השכל שבמוח שמנהיג ומשנה את צרופי אותיות הדבור כרצונו אף בלבוש דקול מיצר הגרון כו' כנ\"ל וד\"ל. וכמו ששינה הצירוף דמים להיות בצירוף דדם וע\"כ נהפ[כו] המים לדם, כי הצירוף דהתהוות המים שבארץ ממ\"ע שמעל לרקיע שא' יקוו המים וירדו לארץ בגערה ונזיפה<sup data-n=\"846\">833</sup> להיות בצמצום דיבשה כמ\"ש יקוו המים כו' מתחת לארץ שנק' מ\"ת שמעורבי' טו\"ר בנהר נילוס שהוא פישון שיצא בבחי' פירוד מג\"ע כו', ובגזירת הדיבור העליון מח\"ע שבראש נהפך המ\"ת הללו לדם שזהו יניק[ה] דגבורות קשות שבדם שגובר על החסדי' דמים שזהו קליפ' דנש\"ט דמצרים שנלקו ברע שלהם כו' וד\"ל. וכך הי' שאר המכות [כ]צפרדע וכנים ערוב כו' שכ\"ז בחי' פסולת דגבו' קשות שנבדלו מבחי' הטוב דקדושה בשינוי הצירופי' דשם אלקי' דוקא ע\"י שם הוי' דתבר שלשליהון למעלה<sup data-n=\"847\">834</sup> כו' כמ\"ש במ\"א וד\"ל).\n<b>וזהו</b> שהי' ההתחלה לכל האותות ומופתים שבי' מכות במה שציוה למשה להפוך המטה שבידו לנחש ומנחש נהפך למטה כמבואר, שזה הדבר הי' מקור ושרש לשינויי <span data-k=\"pg\">58</span> ּ הצירופי' מטוב לרע בי' מכות כמו ממים לדם וצפרדע וכה\"ג, כי מטה האלקי' שביד משה הי' שרשו מעה\"ח דפנימי' הח\"ע שלא הי' שם שבירה כלל ונתלבש בעה\"ד טו\"ר ונהפך לנחש להאיר גם בק\"נ שמקבלי' מנחה\"ק שיהיו נכנעים תח\"י הקדושה, ולזאת מיד נהפך מנחש למטה להורות שאין שינוי אור האלקי כלל בלבושי' דק\"נ דגם חושך כו' ומושל בק\"נ כמו בקדושה, כמו ויאמר ה' אל הנחש ואל בלעם<sup data-n=\"848\">836</sup> כו', שזהו מה שיכול להיות מהעלם דחשך אור ואור לחשך כו' דקמי' כחשיכה כאורה<sup data-n=\"849\">837</sup> כו'. וכן מה שהראה אות האחרון שא\"ל הבא ידך בחיקך והוציא' מצורעת",[["844","831","<b>ארץ חם</b>: ראה תהלים קה, כג. כז. קו, כב."],["845","832","<b>וידעו מצרים כי אני הוי'</b>: וארא ז, ה. בשלח יד, ד. יח. ראה לקמן פ' בשלח קפא, ג. יתרו רעא, ב ואילך. תו\"א וארא נז, א. מאמרי אדה\"ז תקס\"ה ח\"א ריש ע' קלג וע' קצ ואילך. הנחות הר\"פ ע' יז ואילך."],["846","833","<b>יקוו המים. . בגערה ונזיפה</b>: בראשית א, ט. מובא לקמן פ' בשלח קנג, ב בשם המדרש. ראה ב\"ר פ\"ה, א. פדר\"א פ\"ה. שוח\"ט פצ\"ג, ג. תו\"ח תולדות קמג, ב הערה 30."],["847","834","<b>דתבר שלשליהון למעלה</b>: ראה לקמן מא, ג. וש\"נ."],["848","836","<b>ויאמר ה' אל הנחש ואל בלעם</b>: בראשית ג, יד [ושם: ה\"א]. בלק כב, יב."],["849","837","<b>כחשיכה כאורה</b>: תהלים קלט, יב."]]],[2300541050,"כשלג שזהו נגעי בנ\"א<sup data-n=\"850\">839</sup> בק\"נ ויאמר השב ידך<sup data-n=\"851\">838</sup> כו' והנה שבה כבשרו שיכול להפוך מנגע לענג<sup data-n=\"852\">840</sup> כמו מפשע שפע<sup data-n=\"853\">841</sup> כו' כמ\"ש במ\"א<sup data-n=\"854\">835</sup> וד\"ל. ולכך היו כל המופתים ע\"י משה דוקא לפי שהי' כבד פה ולשון בתושב\"כ ושבע\"פ למעלה מבחי' ח\"ע וח\"ת כמ\"ש כי מן המ\"ע משיתיהו מבחי' העלם דאין דחכ' הקדומה ונמשך לח\"ע וח\"ת כמו באותיות דתושב\"כ ושבע\"פ שנק' ספר וסיפור וסופר כנ\"ל, ולכך דוקא ביכולתו הי' לשנות הצירופי' דדבור ולעשות מהעלם גילוי ומגילוי העלם כו' כנ\"ל וד\"ל.\n[כט] <b>וזהו</b> ואלה שמות בנ\"י הבאים מצריימה את יעקב איש וביתו באו כו', פי' את יעקב דוקא איש וביתו באו ואינו סותר לרישא שא' ואלה שמות בני ישראל ולא א' בני יעקב כנ\"ל, דמ\"ש ואלה שמות בנ\"י קאי על בחי' ישראל דלעילא שנק' לי ראש דח\"ע כנ\"ל שיורד ומתצמצם ירידה וצמצום ב' מן המח' שבבינה לדיבור בקול הגרון במיצר, שזה הצמצום דבנ\"י שהן בחי' מדות דח\"ע נמשכי' ויורדי' את יעקב דוקא שהן מתחברים עם בחי' המדות שבלב שנק' יעקב שנולדי' מן השכל שבמוח וכאן נק' בנים<sup data-n=\"855\">842</sup> שלמטה (שנק' יש\"ז ). וזהו את יעקב טפל ליעקב לפי שהמדות הללו דו\"ק כפולי' די\"ב שבטי' שבנוק'<sup data-n=\"856\">843</sup> עולם הדיבור שהן שנק' בשמותם ראובן שמעון לוי כו', הן שיוצאי' בגילוי אותיות הדיבור בקול יעקב החיצון בבחי' מל' כשבט שיוצא מן האילן והן טפלי' ליעקב, ולכך הן במהו' בריאה בפ\"ע כל א' וא' נק' איש וביתו כמ\"ש בזהר ע\"פ איש על דגלו [באותות] לבית אבותם כו' שכל דגל ומחנה נבדלת במדרגה מיוחדת כמו בד' מחנות שכינה וכללותם הוא י\"ב צירופי' דשם הוי'<sup data-n=\"857\">844</sup> שבא בגילוי באותיות בדבור ונק' צבאות הוי' (שזהו העלי' הא' שיצאו ממיצר וגלות זה דבחי' הדיבור מקטנות דאלם הנ\"ל (וכשבאו<sup data-n=\"858\">845</sup> בירידה וצמצום להתלבש בלבוש שק דנוגה זהו בחי' ירידה הב' הנ\"ל בעלמין דאתגליין בדבר ה' שמלובש בתוך כ\"ע כו' כנ\"ל בבחי' הסתר והעלם אחר העלם עד מ\"ח צירופי' האחרוני' הנ\"ל בלבוש הטבע המסתיר ששם א' אותותינו לא ראינו, פי' אותות ומופתים ששייך אלינו שנק' נפלאות ה' שיתגלה לע\"ל כמ\"ש כימי צאתך מאמ\"צ אראנו נפלאות.\n<b>והענין</b> הוא דזה הפסוק בזמן הגלות נא' שא' אתה אל מסתתר שכח האלקי מוסתר הכל בהנהגות הטבע דוקא, ואף הנסים שנעשו הן מל[ו]בשי' הכל בדרך הטבע עצמה כנס דאחשורוש ואסתר שהי' בהתלבשות בדרך הטבע, וכן נס דחנוכה שגברו<sup data-n=\"859\">846</sup> בנ\"ח<sup data-n=\"860\">847</sup> וכה\"ג, ואע\"פ שהן נסים ונפלאו' ממש כאותן ניסים ונפלאות שנעשו בגילוי בהיפוך הטבע, רק",[["850","839","<b>נגעי בנ\"א</b>: נסמן לקמן מב, ג."],["851","838","<b>הבא ידך. . השב ידך</b>: ראה שמות ד, ו. ז. ראה גם לקמן מב, ג."],["852","840","<b>מנגע לענג</b>: ראה ס\"י פ\"ב, מ\"ד ובמפרשים שם. מאמרי אדה\"א דברים ח\"א ע' שכח. וש\"נ. שע\"ת נג, ד הערה 40. לקמן מב, ג. פ' בא קכג, ג. תצוה שמג, ג."],["853","841","<b>מפשע שפע</b>: ראה זהר (אד\"ר) נשא קלג, א. מאמרי אדה\"א דברים ח\"א ע' שז. וש\"נ. הנחות תקע\"ז ע' רמז. תו\"ח בראשית כח, ב הערה 10. לקמן פ' תצוה שמג, ג."],["854","835","<b>להפוך המטה שבידו לנחש. . כמ\"ש במ\"א</b>: ראה לקמן לז, סע\"ב ואילך. מא, ד ואילך."],["855","842","<b>בנים</b>: יזיח: בני ישראל."],["856","843","<b>די\"ב שבטי' שבנוק'</b>: נסמן לקמן פ' בא קכז, ד."],["857","844","<b>י\"ב צירופי' דשם הוי'</b>: ראה שערי אורה [לר\"י גיקטלייא] ש\"ה [סה, ב]. תניא פמ\"א ובספר שיעורים בתניא ע' 547. סה\"מ תרל\"ה ח\"א ע' קסו ד\"ה בענין. מכתב לר\"י פייגין נדפס ברשימות חוברת קמא."],["858","845","<b>הנ\"ל (וכשבאו</b>: יא: הנ\"ל) וכשבאו."],["859","846","<b>שגברו בנ\"ח</b>: יא: שקבעו בנר חנוכה."],["860","847","<b>בנ\"ח</b>: בני חשמונאי."]]],[2300541053,"שנעלמ[י'] מאד ומתלבש[י'] בדרכי הטבע ממש עד שאותותינו השייכי' ונעשי' בשבילנו דוקא לא ראינו בעין בגילוי כנסים ונפלאות שעשה במצרים בהיפוך הטבע וכקי\"ס וכה\"ג. וזהו מדבר אחר חורבן הבית שאין נביא ואין אתנו יודע<sup data-n=\"861\">848</sup> כו' שלא נגלה אור האלקי כמו שהוא בעצם באותיות העליוני' שבי\"מ הרוחני', <span data-k=\"pg\">כט</span> ּ שמה שמתהווה מאין ליש מכח האותיות הללו נעשי' בבחי' יש גמור להסתיר על כח האלקי שבהן רק לפרקי' מתגלה בחי' האין של היש כמו שהוא באלקי' אז נעשה בהיפוך הצירופי' שכבר הוטבעו כמו שא' מי שא' לשמן וידליק כו' כנ\"ל, שזהו ההארה מעלמא דאתכסי' בצירופי' דמח' שמאיר בדבור לשנות הצירופי' כנ\"ל לכך נק' נפלאות מלשון הפלא והעלם דבר שנפלא מאד אף בעולם הדיבור כו' (ומטעם זה הרואה מקום גשמי שבו נעשה הנס חייב לברך<sup data-n=\"862\">849</sup> בשם הוי' דוקא כו'), (וכמו סוד ה' שברזי' דאוריי' שנעלם מכל השגה שכלי' ובא לגילוי כמו בהשגה ממש שאז נק' נפלאות כפלאות דח\"ע, כך הוא בנסים שנעשו בדרך פלא למעלה מסדרי מע\"ב באותיות די\"מ כו'). וזהו שא' אותותינו לא ראינו שיתפרש גם בבחי' אותיות ממש, שזהו בחי' אותיות העליוני' דמח' שבעלמין סתימין ועלמין דאתגליין כמו שהן בבחי' אלקי' טרם שנברא מהן מאין ליש בחי' עלמין כו' שהוא לשון העלם ולבוש כו', שאותיות אלה הן בחי' אורות עליוני' במדות וח\"ע דאצי' של[שון] אות הוא המצויין לאות וסימן לדבר נבדל ונפלא בערך מהכל כו' כמו איש על דגלו באותות כו' באותיות שלהם בשרשם במו\"ד כמא' ישראל עלו במח' (שהוא יחוד פנימי דאו\"א ליחוד יש\"ס ותבונה ו[כ]יח\"ת דזו\"נ במדות ודבור בפנימי' כידוע), וגם בחי' אותותינו שלנו לא ראינו שיבאו בגילוי מן ההעלם דח\"ע ומדות כמו שהן למעלה ממש כמו בנפלאו' עליוני' שנעשו בהיפוך הצירופי' לפי שאין נביא ואין אתנו כו', שהנבואה והיודע בסוד ה' זהו בפנימי' דאותיות המו\"ד העליוני' שהחיצוני' שלהם מחי' עלמין סתימין ואתגליין (כגעה\"ע וגעה\"ת וכה\"ג) כי הנביא מתגלה בו דבר ה' בגילוי כמו שה[ו]א למעלה, ל' ניב שפתים כו'), ולכך א' אותותינו דוקא שהן בחי' פנימי' הדיבור והמח' שאינו שייך רק אלינו לא ראינו בזמן הגלות לפי שזהו בגלות בבחי' אלם דקטנות כמ\"ש מי כמוך באלים<sup data-n=\"863\">850</sup> אין כמוך באלמים כו' כנ\"ל, וכשהדיבור הפנימי' בגלות בלבוש שק דנוגה אזי הכל מתנהג בדרכי הטבע כמו הניסים שנעשו דרך הטבע דוקא כנ\"ל, שהן אותות דאותיות העליוני' שמתנהגי' בלבוש זר כו' אע\"פ שהן נסים ונפלאו' העליוני' ממש בלי שינוי כלל כנ\"ל (וכמו שא' לא ינום ולא יישן<sup data-n=\"864\">851</sup> כו' שמשגיח בעינא פקיחא דלא נאים<sup data-n=\"865\">852</sup> לסבב סיבות בדרכי הטבע דוקא לעשות הנס הנפלא כנס דמפלת המן שהי'",[["861","848","<b>שאין נביא ואין אתנו יודע</b>: המשך הכתוב אותותינו לא ראינו."],["862","849","<b>הרואה מקום. . הנס חייב לברך</b>: ברכות נד, א. ראה שע\"ת ח\"א יד, ג ואילך ובהערה 27."],["863","850","<b>מי כמוך באלים</b>: בשלח טו, יא."],["864","851","<b>לא ינום ולא יישן</b>: תהלים קכא, ד."],["865","852","<b>בעינא פקיחא דלא נאים</b>: ראה זהר [אד\"ר] נשא קכט, סע\"ב ואילך. הנסמן במאמרי אדה\"א נ\"ך ע' תג."]]],[2300541056,"ע\"פ סיבה דנדדה שנת המלך<sup data-n=\"866\">853</sup> כו' וע\"י אהבת אסתר וכה\"ג, וכך בכל דור ודור עומדי' לכלות<sup data-n=\"867\">854</sup> לישראל ברוחניו' ובגשמיות ונתבטל ע\"פ הטבע דוקא באופן שאין בעה\"נ מכיר בניסו<sup data-n=\"868\">855</sup> כלל [וכלל] כידוע (וכדוגמא זו הן ההלכות שנתחדשו ע\"י פלפול בסברו' שע\"פ שכל אנושי אחר הבירור מכל טעות ושקר כו', שאותיות התורה דח\"ע שנק' קדש מלובש בהתלבשו' דלבוש הטבע בשכל ופשט וגם במקראו' המדברי' בפשוטו ממש שאין מקרא יוצא כו' שמלבישי' ומעלימי' לאורות העליוני' דח\"ע באותיות הללו דספר וסיפור כפשוטם כו'), (וזהו שר\"ת הריעו לה' כל הארץ הלכה<sup data-n=\"869\">856</sup> שמלובש בטבע, ור\"ת השתחוו לה' בהד\"ק קבלה<sup data-n=\"870\">857</sup>, דקבלה באצי' ותלמוד בבריאה ומקרא בעשי'<sup data-n=\"871\">858</sup> כו' וקבלה הן ברזי' דאוריי' שבזהר ור\"מ שנק' פלאו' ח\"ע<sup data-n=\"872\">*859</sup> כנפלאו' ונסים שלמעלה מן הטבע כמ\"ש <span data-k=\"pg\">60</span> ּ במ\"א).\n<b>אך</b> הנה בכאן הרי הי' היפך בחי' הגלות בצאתם ממצרים שהוא הגאולה והעלי' מירידה הב' שנז' למעלה, דמאחר שירד יעקב ב' ירידות זו למטה מזו כנ\"ל שזהו [ב]מחו\"ד ע\"כ כאשר צריך לעלות יעלה תחלה [מ]מקום שירד למטה בירידה הב' שהוא בבחי' קטנו' דהעלם ולבוש שק המסתיר לאותיות הדבור דבחי' מל' ה\"א תתאה כנ\"ל (וז\"ש אנכי ארד עמך מצרימה בירידה הא' וכן בירידה זו הב' דגלות בחו\"ל, ואנכי אעלך גם עלה הן ב' עליות זו למעלה מזו, דעלי' הא' שא' ואנכי אעלך זהו עלי' דנש\"י מגלות מצרים בנש\"ט כו' שיוציאם ממיצר וחשך גמור לאור גדול שהוא מ\"ת פב\"פ בבחי' הדבור דוקא, וגם עלה עלי' ב' נגד ירידה א' דמח' דבינה שזהו גם לרבותא<sup data-n=\"873\">**859</sup> על[י' הג'] בעוה\"ב ותחה\"מ אחר ימות המשיח כנ\"ל שע\"ז א' אראנו נפלאות תרין<sup data-n=\"874\">859</sup>, פלא אחר פלא דסדכ\"ס<sup data-n=\"875\">860</sup> כו', ופי' אראנו ליש\"ס<sup data-n=\"876\">861</sup> כמ\"ש בזהר (וכמשי\"ת שז\"ש עד יעבור עם זו קנית כנ\"ל).\n<b>וביאור</b> הענין הנה זהו שא' ואלה שמות בנ\"י הבאים בירידה זו הב' במצרים בגלות בחו\"ל את יעקב דוקא שהוא קול בדיבור איש וביתו שזהו מה שנמשך מדות שבדיבור בגילוי ובמספר שמות ראובן שמעון לוי כו' כדי שיעלו מירידה זו לעלי' דמ\"ת פב\"פ דוקא כנ\"ל, והענין הוא דגם שבגלות א' אותותינו לא ראינו כנ\"ל אבל כשצריך להיות הגאולה שהוא",[["866","853","<b>דנדדה שנת המלך</b>: אסתר ו, א."],["867","854","<b>בכל דור ודור עומדי' לכלות</b>: ע\"פ נוסח ההגדה."],["868","855","<b>שאין בעה\"נ </b>[ בעל הנס]<b> מכיר בניסו</b>: ראה נדה לא, א. לק\"ט חוקת כא, טו. לקמן פ' בשלח רלו, ב."],["869","856","<b>שר\"ת הריעו. . הלכה</b>: תהלים ק, א. ראה לקו\"ת להאריז\"ל שם. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תעה. תו\"ח בראשית לה, ג ובהערה 47. לקמן כג, ב. פ' משפטים רצא, ג."],["870","857","<b>ור\"ת השתחוו לה' בהד\"ק </b>[ בהדרת קודש]<b> קבלה</b>: תהלים כט, ב. ראה פע\"ח (שער השבת) שי\"ח, ספכ\"א. מאמרי אדה\"א נ\"ך ע' קלט. וש\"נ לקמן כג, ב."],["871","858","<b>דקבלה באצי'. . בעשי'</b>: ראה פע\"ח (שער הנהגת הלימוד) שי\"ז. הנסמן במאמרי אדה\"א נ\"ך שם."],["872","*859","<b>פלאו' ח\"ע</b>: נסמן בהערה 862."],["873","**859","<b>גם לרבותא</b>: ראה גם בחיי וישב מו, ד. לקמן פ' וארא סה, ג. יתרו רנד, ג. מאמרי אדה\"א שמות ח\"א ע' פד. במדבר ח\"ב ע' תשעב. ח\"ה ע' א'תתנג. לעיל הערה 296."],["874","859","<b>אראנו נפלאות תרין</b>: ראה גם לקמן פ' בא צו, ג. בשלח קנב, ב. קנה, א. מאמרי אדה\"א דברים ח\"א ע' טז."],["875","860","<b>דסדכ\"ס</b>: לשון הזהר בהקדמה ב, א. ועוד."],["876","861","<b>אראנו ליש\"ס</b>: ראה השמטות לזח\"א רסא, ב. וראה גם בשלח נג, א. לקמן פ' בשלח קנד, ד. קפה, ד."]]],[2300541059,"היציאה מן המיצר וקטנות הדיבור הנק' אלם מאלקים כנ\"ל אז דוקא צריך להיות גילוי אותות ומופתים אף במ\"ח צרופי' האחרונים [כו'] כנ\"ל, והיינו מה שבחי' לי ראש דח\"ע ינהיג בעצמו בצרופי אותיות העליונים כמן שהן במו\"ד למעלה יבאו למטה לעשות היפך הטבע שזהו שרואי' בחוש לאותות העליונים בניסים ונפלאות שלמעלה מן הטבע דוקא, וזהו הי' ע\"י משה דוקא לפי שהי' כבד פה ולשון בבחי' סיפור וספר דתושבע\"פ ובכתב מטעם הנ\"ל שהי' שרשו במ\"ע שבהעלם דח\"ע הקדומה שנק' פלאות חכמה<sup data-n=\"877\">862</sup> כו' (שהוא שנק' אור צח כו' דאוכם הוא לגבי עה\"ע ע\"כ הי' משה עניו מכל כו'), ע\"כ אדרבה היא הנותנת שהי' בכחו להוציא לבנ\"י מגלות וירידה שבדבור שהי' בבחי' התלבשות המל' בלבוש שק דנוגה כנ\"ל, לפי שכל הגבוה גבוה [יותר] יותר יכול להשפיל א\"ע<sup data-n=\"878\">863</sup> (וכמו שנפלאו' ה' דפלאו' ח\"ע נתגלה למשה שהי' נשמתו במקור הח\"ע, כך הי' יכול להביא גילוי ההעלם דמדות וח\"ע אף בדבור וכ\"ש במח' שהן ב' תורות שבכתב ושבע\"פ במ\"ת בבחי' פב\"פ בספר וסיפור כו'. וכמו\"כ בחיצוני' העולמות בשינוי הצירופי' דסדרי מע\"ב כו' שהראה לפרעה וחרטומיו בי' מכות למען ידעו את שם הוי' דח\"ע ממש כמו שהוא גם למטה כמו שהן בלבוש שק דקטנות הדבור (וזהו שאמרו בקי\"ס מי כמוך באלים הוי' שהוא קו האמצעי דת\"י שמקבל מפנימי' הכתר<sup data-n=\"879\">864</sup> כידוע, שגם שנק' אלם בקטנות דשם אלקים כמו שא' אין כמוך באלמי' כמו כשפרעה הכביד לבו וא' מי ה' כו', עכ\"ז גם אז הוא עושה פלא העליון שיתגלה מן ההעלם העליון למטה כמו שהוא למעלה לפי שהוא נאדר בקדש דח\"ע וזהו בקי\"ס כידוע שע\"ז א' וירא ישראל<sup data-n=\"880\">865</sup> את היד הגדולה שנתמשך מהעלם דאין דח\"ע למטה במצרים במ\"ח הצרופי' דאלקי' כו' להפוך ים ליבשה שההעלם נעשה גילוי עד שנטבעו בי\"ס כו', וע\"ז א' אראנו לישראל זה נפלאות ה' העליוני' בגילוי העלם אחר העלם למעלה כנ\"ל). <span data-k=\"pg\">ל</span> ּ [ו]נמצא דירידה זו הב' דבנ\"י הבאים מצריימה את יעקב בגילוי אותיות הדבור כו' הי' לצורך עלי' הא' שהוא מ\"ת פב\"פ בקול ודבור דוקא כמ\"ש וידבר אלקים<sup data-n=\"881\">866</sup> כו' ושמעו קול אלקים מדבר מתוך האש<sup data-n=\"882\">867</sup> ונתקיימו בגופי' שלהם כו'<sup data-n=\"883\">868</sup>) שזהו גילוי אור דפנימי' ח\"ע דאדם העליון דאצי' באותיות הפנימי' דדיבור וע\"י משה דוקא כמ\"ש משה ידבר כו', והוא גם בתושבע\"פ בו\"ס משנה כמ\"ש תורה ציוה לנו משה מורשה במ\"ת כו'). ולכך הוצרך",[["877","862","<b>פלאות חכמה</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קנו. וש\"נ. ש\"א לב,א. שעה\"י קכז, ב הערה 26. לקמן פ' וארא פ, ב. בשלח קסז, ב. קצח, ב (ח\"ס). משפטים רצא, ב. תצוה שמא, ג. שמז, א. ויקהל תלא, א."],["878","863","<b>שכל הגבוה. . להשפיל א\"ע</b>: ראה ש\"א שער הפורים ע' נח וע' סה. מאמרי אדה\"א הנחות תקע\"ז ס\"ע קכא. וש\"נ. לקמן פ' וארא נג, ד. נו, א. פג, ב. בא צ, ג. צד, ד. צה, א. קיט, א. יתרו רסא, ב. רסג, סע\"א. תרומה שיא, א. שיז, ג. תצוה שנד, ג. פקודי תמט, ג."],["879","864","<b>קו האמצעי. . הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (ע' סג). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמה בשם הע\"ח."],["880","865","<b>וירא ישראל</b>: בשלח יד, לא."],["881","866","<b>וידבר אלקים</b>: יתרו כ, א."],["882","867","<b>ושמעו קול אלקים מתוך האש</b>: ואתחנן ד, יב. ה, ה. יט. כא."],["883","868","<b>ונתקיימו. . כו')</b>: יז: (ונתקיימו. . יח: כו'."]]],[2300541062,"להיות בחי' הכנה רבה זו בגילוי אותות ומופתים בי' מכות במצרים להפוך צרופי אותיות דלבוש שק דח\"ע<sup data-n=\"884\">869</sup> שידעו גם הם לשם הוי' כו', אע\"פ שיניקה זו שלהם מחיצוני' ואחוריי' דכלים החיצוני' דמל' דעשי' כלא חשיבא ואינו תופס מקום כלל כידוע במ\"ש ז\"ל הן הן<sup data-n=\"885\">870</sup> כו' כשממית בהיכל מלך<sup data-n=\"886\">871</sup> כו', עכ\"ז הי' צריך בשביל גילוי שכינה שבא בניסי' ונפלאו' הללו שהי' מאיר מח\"ע דמשה ע\"י מטה משה להפוך גם מנחש למטה שעי\"ז יוכלו נש\"י לקבל אור דח\"ע במ\"ת גם בגופים שלהם פב\"פ כו' וד\"ל.\n[ל] <b>ומעתה</b> יתורצו כל הקושיות דלעיל בפסוק זה ואלה שמות בנ\"י כו', הא' מה זה שבא להודיע דבר חדש בשמות בנ\"י ראובן ואיך שבאו עם יעקב שכבר הודיע דבר זה בפ' ויגש בחייהם כו'. הענין יובן ע\"פ כל הנ\"ל שהן ב' ירידות וירידה הא' בחיי השבטי' עצמן זהו<sup data-n=\"887\">872</sup> בהעלם דמח' דבינה שהשמות דשבטי' עצמן נכללו שם במדו' דח\"ע ואינו בא רק להודיע הנולדי' מהם בהתחלקו' דע' נפש כנ\"ל. אבל כאן מודיע מחדש בירידה הב' שבאו המדו' דח\"ע דישראל בדיבור בעלמא דאתגליא דוקא שבאי' במספר שמות כסדרן דוקא, וא' ע\"ז פעם ב' ואלה שמות בנ\"י הבאים ממש בגילוי עוד להיות במספר מכוון כסדרן ראובן שמעון כו' את יעקב דוקא מטעם הנ\"ל שהן<sup data-n=\"888\">873</sup> גילוי המדות בדיבור (וכמו המשכת המדות דח\"ע דתושב\"כ בו\"ס משנה כו'). וזהו שפרש\"י להודיע חבתם שנמשלו לכוכבים שא' המוציא במספר צבאם, שהוא מ\"ש ששם עלו שבטים<sup data-n=\"889\">874</sup> שבטי י\"ה שהשבטים הן המקבלי' מן האילן [כ]ענפי האילן והוא יעקב וז\"ש את יעקב כו' וכמו הכוכבי' שנמשכי' אחר השמש וירח ונק' כוכבי אור<sup data-n=\"890\">875</sup> שמוציאם במספר כמ\"ש מונה<sup data-n=\"891\">876</sup> כו'). וידוע שיוסף הוא צ\"ע שלמעלה מן בחי' הדיבור, ונכללי' השבטי' שהן בעלמא דנוק' לצ\"ע, ולכך מנה כאן י\"א שבטי' ראובן שמעון כו' ובנימין שהוא צ\"ת<sup data-n=\"892\">877</sup>, וכמו שהי' החלום דיוסף שא' ואנחנו מאלמים<sup data-n=\"893\">878</sup> כו' וקמה אלומתי<sup data-n=\"894\">879</sup> ותסובינה<sup data-n=\"895\">880</sup> אלומותיכם ותשתחוין לאלומתי וכן החלום הב'<sup data-n=\"896\">881</sup> דשמש וירח וי\"א כוכבי' כו', שזהו שאו' כאן ואלה שמות בנ\"י כו' שבאו ונכללו י\"א שבטי' ביוסף שהי' במצרים, והוא שא' בדרך כלל ויהי כל יוצאי ירך יעקב ע' נפש ויוסף הי' במצרים<sup data-n=\"897\">882</sup> שנכללו כולם בו מטעם הנ\"ל וזה הי' בירידה הא'",[["884","869","<b>דח\"ע</b>: יז: דח\"מ. טזיח: דח\"ם."],["885","870","<b>הן הן</b>: יל\"ש נחמי' רמז תתרעא. ראה יומא סט, ב."],["886","871","<b>כשממית בהיכל מלך</b>: משלי ל, כח. ראה גם סידור סדר הגדה רצד, רע\"ג. תו\"א מג\"א קיט, סע\"ד. מאמרי אדה\"א נ\"ך ס\"ע תנד ואילך. לקמן פ' בא קכו, ד."],["887","872","<b>זהו</b>: יח: שהן."],["888","873","<b>שהן</b>: יח: שזהו."],["889","874","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["890","875","<b>כוכבי אור</b>: תהלים קמח, ג. ראה פסחים ב, א. תו\"ח ויחי רמו, א הערה 4."],["891","876","<b>מונה</b>: תהלים קמז, ד."],["892","877","<b>שיוסף הוא צ\"ע. . ובנימין שהוא צ\"ת</b>: ראה זהר ויצא קנג, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתצה ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"ב ע' שצא. וש\"נ."],["893","878","<b>ואנחנו מאלמים</b>: וישב לז, ז [ושם: והנה אנחנו — ראה מאמרי אדה\"א בראשית ע' תסב וע' תסז]. ראה ד\"ה זה במאמרי אדה\"ז תקס\"ה ח\"א ע' צט. תו\"א וישב כח, א. תו\"ח שם סג, ג."],["894","879","<b>וקמה אלומתי</b>: יח: קמה אלומתי כו'."],["895","880","<b>ותסובינה</b>: וישב שם [ושם: והנה תסבינה — ראה מאמרי אדה\"א ויקרא ח\"א ע' שנה]."],["896","881","<b>החלום הב'</b>: וישב שם, ט."],["897","882","<b>ויהי כל. . במצרים</b>: שמות א, ה [בדילוג]."]]],[2300541065,"בחייהם כנ\"ל, ואח\"כ וימת יוסף וכל הדור ההוא<sup data-n=\"898\">883</sup> ובנ\"י פרו<sup data-n=\"899\">884</sup> כו' ותמלא הארץ אותם שזהו ירידה הב' בזמן משה ואהרן שקם מלך חדש כו' כנ\"ל וד\"ל. ולפי שכאן הי' הכנה בניסים די' מכות וקי\"ס למ\"ת שיהי' בד' דגלים ולכך יצאו ממצרים במספר ת\"ר אלף שנק' צבאות הוי' ממש כנ\"ל זהו שכאן מפרש שמותם כסדרן ראובן שמעון לוי, דזהו בחי' חו\"ב וחו\"ג שבמדות עליונו' דח\"ע שמאיר גם בעולם הדיבור דוקא והוא להיות הכנה למ\"ת בקבלה פב\"פ <span data-k=\"pg\">62</span> ּ כו' שזהו עלי' הא' ממקום שירד בירידה הב' כנ\"ל, והוא מ\"ש ראובן שמעון, ראי' דחכ' כמ\"ש בראובן כי ראה ה'<sup data-n=\"900\">885</sup> כו' ושמיעה בבינה שא' בשמעון כי שמע ה'<sup data-n=\"901\">886</sup> כו' והוא ג\"כ חו\"ג דראי' דחכ' באהבה ושמיעה דבינה ביראה כידוע, ולוי בחי' ת\"ת הממוצע שמחבר לחו\"ג והוא קו האמצעי כמ\"ש ילוה אישי<sup data-n=\"902\">887</sup> כו' ביחוד דתו\"מ ע\"י משה ואהרן וכהנים ולוים כידוע, ויהודה הוא בבחי' המל' כמ\"ש הפעם אודה את הוי'<sup data-n=\"903\">888</sup> כמו בש\"ע, וכמ\"ש במ\"א שב\"פ דק\"ש<sup data-n=\"904\">889</sup> הן בחי' ראובן ושמעון ואמת ויציב בהתקשרות תמידי' בחי' לוי וג' אלה נכללי' במל' בש\"ע ויששכר וזבולן בחי' נו\"ה<sup data-n=\"905\">890</sup> כו'. וכ\"ז בפנימי' דמדות וחכ' דישראל דלעילא שבאו מצרימה בגלות בהעלם במיצר הגרון ויצאו משם להיות בבחי' הגדלות דמוחי' ומדות בעולם הדיבור שיאיר רק ע\"פ גדלות דח\"ע דישראל לי ראש, וכמו שהוא בבחי' פנימי' כמו במ\"ת שקיבלו בנ\"י פנימי' דח\"ע בדיבור בי' הדברות כנ\"ל כמו שהן במעמד וסדר דיב\"ש נגד י\"ב צרופי הוי'<sup data-n=\"906\">891</sup> כנ\"ל ונכללו כאיש א' ממש כמ\"ש ויחן ישראל כו', כך הוא גם בחיצוניות השפע לעולמות בי\"מ שנמשך ג\"כ אפי' בצרופי' האחרונים דשם אלקי' שמלובש בדרכי הטבע בכו\"מ וד\"י ארמ\"ע בגידול והנהגה דדצח\"מ גשמיי' גם שם מאיר מבחי' אור דחכ' ומדות כמו בפנימי' הדבור העליון שמקבלים מחכ' ובינה ומדות דאצי' ממש כנ\"ל, וזהו ענין מה שאנו רואים בחוש שנמשך בחי' השגחה פרטי' בבחי' ראי' ושמיעה העליונה דשם הוי' דחו\"ב ש\"מ בכל דרכי בנ\"א למטה, כמו משמים הביט הוי' ממש ראה את כל בנ\"א<sup data-n=\"907\">892</sup>, ממכון שבתו השגיח על<sup data-n=\"908\">893</sup> כו' בהשגחה פרטי' עד שמבין אל כל מעשיהם<sup data-n=\"909\">894</sup> בפרט כמ\"ש עיניך פקוחות<sup data-n=\"910\">895</sup> על כל דרכי בנ\"א, עיניך ממש ואף על איש א' בפרט כמו דע מה שלמעלה ממך<sup data-n=\"911\">896</sup> עין רואה ואזן שומעת כו'. וזהו ע\"ד שבגלוי, וגם ע\"ד שבנסתר והעלם בתוך נקוד' הלב הרי בוחן כליות ולב<sup data-n=\"912\">897</sup>, ולפניו ית' נגלו",[["898","883","<b>וימת יוסף. . ההוא</b>: שמות שם, ו."],["899","884","<b>ובנ\"י פרו</b>: שם שם, ז."],["900","885","<b>כי ראה ה'</b>: ויצא כט, לב."],["901","886","<b>כי שמע ה'</b>: ויצא שם, לג."],["902","887","<b>ילוה אישי</b>: שם שם, לד."],["903","888","<b>הפעם אודה את הוי'</b>: ויצא שם, לה."],["904","889","<b>שב\"פ דק\"ש</b>: ראה תו\"א ויחי מה, ב ואילך [ובהנסמן במ\"מ בריש המאמר שם]."],["905","890","<b>וישכר וזבולון בחי' נו\"ה</b>: ראה זהר בשלח מח, ב. (סבא) משפטים קד, ב."],["906","891","<b>דיב\"ש נגד י\"ב צרופי הוי'</b>: ראה רקאנטי תצוה כח, ב. תו\"ח ח\"ש קכט, ג הערה 24. לקמן פ' משפטים רפז, א. תצוה שנב, א. לעיל כ, ג."],["907","892","<b>משמים הביט. . בנ\"א </b>[יז: בנה\"א]: תהלים לג, יג."],["908","893","<b>ממכון שבתו השגיח על</b>: תהלים שם, יד [ושם: אל — ראה לקמן פ' בשלח קלד, ד. מאמרי אדה\"א הנחות תקע\"ז ע' שלה. וש\"נ]."],["909","894","<b>שמבין אל כל מעשיהם</b>: שם שם, טו."],["910","895","<b>עיניך פקוחות</b>: ירמי' לב, יט."],["911","896","<b>דע מה שלמעלה ממך</b>: ראה אבות פ\"ב, מ\"א."],["912","897","<b>בוחן כליות ולב</b>: ירמי' יא, כ."]]],[2300541067,"כל תעלומות<sup data-n=\"913\">898</sup> כו', וכמו וירא ה' כי רבה<sup data-n=\"914\">899</sup> כו', וכן וישמע ה'<sup data-n=\"915\">900</sup>, וכן הכצעקתה הבאה אלי<sup data-n=\"916\">901</sup> ממש וכה\"ג א' מחטו לי כמחט בבשר החי<sup data-n=\"917\">902</sup> כו', שמובן מכ\"ז ענין גילוי אור אלקי בעולמות אף ביותר תחתון כחלקי דצח\"מ וארמ\"ע שמשגיח עליהם בפרטי פרטיות בראי' והשגחה דשם הוי' ממש ואין הסתר והעלם לפניו כלל, וכמו שאו'<sup data-n=\"918\">903</sup> שבחכ' פותח שערים ובתבונה משנה עתים כו' ומסדר הכו\"מ כו' כרצונו דוקא כגרזן ביד החוצב כו', שלא כדעת האפקורסי' הכופרי' בהשגחה האלקי' הפרטי' ואו' עזב ה' את הארץ<sup data-n=\"919\">904</sup> כו' ויאמרו לא יראה<sup data-n=\"920\">905</sup> [יה] ולא יבין אלקי יעקב כו' כי רם על כל<sup data-n=\"921\">906</sup> כו' שמרומם ונשגב בבחי' מקיף עליהם, ובאמת גם בדבר אלקי' שבא בצרופי אותיות הטבע ממש שם דוקא מאיר מבחי' מקור הראשון דחו\"ב ומדות דא\"ס שבאצי' וקשורין כולן במקורם הראשון בלי שינוי כלל וכלל כנ\"ל. וזהו ראובן שמעון לוי חד\"ר<sup data-n=\"922\">907</sup> לאנהגא בהון עלמין<sup data-n=\"923\">908</sup> כו' ע\"פ משפט התורה דוקא, כמ\"ש השופט כל הארץ<sup data-n=\"924\">909</sup> כו' מלך במשפט<sup data-n=\"925\">910</sup> דאוריי' כו' וכמ\"ש יושב ודן יושב וזן<sup data-n=\"926\">911</sup> כו' וכמו כי לא שלם עון האמורי<sup data-n=\"927\">912</sup> עד הנה כו', שמשפט הזה הוא בחי' ישראל ויעקב והשבטים שהוא תושב\"כ ושבע\"פ כנ\"ל וד\"ל.\n[לא] <b>והנה</b> מעתה יש להבין ענין ב' העליות שאחר ב' ירידות הנ\"ל והוא כמ\"ש אנכי ארד עמך כו' ואנכי אעלך גם עלה כנ\"ל, דהנה מבואר למעלה בענין ב' ירידות דח\"ע שבראש שנק' בחי' ישראל העליון לי ראש כו' שזהו הא' במדו' דח\"ע היורדי' ונמשכי' במח' דבינה בה\"א <span data-k=\"pg\">לא</span> ּ עילאה בעלמא דאתכסי' (כמו אוי\"ר שכליי' שכלולי' במח' דבינה בפנימי' וחיצוני' שהן יש\"ס ותבונה כו') והב' ביריד' של המדות דיעקב וישראל בדיבור שז\"ש כאן ואלה שמות כו' כנ\"ל, ולנגד זה הן ב' עליות העלי' הא' מירידה השני' דבחי' הדיבור שיאיר בו גדלות הח\"ע ומדו' דתורה אור כמו במ\"ת וגם בחיצוני' כאותות ומופתי' שעשאן משה בבחי' הדיבור כמ\"ש ואתה תהי' לו לאלקי'<sup data-n=\"928\">913</sup> וכתי' ראה נתתיך אלקים לפרעה<sup data-n=\"929\">914</sup> כו' וא\"כ הרי הי' ירידה זו בשביל העלי' כמ\"ש ואנכי אעלך שהוא עלי' הא' דמ\"ת פב\"פ בקול ודבור כנ\"ל. ומ\"ש גם עלה זהו עלי' הב' בכלל נגד ירידה הא' שא' בפ' ויגש ואלה שמות בנ\"י כו' שהוא ירידה דאור דח\"ע בבינה ומח' שנק' מיצר מ\"י דבינה (שהוא פלג אלקי'<sup data-n=\"930\">915</sup> מי אלה כו' כמ\"ש במ\"א), ועלי' הזאת שמדו' דח\"ע שבראש עולי' גם ממיצר וצמצום דמח' דבינה, שזהו ענין העלא' המדות למעלה",[["913","898","<b>ולפניו. . תעלומות</b>: ע\"פ ברכת זכרונות (מוסף לר\"ה)."],["914","899","<b>וירא ה' כי רבה</b>: בראשית ו, ה."],["915","900","<b>וישמע ה'</b>: בהעלותך יא, א."],["916","901","<b>הכצעקתה הבאה אלי</b>: וירא יח, כא."],["917","902","<b>מחטו לי כמחט בבשר החי</b>: וירא כ, ו. ראה זהר ויקרא ח, א."],["918","903","<b>וכמו שאו'</b>: ע\"פ תפלת ערבית."],["919","904","<b>עזב ה' את הארץ</b>: יחזקאל ח, יב. ט, ט."],["920","905","<b>ויאמרו לא יראה</b>: תהלים צד, ז."],["921","906","<b>רם על כל</b>: תהלים קיג, ד. ראה גם לקמן פ' וארא סד, א."],["922","907","<b>חד\"ר</b>: יח: חסד דין רחמי'."],["923","908","<b>לאנהגא בהון עלמין</b>: ת\"ז בהקדמה יז, א."],["924","909","<b>השופט כל הארץ</b>: וירא יח, כה."],["925","910","<b>מלך במשפט</b>: משלי כט, ד. ראה גם לקמן פ' בשלח קלד, ד. קעג, א."],["926","911","<b>יושב ודן יושב וזן</b>: ראה ע\"ז ג, ב."],["927","912","<b>כי לא שלם עון האמורי</b>: לך טו, טז."],["928","913","<b>ואתה תהי' לו לאלקי'</b>: שמות ד, טז."],["929","914","<b>ראה נתתיך אלקים לפרעה</b>: וארא ז, א."],["930","915","<b>פלג אלקי'</b>: תהלים סה, י. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקפט ואילך. לקו\"ת במדבר ו, ד."]]],[2300541069,"מכלי הגבלתם שכלולי' בהשגת שכל ומח' עיונית דבינה בחי' ה\"א עילאה בבחי' עיבור (כרגל הקצר שבה\"א עילאה שנק' אימא עילאה (והוא תושבע\"פ שבבינה שנק' תורת אמך שמקבל מאור אבא פנימי' ח\"ע שבתושב\"כ כו'), זהו ענין הגאולה השני' שיהי' ע\"י משיח שיהי' העברה בנהר פרת כמ\"ש הפך ים ליבשה<sup data-n=\"931\">916</sup> בנהר יעברו ברגל להבא כו' כידוע שזהו ההעברה בנהר דבינה ה\"א עילאה שהוא במח' שמצמצם ומעלי' לאור החכ' שנק' אין ונעשה בבחי' יש בהשגה מורגשת (והן אוי\"ר שמכוסי' ונעלמי' בהשגה ומח' עיונית כידוע). והעליה גם ממיצר מ\"י דבינה נק' בחי' לידה וגאולה שהוא להעלו' למדרג' דאור החכ' עצמה כמו שה[ו]א בבחי' אין ממש ולהתפשט מבחי' יש דהשגה כענין מה פשפשת כו' משום דלית מח' והשגה תפיסא בי' כלל, לפי שהשגה ומח' הוא בחי' לבוש והעלם להעלים לאור אמיתי' דא\"ס ב\"ה שהוא למעלה מכל השגה ותפיסא במוח בינה כו', והוא שנק' ביטול היש דהשג' לאין שהוא בחי' ראי' דחכ' בעין השכל כראי' חושיי' ממש שרואה במהו' ועצמו' הדבר כמו שהוא ממש, ולזה אינו דומה שמיעה לראי'<sup data-n=\"932\">917</sup> כלל דאע\"פ ששומע ומבין ומשיג לאמיתי' הדבר מ\"מ זהו בשמיעה מרחוק שמשיג רק המציאו' ולא במהות ועצם כלל משא\"כ בראי' עין מקרוב כו' כידוע. וכך הוא ההפרש בין בחי' שמיעה מרחוק ה' נראה ל[ו] בהשגה והבנה במח' עיוני' כמו בהתבוננו' בק\"ש שא' שמע ישראל בשמיעה והשגה דוקא שה' אלקינו הוי' אחד פשוט כו', ולע\"ל בימות המשיח הרי עין בעין יראו<sup data-n=\"933\">918</sup> בבחי' רא[י'] דחכ' שנק' אין ממש שהוא רואה בעין השכל כראי' חושי' מקרוב במהו\"ע א\"ס ב\"ה כמ\"ש וראו כ\"ב<sup data-n=\"934\">919</sup> כי פי הוי' כו' וכן א' אז כולם ידעו אותי<sup data-n=\"935\">920</sup> ממש וכה\"ג (ומעין זה הי' גם במ\"ת שראו את הנשמע<sup data-n=\"936\">921</sup> כו').\n<b>וזהו</b> שא' גם עלה לרבות עלי' גדולה מביאת א\"י דגם שביאתם לא\"י הי' עלי' יותר ממ\"ת שהוצרכו לירידה ב' בשביל עלי' זאת והוא מה שהלכו במדבר העמי'<sup data-n=\"937\">922</sup> נחש שרף ועקרב<sup data-n=\"938\">923</sup> והיו מנוסי' בנסיונו' ברעב ובצמא כמ\"ש ויענך וירעיבך כו', עכ\"ז לא הי' עלי' שלימה בא\"י אחר שחטאו בימי השופטי', וגם בימי דוד ושלמה בבנין בהמ\"ק בגילוי אורו' עליונים בכלים דמל' בשלימות בקיום המצות וקרבנות כו' עכ\"ז לא הוטהרה הארץ אע\"פ שנק' ארץ חפץ<sup data-n=\"939\">924</sup> וארץ אשר ה' דורש אותה<sup data-n=\"940\">925</sup> כו' כי גבר שם יניקת הק\"נ בתערובו' רע עד שנחרב הב\"ר וב\"ש ויצאו ישראל בגלות בח\"ל בארץ העמים ושכינה עמהם כידוע. אך",[["931","916","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["932","917","<b>אינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לק\"ט שלח יג, יח. מאמרי אדה\"א דברים ח\"א ע' קמו ואילך. הנסמן בשה\"א ט, ב הערה 14. לקמן פ' וארא פה, ב. משפטים רפט, ג. מאמר ד\"ה משה קבל תר\"ם קה\"ת תשנ\"ח ע' 4. וש\"נ."],["933","918","<b>עין בעין יראו</b>: ישעי' נב, ח."],["934","919","<b>וראו כ\"ב</b>: ישעי' מ, ה [בדילוג]."],["935","920","<b>כולם ידעו אותי</b>: ירמי' לא, לג."],["936","921","<b>שראו את הנשמע</b>: נסמן לקמן פ' בשלח קפ, ב."],["937","922","<b>במדבר העמי'</b>: ע\"ד לשון הכתוב יחזקאל כ, לה."],["938","923","<b>נחש שרף ועקרב</b>: עקב ח, טו."],["939","924","<b>ארץ חפץ</b>: ראה מלאכי ג, יב. תו\"ח לך פד, ב ובהערה 18."],["940","925","<b>וארץ אשר ה' דורש אותה</b>: עקב יא, יב [ושם: ה\"א]."]]],[2300541070,"עיקר שלימות העלי' בבחי' קיום נצחי בלי ביטול <span data-k=\"pg\">64</span> ּ והפסק לעולם זהו בגאולה האחרונה דמשיח בקיבוץ גליות בא\"י ובנין בהמ\"ק נצחי [ו]כמ\"ש ולירושלי' כו' בשמחת עולם ושם נעשה כמצות רצונך<sup data-n=\"941\">926</sup> כו', שם דוקא שזהו לאחר שלימות הבירורי' דעה\"ד טו\"ר בתכלית, וגם הארץ תטהר מכל סיג ופסולת כמו גן ה' בגעה\"ת וכה\"ג עד שתמלא הארץ דיעה את ה' (כמו בג\"ע באדה\"ר וקין<sup data-n=\"942\">927</sup> והבל שדיבר ה' עמהם פב\"פ<sup data-n=\"943\">928</sup> כו'), והיינו מה שיזכו בנ\"י לקבלת התורה הפנימי' שהוא סוד ה' בטעמי תו\"מ (כי אילנא דטו\"ר כמו או\"ה כו\"פ טו\"ט יתעבר<sup data-n=\"944\">929</sup> שלא יהי' שום רע ופסול וטמא בעולם כמ\"ש ואת רוה\"ט אעביר מן הארץ<sup data-n=\"945\">930</sup> לגמרי). ולזאת ודאי גם עבודתם בתפלה וק\"ש באוי\"ר והשגו' אלקו' לא יהי' לברר ולתקן לעה\"ד טו\"ר בביעור הרע מן הטוב אלא הכל בבחי' אוי\"ר שכלי' כנשמו' בגעה\"ת עכשיו שנהנין מזיו כו', שזהו בחי' המדו' שבמח' פנימי' דבינה דמל' דאצי' בה\"א עילאה דוקא שלמעלה ממדות שבלב בקול ודבור חיצוני (ונק' קלא פנימאה דיעקב במח' ובינה שהוא בחי' ישראל ולאה או יש\"ס ותבונה כו') (וכמו אדה\"ר בג\"ע שא' לעבדה ולשמרה, לא לתקן לרע בעה\"ד טו\"ר אלא לעבדה ברמ\"ח מ\"ע ברוחניו' כו', ואמנם בימות המשיח שיהי' במדרג' דגעה\"ת הנ\"ל עכ\"ז יהיו המצות בגשמיו' דוקא וכמו שאו' ושם נעשה לפניך כמצות רצונך ממש וכן א' הלכתא למשיחא<sup data-n=\"946\">931</sup> כו', לפי שיומשך גילוי אלקו' הרוחני' דאצי' בגשמיו' בקרבנות בהמו' גשמיו' רק שיהיו טהורי' ונקיי' מכל רע כבהמו' שקודם חטא עה\"ד (כשור שהקריב אדה\"ר<sup data-n=\"947\">932</sup> כו') וכמ\"ש לא ירעו ולא ישחיתו<sup data-n=\"948\">933</sup> כו' ויהי' רוח אלקי' באדם ממש וכמ\"ש ואשפוך את רוחי<sup data-n=\"949\">934</sup> כו' ונבאו בניכם כו' כמו שהי' בדורו של אדה\"ר שנקראו בני האלקי'<sup data-n=\"950\">935</sup> ממש כו'). וא\"כ גם ענין קבלת התורה יהי' אז בבחי' הפנימי' כמו שלומדי' עכשיו בגעה\"ת דיני ההלכות דו\"ס משנה בטעמיהן ע\"פ הסוד דוקא (כמו במשנה דאם בהרת קדמה לשער לבן קודב\"ה או' טהור כו' וכה\"ג), ואמנם יהי' גילוי סוד ה' ליריאיו בטעמי מצות בהשגה דוקא שהוא בחי' בינה שמבין ומשיג בטוב טעם ודעת האלקי' כמו כולם ידעו אותי ומלאה הארץ דיעה<sup data-n=\"951\">936</sup> כו' כנשמו' בג\"ע שמשיגי' בהשגה בסודות התורה שלומד עמהם רב מתיבתא (כמבואר בזהר פ' שלח<sup data-n=\"952\">937</sup> ). ונמצא דכמו שהי' עלי' הא' דנש\"י במ\"ת בגילוי הדבור ובאי'<sup data-n=\"953\">938</sup> במעשה המצות לברר ולתקן לעה\"ד דבחכ' אתברירו ז' מדות דתהו שהן ז' אומות<sup data-n=\"954\">939</sup> דא\"י",[["941","926","<b>ולירושלים. . ושם. . רצונך</b>: תפלת מוסף לשלש רגלים [בדילוגים]. ראה [ד\"ה אוסרי לגפן תקס\"ד נדפס ב]תו\"ח ויחי רלו, א. רלח, ד ואילך. מאמרי אדה\"א שמות ח\"א ע' רכו. וש\"נ. במדבר ח\"ה ע' א'תרכד. לקמן פ' בשלח קנו, ב. ויקהל תכב, ג."],["942","927","<b>באדה\"ר וקין</b>: בראשית ג, ט. ד, י."],["943","928","<b>והבל שדיבר ה' עמהם פב\"פ</b>: כ\"ה גם בהכת\"י."],["944","929","<b>אילנא דטו\"ר. . יתעבר</b>: ראה זהר (רע\"מ) נשא קכד, ב. קכה, א. הובא באגה\"ק סכ\"ו. מאמרי אדה\"א ויקרא ח\"ב ע' תרפה. וש\"נ. קונטרסים ע' תטו. וש\"נ. שע\"ת סו, א. צז, ב. תו\"ח נח סא, ג. לקמן פ' בשלח קנו, ב. ויקהל תכב, ג."],["945","930","<b>ואת רוה\"ט אעביר מן הארץ</b>: זכרי' יג, ב."],["946","931","<b>הלכתא למשיחא</b>: ראה סנהדרין נא, ב. אגה\"ק סכ\"ו (קמג, ב). מאמרי אדה\"א ויקרא ח\"א ע' קיד־ ח\"ב ע' תרפו (ובהנסמן בהנ\"ל). במדבר ח\"ב ע' תשעה. ח\"ה ע' א'תרכד. דרושי חתונה ח\"א ס\"ע צז וע' קלא. לקמן פ' בשלח קנו, ב. ויקהל תכב, ג."],["947","932","<b>כשור שהקריב אדה\"ר</b>: שבת כח, ב. ראה תו\"ח תולדות קס, ג ובהערה 22. לקמן פ' ויקהל תכב, ג."],["948","933","<b>לא ירעו ולא ישחיתו</b>: ישעי' יא, ט. סה, כה."],["949","934","<b>ואשפוך את רוחי</b>: יואל ג, א [ושם: והי' אחרי כן אשפוך — ראה לקמן פ' בשלח קנד, א. רכד, ב. רלב, ג. מאמרי אדה\"א ויקרא ח\"א ע' רסט. וש\"נ. תו\"ח וישב רח, ב בהערה 20]."],["950","935","<b>בני האלקי'</b>: בראשית ו, ב."],["951","936","<b>ומלאה הארץ דיעה</b>: ישעי' יא, ט [ושם: כי מלאה — ראה הנסמן לקמן פ' בשלח קס, ד]."],["952","937","<b>רב מתיבתא. . שלח</b>: ראה גם לקמן פ' בא צב, ג. וש\"נ."],["953","938","<b>ובאי'</b>: אוצ\"ל: ובא\"י ובארץ ישראל."],["954","939","<b>ז' מדות </b>[יג: ז\"מ ז' מלכין]<b>. . ז' אומות</b>: ראה גם ביאוה\"ז תשא נג, ג. שע\"ת קג, ד. מאמרי אדה\"א הנחות תקע\"ז ע' קמה. וש\"נ."]]],[2300541071,"כידוע שאין זה רק בחי' ה\"א תתאה דמל' (והוא ענין קי\"ס במל' סופא דכ\"ד כידוע), כך יהי' עלי' הב' בימוהמ\"ש בה\"א עילאה דבינה שהמדות הן באוי\"ר שכליי' לבד בהשג' אלקו' ברוחניות ממש בלי שום מסך מבדיל מצד הגוף כלל ותו\"מ יהי' הכל בבחי' הטוב דקדושה האלקי' בלי נצרך לברר ולתקן לרע כלל (ועכ\"ז יהי' שס\"ה ל\"ת כמו שהי' באדה\"ר בג\"ע שא' לשמרה כו') שהרי הגופי' יהיו בהגשמה והארץ תעבד בגשמיו' ויאכלו מתבואת הארץ (ולא כמזון המן הרוחני כו') והנער בן ק' שנה ימות<sup data-n=\"955\">940</sup> (כדורו' דאדה\"ר כנ\"ל שא' לא ידון רוחי<sup data-n=\"956\">941</sup> באדם בשגם כו') שיהי' מיתה עכ\"פ שהוא מסתעף מעה\"ד טו\"ר כו' ואין זה עלי' שלימה (ועכ\"ז א\"א לבוא גם לעלי' מדרגה זו בלא מירוק גדול כיסורי' דגלות האחרון הזה בכור העוני והלחץ כו' שהוא במקום גיהנם וגם נה\"ד שלפני געה\"ת כנ\"ל במ\"ש הוציאוה ותשרף כו') כמו שהי' הבירור בכור הברזל במצרים מנש\"ט ממש כ[ד]י שיזכו למ\"ת בנגלה כנ\"ל.\n<b>אך</b> הנה א' ואנכי אעלך גם עלה גם זה ריבוי הוא <span data-k=\"pg\">לב</span> ּ לרבות עלי' הג' שלמעלה גם מימות המשיח שיהי' קיבוץ גליות בא\"י (שרחוקה מג\"ע הארץ ל\"ב מעלות<sup data-n=\"957\">942</sup> כו') במעלה ומדרגה דרוחניו' האלקי' כנ\"ל, להיות שכ\"ז [ה]עילוי בנשמות וגופי' לא יהי' רק בהפשטה מן הגשמיות דרע ופסולת וטומאה וכמ\"ש ואת רוה\"ט אעביר כו', וגם שיהי' בביטול תמידי לאלקו' בדו\"ר שכליי' כמו שאו' וידע כ\"פ<sup data-n=\"958\">943</sup> כו' וכן יהי' פחד ה' על כל הברואי' וייראוך כל המעשים כו', אין זה רק בחי' רוחניו' האלקי' שמלובש בגשמיו' כמו חיות אלקות באופני' וחיות והגלגלי' שמשיגי' את בוראם המהוה אותם תמיד ואו' שירה בתמידי' וכמו\"כ בנשמו' דעשי' בגעה\"ת בפנימי' כו'. אבל בעוה\"ב שאחר ימוהמ\"ש יהי' מעלה יתירה נבדלת בערך הרבה ממדרג' זו והוא כערך הבדלת המעלה דגעה\"ע על געה\"ת שצריך לבא תחלה במירוק ובירור שני בנה\"ד העליון שלפני געה\"ע כו'. וענין געה\"ע ידוע שזהו כמו [מה] שנשמו' דבריאה עולי' במל' דאצי' לאשתאבא בגופא דמלכא כו' והיינו ענין העלאה וביטול היש דהשגה דבינה לאין דחכ' שלמעלה מן ההשגה כמו בבחי' ראי' מקרוב ממש כנ\"ל, והוא ענין גילוי סוד ה' שבח\"ע שנפלא מן ההשגה דבינה ונק' פלאות חכ', דגם בחכ' הוא בבחי' ההעלם דחכ' (כדוגמא דניסי' ונפלאו' למטה שלמעלה מן הטבע כך הוא",[["955","940","<b>והנער בן ק' שנה ימות</b>: ישעי' סה, כ."],["956","941","<b>לא ידון רוחי</b>: בראשית ו, ג [בדילוג]."],["957","942","<b>בא\"י. . ל\"ב מעלות</b>: ראה רמב\"ם הל' קידוש החודש ספי\"א. מאמרי אדה\"א ויקרא ח\"ב ריש ע' תשג וע' תשי. קונטרסים ע' שצט. ס' השיחות תשמ\"ט ח\"א ע' 357 בהערה."],["958","943","<b>וידע כ\"פ </b>[ כל פעול]: תפלת העמידה לר\"ה."]]],[2300541072,"נפלאות דפלא העליון דחכ' שנק' ח\"ס כו' וע\"כ באי' לבחי' ביטול במציאו' ממש לאשתאבא כו' כמ\"ש השתחוו לה' כו' שביטול זה הוא ביטול דמ\"ה דח\"ע (שלמעלה גם מביטול ההשגה דמה פשפשת כו' כמ\"ש במ\"א). וזהו דוגמא לעוה\"ב שהוא בגעה\"ע כנ\"ל, והיינו מ\"ש עד יעבור עמך ה'<sup data-n=\"959\">944</sup> שעתיד להיות העברה שני' בנהר פרת שהוא ההפסק בין א\"י לגעה\"ת כמ\"ש בנהר יעברו ברגל שז\"ש לעולם ירשו ארץ ארץ החיים נצחיי' דעוה\"ב (באלף הז') שהוא געה\"ע שהוא רוחני יותר ונצחי יותר וזהו גם עלה וד\"ל (ובאמת לכאו' נמצא בכתובי' ב' העברו'<sup data-n=\"960\">*945</sup> א' בנהר יעברו ברגל שהוא מ\"ש בישעי' בקיבוץ גליות מאשור כו' והניף ידו על הנהר והכהו לז' נחלים<sup data-n=\"961\">945</sup> שהוא בלשון ים מצרים ומנחל מצרים זה עד נהר הגדול נהר פרת<sup data-n=\"962\">*946</sup> יש מרחק רב והוא העברה הב' בנה\"פ, וזהו עד יעבור הב' והוא בהעברה מא\"י לגעה\"ת כנ\"ל, והוא למעלה מש' הוי' דתו\"מ שהוא עוה\"ב שלמעלה מתו\"מ שאין תו\"מ מועיל שם כו' ואפי' ברוחניו' לכך א' עד יעבור סתם, כי עוה\"ב זה אין בו או\"ש כלל רק הגופי' קדושי' וטהורי'<sup data-n=\"963\">946</sup> יחיו חיי עולם מחיי החיים<sup data-n=\"964\">947</sup> האלקי' דא\"ס (ולא כרוח האלקי' שהי' באדם בדור א\"ה<sup data-n=\"965\">948</sup> כנ\"ל).\n<b>ומ\"ש</b> עוד עם זו קנית בקנין עצמי' ממש זהו עוד עלי' שלמעלה גם מעוה\"ב זה והוא בתחה\"מ שבסוף אלף הז'<sup data-n=\"966\">949</sup> כו' (כמ\"ש במ\"א בענין שא' וחד חרוב שאלף הז'<sup data-n=\"967\">950</sup> דעוה\"ב נק' חרוב), והוא מה שיעברו בנהר שיוצא מעדן להשקות הגן שהן ג\"ן סדרי' דאוריי' כו' לבחי' העדן עצמו שנא' בו עין לא ראתה כו' שגם בחי' עין השכל דח\"ע בראי' מקרוב (וכדוגמא זו בגעה\"ע כנ\"ל) לא ראתה רק יעשה למחכה לו כו', והוא בחי' העונג הנעלם בעצמו' א\"ס ב\"ה שלמעלה מבחי' העונג המורגש בח\"ע אע\"פ שהוא בבחי' אין והעלם בסוד ה' שנק' פלאו' דחכ' כנ\"ל שעכ\"ז בא העונג העליון במורגש לנשמו' בעוה\"ב עד שיחי' ממנו כחיו' המורגש בגופי' ונק' חיי העוה\"ב כחיי הנשמו' בג\"ע העליון עכשיו שנהנין ומרגישי' לעונג העליון (דכתר מל' דאצי' בפנימי' דחכ' זו (כמו הכלל הידוע בע\"ח דפנימי' אבא הוא בחי' פנימי' ע\"י<sup data-n=\"968\">951</sup> ופנימי' אבא שבא בהשגה דבינה זהו ימוהמ\"ש שישכיל עבדי כו' <span data-k=\"pg\">66</span> ּ ונק' פלא יועץ וחכם חרשים<sup data-n=\"969\">952</sup> כו' ופנימי' ע\"י זהו בעוה\"ב דכתי' וע\"י יתיב<sup data-n=\"970\">953</sup> כו'), אבל בעדן עצמו שלמעלה גם מנהר זה שיוצא מעדן ה\"ז למעלה מעונג העצמו'",[["959","944","<b>עד יעבור עמך ה'</b>: בשלח טו, טז. ראה מאמרי אדה\"א דברים ח\"א ע' טו ואילך. וש\"נ. שמות ח\"א ע' סא. וש\"נ. לקמן מ, ד. וש\"נ."],["960","*945","<b>ב' העברות</b>: ראה לקמן פ' בשלח קפו, א. וש\"נ."],["961","945","<b>מאשור. . והניף. . לז' נחלים</b>: ישעי' יא, יא. טו [בדילוג]."],["962","*946","<b>ומנחל מצרים. . פרת</b>: נסמן לקמן פ' בשלח קפו, א."],["963","946","<b>או\"ש. . קדושי' וטהורי'</b>: יח: אכילה ושתי'. . טהורים וקדושים."],["964","947","<b>מחיי החיים</b>: ראה יומא עא, א."],["965","948","<b>א\"ה</b>: יזיח: אדה\"ר."],["966","949","<b>בתחה\"מ שבסוף אלף הז'</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תסט וע' תעב."],["967","950","<b>וחד חרוב שאלף הז'</b>: ר\"ה לא, א. סנהדרין צז, סע\"א. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' שצט וע' תיד. תו\"א מג\"א צו, א. מאמרי אדה\"א נ\"ך ע' תסט ואילך. לקו\"ת במדבר ד, ג."],["968","951","<b>דפנימי' אבא. . ע\"י</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. לקו\"ת נצבים מט, ד. מאמרי אדה\"א בראשית ע' כה. וש\"נ. שעה\"י קכח, א הערה 15. לקמן פ' בא קכ, ב. קכז, א. תצוה שנד, ד [ושם: כמ\"ש בע\"ח בכמה דוכתי]."],["969","952","<b>פלא יועץ וחכם חרשים</b>: ישעי' ט, ה. ג, ג. ראה גם מאמרי אדה\"א בראשית ע' תו. וש\"נ. במדבר ח\"ב ע' תקסז וע' תרלא. תו\"ח מקץ רכו, ג."],["970","953","<b>וע\"י יתיב</b>: דניאל ז, ט."]]],[2300541073,"הבא במורגש לנשמו' בעוה\"ב ע\"י בחי' בינה עילאה דע\"י שהוא נהר זה שיוצא מעדן הנעלם להשקות ג\"ן סדרי' דאוריי' כמו בטעמי' ונגינות מקיף דח\"ע<sup data-n=\"971\">954</sup> כו' אלא הוא בחי' עונג הנעלם בעצמו' א\"ס ממש (שנק' בחי' שעשועי המלך בעצמותו ממש כידוע), והוא שיעשה למחכה לו למאן דדייק מילי' דח\"ת דתושבע\"פ דוקא שנק' עמל תורה כנ\"ל שלמעלה משכר התו\"מ בעוה\"ב, וכן עמל תפלה ותשובה כמו בעמל מלאכה כנ\"ל, שז\"ש דת\"ח אין להם מנוחה אפי' בעוה\"ב שילכו מחיל כו' וכן קדושי' יהללוך סלה גם בעלותם בחכ' ומדו' דא\"ס ילכו למעלה מעלה עד אין שיעור כנ\"ל, וזהו עם זו קנית בקנין עולם הנצחי כמ\"ש אלה לחיי עולם (וקאי בתחה\"מ כמ\"ש ורבי' מישיני עפר יקיצו אלה כו' וכאבות ומשה ואהרן וכל דורו' יהושע<sup data-n=\"972\">955</sup> השופטי' ונביאי' עד דורו של משיח ועוה\"ב כו' שאין להם מספר כלל (כי קיבוץ גליות יש להם מספר עכ\"פ, ועוה\"ב גם הוא יהי' לגופי' שיהי' בימות המשיח רק שלא יאכלו אכילה גשמי' כי הארץ תשבות לגמרי בשביעי' אלא לחם פנג<sup data-n=\"973\">956</sup> וכמו המן וכה\"ג כמו שא' עתידה א\"י שתוציא גלוסקאות<sup data-n=\"974\">957</sup> (ואפשר זהו בא\"י ולא בעוה\"ב) וכה\"ג א' עתידה אשה שתלד בכל יום<sup data-n=\"975\">958</sup> כו', והכל ענין א' הוא דארץ ואשה לא יצטרכו למשפיע אלא מכח עצמם יולידו בלא זריעה כלל, וכעין זה באו\"ח<sup data-n=\"976\">959</sup> קודם החטא שעלו למטה ב' וירדו ד'<sup data-n=\"977\">960</sup> כו'). וזהו למעלה מענין אין ויש, דעוה\"ב יהי' מיש האמיתי ליש גמור<sup data-n=\"978\">*961</sup> כחיי עולם דא\"ס שיחיו הגופים בלי אמצעי כלל, וע\"כ כמו שהן בגופי' לא יהי' בבחי' פירוד וכמשה ומשיח וחנוך שידעו ה' פא\"פ כאשר ידבר<sup data-n=\"979\">961</sup> כו' כמ\"ש במ\"א (ולכך לא יהי' ע\"י זריעה מאין ליש וביטול היש לאין). (וזהו הלכה ר\"ת הריעו לה' כו' שהוא למעלה מקבלה באצי' ר\"ת השתחוו כו' דקבלה שהן [ה]סודות דנפלאו' העליוני' כפלאו' דח\"ע הוא כניסי' ונפלאו' שלמטה בהיפך הטבע נק' אין של היש המוטבע לכך נק' פלא והפלא' שאין דפלא מתגלה וכך הן סודות התורה שנק' אין שבא בגילוי השג' שנק' יש דבינה כידוע. אבל למעלה מאין ויש דחו\"ב זהו בעצמו' העונג הנעלם כמו שהוא בבחי' יש אמיתי נמשך בהתגלות ביש מוגבל שנק' מיש ליש כעוה\"ב כנ\"ל, זהו ענין ההלכו' שמלובשי' בשכל ופשט סברו' אנושי' בדברי' גשמיי' שהוא נגלה שבתו' וכמו נסים שנעשו בדרך הטבע עצמן, דגם שעכשיו א' ע\"ז אותותינו לא ראינו זהו פלא דאין לשנות הצרופי', אבל למעלה",[["971","954","<b>דח\"ע</b>: יח: דחו\"ב."],["972","955","<b>וכל דורו' יהושע</b>: יביז: ויהושע וכל דורו'."],["973","956","<b>לחם פנג</b>: ראה זהר ויחי רלה, ב. רמו, א. מאמרי אדה\"א בראשית ע' קכד. וש\"נ. דברים ח\"א ע' קג. תו\"ח לך צו, ג ובהערה 24. לקמן לג, ג. פ' בא קכז, א. בשלח קנט, ג. קסא, א. קצה, ג. רי, ד. רלה, א. ויקהל תיז, א. תכב, ד."],["974","957","<b>עתידה א\"י שתוציא גלוסקאות</b>: ראה שבת ל, ב. שע\"ת סו, א. שה\"א נח, סע\"ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלח. וש\"נ. תו\"ח בראשית לא, ד ובהערה 33. לקמן פ' תצוה שכב, ב. ויקהל תכב, ד."],["975","958","<b>עתידה אשה שתלד בכל יום</b>: שבת ל, ב. ראה אגה\"ק סכ\"ו. שה\"א נט, א [וכן צ\"ל ב]מאמרי אדה\"א ויקרא ח\"ב ע' תערב. וש\"נ. תו\"ח נח נג, ג הערה 39. לקמן פ' תצוה שכב, ב."],["976","959","<b>באו\"ח</b>: יח: באדם וחוה."],["977","960","<b>שעלו למטה ב' וירדו ד'</b>: סנהדרין לח, ב."],["978","*961","<b>מיש האמיתי ליש גמור</b>: ראה גם לקמן פ' בשלח קנט, ב. וש\"נ."],["979","961","<b>שידעו ה' פא\"פ כאשר ידבר</b>: בהעלותך יב, ח. ברכה לד, י. תשא לג, יא. ראה גם תו\"ח נח נא, ד."]]],[2300541074,"מפלא זה זהו בחי' יש האמיתי דקמי' כחשיכה כאורה העלם וגילוי אין ויש שוין ומתלבש ביש דטבע כמו שהוא בלי צריך לשנות הצרופי' כלל. וזהו ההלכו' שמלובש בהן מעצמו' דיש האמיתי כמו שהן בלבושי' גשמיי' שהוא למעלה מנפלאו' דסודו' התו' (והוא מגילת אסתר שהי' הנס בדרך הטבע שלא נז' שם הוי' ואלקי' רק המלך סתם שלא יבטל<sup data-n=\"980\">962</sup> לע\"ל וכן ההלכו' לא יבטלו<sup data-n=\"981\">963</sup> מטעם זה וכמ\"ש במ\"א), לפי שאין היש דטבע בבחי' פירוד כלל כמו בעוה\"ב כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן בתוס' ביאור מ\"ש כאן ואלה שמות בנ\"י [כו'] שמדבר בעלי' הא' שאחר ירידה הב' בדיבור וכתי' כימי צאתך מאמ\"צ אראנו לישראל זה נפלאות ב' עליות, והכל בבחי' פלא דח\"ע שהוא [ב]פנימי' דח\"ס כמ\"ש עד יעבור וזהו [אשר] אנא זמין כו'. ופלא הב' בפנימי' דע\"י בעוה\"ב שזהו עד יעבור הב', ונפלאו' אל[ה] יבאו מסדכ\"ס לגילוי בבחי' יש גמור מיש ליש בעדן עצמו כנ\"ל, שזהו עם זו ואהי' הב' כו' שהן כמו הלכו' וניסי' שבדרך הטבע שא\"צ לנפלאו' כלל, וזהו אראנו בגילוי יש למטה נפלאו' העליוני' כמו שראה ישראל זה במצרים בהיפוך הטבע כנ\"ל וד\"ל.",[["980","962","<b>שלא נז'. . שלא יבטל</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' שצז ואילך. תקס\"ח ח\"א ע' צט. ח\"ב ע' תרצה. תו\"א מג\"א קיט, ב."],["981","963","<b>ההלכו' לא יבטלו</b>: ירושלמי מגילה פ\"א, ה\"ה. רמב\"ם הל' מגילה ספ\"ב. ראה מאמרי אדה\"ז תקס\"ח ותו\"א שם. מאמרי אדה\"א נ\"ך ע' תא."]]],[2300540045,"<b>בעז\"ה ליל שבת פ' שמות</b>\n<span data-k=\"pg\">לג</span> ּ<b>ויאמר</b> מלך מצרים למילדות<sup data-n=\"982\">1</sup> העבריות<sup data-n=\"983\">2</sup> אשר שם האחת שפרה כו' אם בן הוא והמיתן אותו כו' ותיראנה",[["982","1","<b>ויאמר מלך מצרים למילדות</b>: מאמר זה נאמר ע\"י כ\"ק אדה\"ז בליל שבת פ' שמות תקס\"ה ונרשם בשעתו ע\"י כ\"ק אדה\"א. ונתבאר באריכות בד\"ה ויאמר מלך מצרים למילדות שלאח\"ז. המאמר שלפנינו (הנחת כ\"ק אדה\"א) נדפס גם בתוס' הערות וכו' באוה\"ת שמות כרך ח ע' ב'תתלט ואילך. ובאוה\"ת ענינים ע' רסט ואילך. בכת\"י הנחות הר\"מ (בן כ\"ק אדה\"ז) דשנת תקס\"ה [בוך 1149 ע' קכא, ב.]. נמצא גם הנחה אחרת מדרוש זה. והנחה זו השני' נדפסה גם [בתוס' הערות וכו'] באוה\"ת שמות כרך ז ע' ב'תצא ואילך. וראה גם אוה\"ת שמות כרך ח ע' ב'תתמט. דרך מצותיך מצות קרבן פסח (עו, ב). הערות נוספות מהצ\"צ (על הנחת כ\"ק אדה\"א) נעתקו להלן בשולי היריעה וצויין אליהם בפנים המאמר באות א ב וכו'. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["983","2","<b>ויאמר מלך מצרים למילדות העבריות</b>: שמות א, טו."]]],[2300540083,"המילדות את האלקים כו' עד סוף הפרשה כל הבן<sup data-n=\"984\">3</sup> הילוד היאורה תשליכוהו כו'. וגם<sup data-n=\"985\">4</sup> להבין ענין הפ' הסמוכה לזאת והוא סיפ[ו]ר [סיבת] לידת משה כמ\"ש ותרד בת פרעה<sup data-n=\"986\">5</sup> לרחוץ על היאור כו' עד ויהי לה לבן ותקרא שמו משה כי מן המים משיתיהו<sup data-n=\"987\">6</sup>. הנה תחלה יש להקדים להבין שרש ענין גלות מצרים ומ\"ש פרעה מי ה' אשר אשמע בקולו<sup data-n=\"988\">7</sup> ושרש ענין יניקת הקליפ[ות] למעלה מעלה, והוא ענין הידוע בע\"ח [ד]מעמד ומצב היכלו' הקליפות<sup data-n=\"989\">8</sup> הן בין או\"פ דיושר ובין בחי' עיגולים [ו]או\"מ דקדושה, פניהם אל או\"פ דיושר ואחוריהם אל בחי' העיגולים והמקיפים דקדושה כו' ע\"ש. ולהבין זה יש להקדי' הידוע בתחלה מהו או\"פ דיושר ומהו בחי' עיגולים ומקיפים ובכללם נק' או\"י ואו\"ח שהעיגולי' כלי לאו\"מ החוזר כו' [והיושר כלי למקיף הישר כו']. הנה מבשרי אחזה כו' דאנו רואים באדם התחתון שאור נשמתו מתפשטת בכלי אברי הגוף לחלקים רבים מאד וכללות החלקים הן בחי' ג' חללי גלגלתא<sup data-n=\"990\">9</sup> הידועי', שהוא מוח הזכרון במוח החכמה<sup data-n=\"991\">10</sup> ומוח הבינה שם לפני'<sup data-n=\"992\">11</sup> ומוח הדעת שבאחורי הכתפיי' ומן הדעת מתחלק עוד למח' ו[ל]מדות שבלב כו'. וגם מתפשט מהם בעיני[ם] כח הראי' ובאזני' כח השמיעה עד שמתחלקי' לחלקי' רבים בכל פרטי האברים כולם ידים ורגלים כו', [ו]הנה בודאי א\"א לומר שבכל דמות ציור ניתוח הזה שבאברים יש ג\"כ בנפש [ה]רוחניו' שהרי דבר רוחני אינו בגדר חלקי ניתוח כלל כידוע. והמופת<sup data-n=\"e1\">א</sup> לזה ממה שאנו רואים בג' חללי גלגלתא הנ\"ל שרק מפניא ניתוח בחי' ג' החללים במוח נתחלק אור השכל לג' חלקים הנ\"ל מוח חכ' מוח בינה [ו]מוח הדעת כו', אבל בענין ומהות<sup data-n=\"993\">12</sup> הנפש לא<sup data-n=\"e2\">ב</sup> נתחלק עדיין ממנו<sup data-n=\"994\">13</sup> אור השכל לג' חלקים כלל אלא הוא כח א' בלבד והיינו בחי' כח",[["984","3","<b>אם בן הוא. . ותיראנה. . כל הבן</b>: שמות שם, טז. יז [ושם: ותיראן — וכ\"ה לקמן כו, ב]. כב."],["985","4","<b>וגם</b>: ז: ולהבין זה וגם. אבדהח: כבפנים."],["986","5","<b>ותרד בת פרעה</b>: שמות ב, ה."],["987","6","<b>ויהי לה לבן. . משיתיהו</b>: שם ב, י [בדילוג]."],["988","7","<b>מי ה' אשר אשמע בקולו</b>: שמות ה, ב."],["989","8","<b>[ד]מעמד. . הקליפות</b>: באוה\"ת כאן (ע' ב'תצא) מציין: והוא בע\"ח שער מ\"א פ\"ה בד\"ה ועתה נדבר [והוא בהוצאת שקלאב תק\"ס. ובדפו\"א שמ\"ב, פ\"ג ופי\"ג]. ראה מאמרי אדה\"א דברים ח\"א ע' יג. וש\"נ. שע\"ת צה, ד ובהערה 34. לקמן לא, ג. פ' בשלח קפא, ד."],["990","9","<b>ג' חללי גלגלתא</b>: באוה\"ת כאן (ע' ב'תצא) מציין: ועיין מזה בזח\"ג נשא דק\"מ ע\"א. ואתחנן דרס\"ב ע\"א ובת\"א פ' תצוה בביאור ועשית ציץ וכן הוא בספרי הניתוח בשבילי אמונה נתיב רביעי שביל ראשון ובספר הברית מאמר י\"ז פ\"ד. וצ\"ע בכוזרי מאמר ה' סי' י\"ב בפי' האוצר נחמד שם [ד\"ה והכח הזוכר] ודע שהקדמונים."],["991","10","<b>מוח הזכרון במוח החכמה</b>: ראה גם אוה\"ת תצוה ע' א'תרנה [והוא משנת תקע\"ב]. מאמרי אדה\"א שמות ח\"ב ע' תקמא. וש\"נ. נ\"ך ע' צט. הנחות תקע\"ז ע' קנ וע' רמ. תו\"ח מקץ ריט, א. לקמן כז, ג. לד, ג. פ' יתרו רסח, ד. תצוה שנ, ד."],["992","11","<b>שם לפני'</b>: אדהז: שמלפנים. ובאוה\"ת כאן (ע' ב'תתמ): שהם מלפנים."],["993","12","<b>בענין ומהות</b>: אד: בעצמות מהות. ה: בעצמו' ומהות."],["994","13","<b>ממנו</b>: בד: ממנה.\n\n<b>א</b>  <b>והמופת. . מפני</b>: ה: כ\"ז ליתא ובמקומו מובא: ומה שנתחלק לג' בחי' הנ\"ל במוחין מוח החכ' כו' הוא מצד התלבשותה בכלי המוחין שהם מחולקים לג' בחי' ומפני.\n<b>ב</b>  <b>לא. . והחכ'</b>: שם במקום תיבות אלו: אין שם בחי' התחלקות לג' חלקים הנ\"ל כי היא למעלה מבחי' חכ' ושכל והשכל מסתעף הימנה והיא עצמה נק' משכיל שהוא המקור המוליד ומהווה השכל כמ\"ש משכיל לאיתן האזרחי כו' (וע\"ש זה נק' נפש המשכלת שמהווה את השכל."]]],[2300540121,"רוחני' החכמה שקבוע בנפש ונק' משכיל כמ\"ש משכיל לאיתן האזרחי<sup data-n=\"995\">14</sup> כו' כלומר שפועל כל ההשכלות והחכמות כו', ועכ\"ז<sup data-n=\"996\">15</sup> נק' הנפש נפש המשכלת<sup data-n=\"997\">16</sup> פי' שמשכלת את אור השכל והחכ'ב להיות האדם משכיל שכליי' הרבה בכמה מיני מדרגות, וכללותם הן בחי' ג' מדרגו' הנ\"ל כאשר מתחלקת בג'ג חללי גלגלתא הנ\"ל וד\"ל<sup data-n=\"e3\">ג</sup>. וא\"כ מה שנתחלק<sup data-n=\"e4\">ד</sup> אור השכל הנק' משכיל לג' חלקים בג' חללי[ם] הנ\"ל אינו אלא מצד בחי' הג' חללים אבל לא מצד עצמו מפני שהוא פשוט ואינו מורכב בגדר חלקים וניתוח כלל כנ\"ל, ועד\"ז גם [ל]מטה מטה בניתוח שארי כחות האברים כולם כמו כח הראי' בעין עד שהם במספר רמ\"ח אברים אינן באים בבחי' ציור ניתוח גשמי אלא מצד כלי האברים, אבל מצד עצמ[ם] כמו שהן בנפש אינם בבחי' התחלקות כלל וכלל אלא הנפש כלולה מכל כחות האברים בתכלית ההתכללו' בבלתי פירוד והתחלקות כלל וד\"ל. והמופת היותר אמיתי לדבר זה שאם הי' ציור כחות<sup data-n=\"998\">17</sup> התחלקות בנפש הרוחני' ג\"כ איך היו שוכנים בה יחד ב' הפכים המנגדים בתכלית כמו כח הקרירות שמשכנ[ו] במוח וכח החמימות שמשכנ[ו] בלב<sup data-n=\"999\">18</sup>, או הרכבת אש ומים ורוח שבהבל<sup data-n=\"1000\">19</sup> הלב שהאש ו[ה]מים מנגדי' בתכלית כידוע, <span data-k=\"pg\">68</span> ּ ובשלמא בגוף מפני שיש לכל אחד בחי' כלי מיוחדת שיכולה<sup data-n=\"1001\">20</sup> לשכון כמו כלי המוח לקרירות וכלי הלב לחמימות וכן מיוחדים טבעי'<sup data-n=\"1002\">21</sup> לכל כחות האברים ומפני שהאברים מרוחקים זה מזה כו', אבל בנפש הרוחני' איך ישכנו בו<sup data-n=\"1003\">22</sup> מנגדי' יחד כו'. אך הענין הוא [ד]באמת אין לחיות הנפש המתפשט' בכלי הגוף ערך והשתוות כלל לגבי מהו\"ע הנפש עם כחותי' כאשר כלולי' בה עד שאינ[ה] מתייחסת ממהותה כלל וכלל יותר<sup data-n=\"e5\">ה</sup> משאין ערך הזיו של השמש לגבי השמש כו', וע\"כ יוכל לשכון במהות הנפש ב' ההפכיי' המנגדיי' המתפשטי' בגוף והיו לאחדים בה כו', והכל טעם ושרש א' דלפי שאין עצמות הנפש לא מיני' ולא מקצתי' ממהות כחות הנראים המתפשטי' בכלי הגוף ע\"כ אין בה ציור ניתוח התחלקות כלל כ[נ\"ל] אלא ישכנו כולם יחד [בה] בתכלית ההתכללות עד שלא ימצאו כלל במציאות מנגדים וכדומה כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למשכיל למעלה דבחי' היושר שהוא בציור אדם<sup data-n=\"1004\">23</sup> כידוע בע\"ח ושרשו מבחי' הקו\"ח<sup data-n=\"1005\">24</sup> כו' מקור",[["995","14","<b>משכיל לאיתן האזרחי</b>: תהלים פט, א. ראה גם לעיל יב, ג. מאמרי אדה\"א דברים ח\"ב ע' שסט."],["996","15","<b>ועכ\"ז</b>: אד: וע\"ש זה."],["997","16","<b>נפש המשכלת</b>: ראה תניא פ\"ג. פ\"ה. פל\"ג. פ\"נ."],["998","17","<b>כחות</b>: אדה: בחי'."],["999","18","<b>כח הקרירות. . במוח וכח החמימות. . בלב</b>: ראה תניא פ\"ג."],["1000","19","<b>הרכבת אש ומים ורוח שבהבל</b>: נסמן לעיל יט, ג."],["1001","20","<b>שיכולה</b>: אדה: יוכלו."],["1002","21","<b>מיוחדים טבעי'</b>: ד: מיוחדת טבעיות. ה: מיוחדות טבעיות."],["1003","22","<b>בו</b>: אדה: ב'."],["1004","23","<b>היושר שהוא בציור אדם</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב. ג."],["1005","24","<b>היושר. . ושרשו מבחי' הקו\"ח</b>: ראה גם לקמן כט, ג. פ' ויקהל שפז, ב. מאמרי אדה\"ז תקס\"ב ח\"א ע' רכח. לקו\"ת קרח נב, ב ואילך.\n\n<b>ג</b>  <b>בג'. . וד\"ל</b>: שם: בחללי גלגלתא והרי בחי' זו שנק' הנפש משכיל הוא בחי' מקור כללי לג' מוחין חב\"ד כאחד ממש).\n<b>ד</b>  <b>שנתחלק</b>: שם: שאח\"כ נתחלק.\n<b>ה</b>  <b>יותר. . השמש</b>: כ\"ז נמחק שם."]]],[2300540159,"כל האו\"פ<sup data-n=\"1006\">25</sup> דיושר כו', אבל<sup data-n=\"1007\">26</sup> הענין הוא כאשר עצמות אוא\"ס נאצל כבר<sup data-n=\"1008\">27</sup> בבחי' התפשטות ההארה ובחיות<sup data-n=\"1009\">28</sup> הג[י]לוי מן ההעלם בלבד כדוגמת האר[ת] עצמות הנפש המתפשטת בכלי הגוף כנ\"ל אבל לא הי' עדיין בחי' התחלקו' כחות הנאצלי' כלל בעצמות אוא\"ס אלא הוא פשוט בתכלית כו' רק לאחר שנאצל אור וגילוי המאציל נעשה [ב]בחי' התחלקות, וכלל[ות] ההתחלקות הן בחי' ג' חללי גלגלתא דז\"א כו', ועד\"ז עד רום המעלות הוא והיינו [גם] בחכ' דא\"ק הגם שאין שם כלים גמורים אבל יש בו שורש דשרש<sup data-n=\"1010\">29</sup> להתהוות<sup data-n=\"1011\">30</sup> הכלים<sup data-n=\"1012\">31</sup> דחכ' באצי' כו' וד\"ל. וכן כל פרטי אורות שנאצלים<sup data-n=\"1013\">32</sup> מחכ' ואילך הכל מצד בחי' הכלים מכלים שונים הנק' אדם בציור ניתוח אברים כו' בלבד עד שימצא בהן ב' הפכים חו\"ג אוי\"ר<sup data-n=\"1014\">33</sup> כו' או מוח ולב קרירות וחמימות כו', אבל מצד שרשם בעצמות המאציל<sup data-n=\"e6\">ו</sup> אין [בהם] בחי' התחלקות כלל אלא כלולים בתכלית ההתכללות בעצמות אוא\"ס עד שאינם במציאות ב' הפכים כלל וכלל כמ\"ש<sup data-n=\"1015\">34</sup> במשל, והוא לפי שעצ[מות] אוא\"ס אין לו ערך כלל כו', דהיינו שאין הנאצלי' ממהותו כלל וכלל כו' וד\"ל כמ\"ש<sup data-n=\"1016\">35</sup> במ\"א וד\"ל. ולכך נק' מבחי' הקו\"ח ולמטה בשם השתלשלו' לשון שלשלת<sup data-n=\"1017\">36</sup>, כמו שבשלשלת כ\"א אחוז בעליון הימנו כו' כך למעלה נשתלשל אור המאציל מהארת הקו עד בהיות כאו\"א על מקומו [י]בא זה למטה מזה וכל א' קשור בעליון הימנו כו', והוא רק בחי' ריבוי הכלים מכלים שונים באצי' עד שגם נשתלשל מהם הארה דהארה כו' גם למטה בבי\"ע, והן בדרך כלל מבחי' למ\"ד כלים דז\"א<sup data-n=\"1018\">37</sup> דאצי' כידוע שמיו\"ד כלים הפנימי' נעשה בחי' נשמה לעולם הבריא' ומהאמצעי' בחי' רוח ליצי' ומהחיצוני' נעשה בחי' נפש לעשי' כו'. והענין הוא דגם [ב]בחי' כלי [ה]עשי' יוכל להיות כמה מדרגות כמו היד והרגל ששניהם בבחי' כלי [ה]עשי', והנה יש הפרש גדול במדריגה ביניהם שהרי היד פועל פעולת הכתיבה שהוא לכתוב ולצייר ענין שכלי שמעשהו דקה ופעולת כלי הרגל גסה שהוא לעמוד ולהלך הילוך גשמי כו', כמו\"כ כללות בחי' הלמ\"ד כלים דאצי' הגם שהן בחי' עשי' לגבי אורות הנאצלים <span data-k=\"pg\">לד</span> ּ בהם שהם כדוגמ[ת] ציור כלי אברי גוף האדם כו' עכ\"ז יש בהם מדרגות הרבה, ובכללות הן ג' מדרגות דהיינו בחי' התהוות החכמה ו[ה]השגה המוגבלת דנשמות ומלאכי' [ד]עולם הבריאה",[["1006","25","<b>האו\"פ</b>: אז: ע\"ס."],["1007","26","<b>אבל</b>: אדה: ליתא."],["1008","27","<b>נאצל כבר</b>: ד: האציל דבר."],["1009","28","<b>ובחיות</b>: אדה: ובחי'."],["1010","29","<b>דשרש</b>: אז: ליתא."],["1011","30","<b>דא\"ק. . שורש דשרש להתהוות הכלים</b>: בסה\"מ תרנ\"ד ריש ע' רצט מציין: כמ\"ש בע\"ח שער דרושי אבי\"ע פ\"ד [והוא בהוצאת שקלאב תק\"ס ובדפו\"א פ\"ב]. אוה\"ת בלק ע' תתקעא־ ענינים ע' פז [ושם: בע\"ח שמ\"א פ\"ז — והוא בהוצאת שקלאב וכנצ\"ל: פ\"ד כבסה\"מ הנ\"ל]. המשך תער\"ב ח\"ב ע' תתעו. ראה גם לקמן כט, א."],["1012","31","<b>הכלים</b>: דה: הכלי. אז: כלים."],["1013","32","<b>אורות שנאצלים</b>: אדה: האורות שנאצלו."],["1014","33","<b>אוי\"ר</b>: אדה: אש ורוח."],["1015","34","<b>וכלל כמ\"ש</b>: אדה: וכנ\"ל."],["1016","35","<b>וד\"ל כמ\"ש</b>: אדה: וכמ\"ש."],["1017","36","<b>השתלשלו' לשון שלשלת</b>: ראה גם לקמן כט, סע\"ב. פ' בא קלא, ד. בשלח קמד, א. קסה, ב. סידור ערב שבת קסא, ד. תו\"א בשלח סד, ב. מג\"א צ, א. לקו\"ת ואתחנן יב, א. ברכה צה, ב. שה\"ש מב, ב. ש\"א נד, א. מאמרי אדה\"א דברים ח\"א ע' קכז. וש\"נ. תו\"ח וישלח קפח, ב ובהערה 28."],["1018","37","<b>למ\"ד כלים דז\"א</b>: ראה קו\"א לתניא (ד\"ה להבין מ\"ש בפע\"ח) קנו, ריש ע\"ב. לקמן פ' וארא נז, ד. יתרו רנח, ד הערה 92.\n\n<b>ו</b>  <b>בעצמות המאציל</b>: שם: בבחי' העיגול הגדול של החלל ומקו\"פ הסובב את הכל (שמשם שרש העיגולים כמ\"ש בכיהאריז\"ל)."]]],[2300540196,"הן [מ]בחי' פנימי' הכלים והתהוות המדות ביצי' מאמצעית כו' והתהוות עולם העשי' מבחי' סוף כלי מעשה דאצי' כמו כלי הרגל להלוך כו'. ועד\"ז<sup data-n=\"e7\">ז</sup> יובן בפרטי פרטיות, כי הנה גם בי\"ע כל אחד כלול מבי\"ע, עד שגם בי\"ס דעשי' יש ג' מדרגו' הללו (וכידוע ממשל מחדו\"מ שבאדם שבחי' הדמיון שבמח' הוא בחי' עשי' שבמח' ובחי' ציווי המעשה הוא בחי' המעשה שבדבור עד שבחי' המעשה שבמעשה [הוא] האחרון מכולם ונק' עשי' דעשי'ז [וד\"ל]. והיינו מאמר [עד] דמטי רגלין ברגלין<sup data-n=\"1019\">38</sup> כו' פי' רגלין הוא בחי'<sup data-n=\"1020\">39</sup> מדרגה התחתונה שבבחי' כלים די\"ס דעשי' כו', ונק' ג\"כ רגלי השכינה<sup data-n=\"1021\">40</sup> כו' וד\"ל.\n[ב] <b>והנה</b> ידוע דתכלית המכוון במאציל בכל ההשתלשלו' הי' כדי שיהי' בירידה זו בחי' עלי', וירידה זו לצורך עלי' היתה, והענין הוא כדי שבהארת האצי' בבי\"ע בנשמות ומלאכים יהי' בהם בחי' הביטול במציאות בהתפעלו' רב ועצום בכאו\"א לפי מדרגתו ושרשו, כמו מחנה מיכאל בחי' העלאת מ\"נ שלהם במס\"נ וביטול במציאות בבחי' התשוקה ומדת האהבה כו', ומחנה גבריאל בחי' כלות הנפש במדת הפחד כו' והוא בחי' הביטול בכלל, וימצא בזה רבוא<sup data-n=\"1022\">41</sup> רבבות מדרגות שונות כו' כידוע בזהר פ' פקודי<sup data-n=\"1023\">42</sup>. וידוע דבהיכלות הקליפות החיות אלק[י] בסוד גלות השכינה כו' דהיינו שיודעים את רבונם וקרו לי' אלקא דאלקיי'<sup data-n=\"1024\">43</sup> כו' אבל אין בהם בחי' הביטול כלל אלא הם יש ודבר בפ\"ע כו', ולכך הם אינם חפיצים כלל בבחי' היושר דהיינו המשכות גילוי אור בכלים רבים בבחי' התיקון [ד]ציור אדם ב[א]בי\"ע כנ\"ל, מפני שאז לא יגיע השפע האלקי' רק בקדושה כמו<sup data-n=\"1025\">44</sup> בנשמות ומלאכים עליונים ולא יגיע אליהם כלל וכלל רק בבחי' חיצוניות דחיצוניות בלבד, מאחר שעיקר הכוונה במאציל בירידה של ההשתלשלו' לצורך עלי' דוקא, ובבחי' ביטול דמלאכים ונשמות ירד האור אבל בזולתם שאין בהם בחי' הביטול לא ירד, כמ\"ש [אני ה'] וכבודי<sup data-n=\"1026\">45</sup> לאחר לא אתן, כמאמר אין אני והוא<sup data-n=\"1027\">46</sup> יכולים<sup data-n=\"1028\">47</sup> כו' בגה\"ר<sup data-n=\"1029\">48</sup> וכדומה. אלא הם חפצים יותר בבחי' העיגולים כלי המקיפים דאו\"ח [כו'] והוא למעלה מבחי' היושר שרש כל השרשים דאו\"פ שאי[נו] אלא הקו\"ח כנ\"ל אלא [הוא] בחי' העיגול והמקיף הסובב [ל]בחי' הקו\"ח כו' כידוע,",[["1019","38","<b>[עד] דמטי רגלין ברגלין</b>: ראה זהר פקודי רנח, א ובמק\"מ שם. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתמה־ דברים ח\"א ע' עז."],["1020","39","<b>בחי'</b>: אדה: ליתא."],["1021","40","<b>רגלי השכינה</b>: ברכות מג, ב. חגיגה טז, א. ראה גם מאמרי אדה\"א שמות ח\"א ע' קט. וש\"נ."],["1022","41","<b>רבוא</b>: אדה: ריבוי."],["1023","42","<b>בזהר פ' פקודי</b>: נסמן לקמן ל, ב."],["1024","43","<b>אלקא דאלקיי'</b>: מנחות בסופה."],["1025","44","<b>כמו</b>: אדה: ליתא."],["1026","45","<b>אני </b>[ה']<b> וכבודי</b>: ישעי' מב, ח [בדילוג — ראה גם מאמרי אדה\"א נ\"ך ע' קצא. וש\"נ]. ובאוה\"ת כאן (ע' ב'תתמב) לא הובאו התיבות אני ה'."],["1027","46","<b>אין אני והוא</b>: סוטה ה, א. ערכין טו, ב."],["1028","47","<b>יכולים</b>: אדה: ליתא."],["1029","48","<b>בגה\"ר</b>: דה: בגסי הרוח.\n\n<b>ז</b>  <b>ועד\"ז. . דעשי'</b>: שם ליתא."]]],[2300540230,"והוא עד\"מ בחי' העלם עצ[מות] הנפש קודם שתתפשט אור[ה] בכלים מכלים שונים כו' שאין בה התחלקות כלים כלל אלא נכלל הכל כא' כו', כמו\"כ בבחי' מקיפי' עליונים דקו\"ח כו' הרי הוא עדיין מבחי' עצ[מות] המאציל שאין בו בחי' כלים כלל ולפניו הכל שוין כו' כחשיכ[ה] כאורה<sup data-n=\"1030\">49</sup> [כו'], ויכולים גם הם לקבל יניקה ושפע מאחר שהוא למעלה [מעלה] מבחי' השתלשלות לגמרי כו'. והמשל הגשמי בזה [ל]חביות שמליאה מים כאשר הברזא יוצא ממנה ולא יצא<sup data-n=\"1031\">50</sup> ממנה המשקה רק דרך הברזא הנה אז לא יצא המשקה לאיבוד בכלי מכוער וכדומה וגם לא יותר מדאי מכפי<sup data-n=\"1032\">51</sup> המדה כו', אבל כשאין בה ברזא אלא היא פתוחה מכל צד (והתהום נובע בה<sup data-n=\"1033\">52</sup> ) הנה <span data-k=\"pg\">70</span> ּ אין שיעור ליציאת המשקה ממנה מכל צד ופנה ובלא דקדוק כלל באיזה כלי כו' והכל פונים לשם כו'. והנמשל יובן ברוחניות שקודם בחי' הירידה בבחי' הקו\"ח באו\"פ דיושר כו' הי[ו] הכל יכולים לקבל גם מי שאינו ראוי מאחר שאינו לפי המדה ולא בא אור השפע לכלל כלי זו<sup data-n=\"1034\">53</sup> המדה המודד כל ההשפעות כו', ולכך גם דור אנוש היו ניזוני' מחסדו<sup data-n=\"1035\">54</sup> של הקב\"ה<sup data-n=\"1036\">55</sup> (וכמו אברהם [כאשר] הי' עדיין מאותו המדריגה שלמעלה מבחי' הכלים דתיקון כו' כמו שנא' בו אב המון גוים נתתיך<sup data-n=\"1037\">56</sup> כו' אמר לו ישמעאל יחי' לפניך<sup data-n=\"1038\">57</sup> כו'<sup data-n=\"1039\">58</sup>, עד שמבחי' מותרי החסדי' דאברהם מקבל גם ישמעאל דקליפה כו', משא\"כ ביצחק כמ\"ש כי ביצחק יקרא לך זרע<sup data-n=\"1040\">59</sup> שהובדל להיות בבחי' הקדושה והוא בבחי' התיקון דכלי האו\"פ דיושר כו' וד\"ל).\n<b>וזהו</b> שרש ענין גלות מצרים עד שאמר פרעה מי הוי' אשר אשמע בקולו כו', פי' הוי' ידוע שהוא בבחי' התיקון דיושר הנ\"ל דהיינו [ש]צמצום האור נשתלשל<sup data-n=\"1041\">60</sup> להאיר בבחי' כלי, והן ד' אותיות דשם הוי' בפרט [ש]בכל ספי' וספי' כידוע שהיו\"ד הוא בחי' הצמצום והה'<sup data-n=\"1042\">61</sup> בחי' התפשטות והוי\"ו הוא בחי' המשכה [כו'], ובדרך כלל הנה ידוע דד' אותיות הוי' הן ד' עולמות אבי\"ע<sup data-n=\"1043\">62</sup> שנמשכו ונתפשטו מן המאציל, דהיינו היו\"ד הוא התפשטו' האצי' והה' הוא התפשטות עולם הבריאה והוי\"ו בעולם היצי' כו', ועד\"ז בפרטי פרטיות גם באצי' עצמו שכלול מאבי\"ע<sup data-n=\"1044\">63</sup> כידוע הכל ע\"י שם הוי' כו' וד\"ל, והנה ענין הגלות",[["1030","49","<b>כחשיכ[ה] כאורה</b>: תהלים קלט, יב."],["1031","50","<b>יצא</b>: אה: יוציאו."],["1032","51","<b>מכפי</b>: אדה: רק כפי."],["1033","52","<b>(והתהום נובע בה)</b>: אדה: והתהום נובע בה."],["1034","53","<b>זו</b>: אה: קו."],["1035","54","<b>דור אנוש היו ניזוני' מחסדו</b>: כ\"ה בכ\"מ — ראה פסחים קיח, א. מאמרי אדה\"א דברים ח\"א ע' נא־ וע' רח־ ח\"ד ע' א'תעז. ובהנסמן בהנ\"ל. בראשית ע' תצג. קונטרסים ע' ריד. הנחות תקע\"ז ע' רעח וע' שכד. תו\"ח בראשית ח, ד. מ, ב. ח\"ש קלט, ד. תולדות קמה, א. לקמן לא, א. פ' בשלח קלד, ד. קעד, א. רכא, ב. רמח, ג."],["1036","55","<b>של הקב\"ה</b>: אדה: [ו]כו'."],["1037","56","<b>אב המון גוים נתתיך</b>: לך יז, ה."],["1038","57","<b>לו ישמעאל יחי' לפניך</b>: לך יז, יח."],["1039","58","<b>כו'</b>: אדה: ליתא."],["1040","59","<b>כי ביצחק יקרא לך זרע</b>: וירא כא, יב."],["1041","60","<b>נשתלשל</b>: אד: כאשר נתצמצם. ה: כשנתצמצם."],["1042","61","<b>שהיו\"ד. . והה'</b>: ראה אגה\"ת פ\"ד. לקמן פ' בשלח קנ, א ואילך."],["1043","62","<b>דד' אותיות הוי'. . אבי\"ע</b>: ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"א. לקו\"ת להאריז\"ל בראשית עה\"פ (ג, כג) וישלחהו ה\"א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תצא. תו\"ח ח\"ש קכח, ב הערה 21."],["1044","63","<b>באצי' עצמו שכלול מאבי\"ע</b>: ראה פרדס (שער טעם האצילות) ש\"ב, פ\"ז. ע\"ח (שער כללות אבי\"ע) שמ\"ב, רפ\"ד. (שער סדר אבי\"ע) שמ\"ז ספ\"ב. לקמן פ' בא קכב, א."]]],[2300540262,"הוא למעלה באצי' בחי' שינה<sup data-n=\"1045\">64</sup> כמ\"ש עורה למה תישן<sup data-n=\"1046\">65</sup> [כו'], וגם נק' בשם בחי' עיבור, והכל ענין א' הוא דהיינו כמו עד\"מ שהמוחי' בתכלית הקטנות [ב]ולד המונח בבטן אמו להיותו מקופל ראשו בין ברכיו כידוע והרי הוא בבחי' הסתלקות המוחין כו', והרי ראשו שמונח בין ברכיו היינו שנעלמו ונתלבשו בחי' המוחין שלו בבחי' נה\"י שבו בלבד, והיינו ענין תלת כלילן גו תלת<sup data-n=\"1047\">66</sup> שבבחי' עיבור כידוע וד\"ל. ועד\"ז ג\"כ בבחי' שינה באדם שהרי אנו רואים באדם כשישן נסתלק כח שכלו ממנו וגם כחות מדותיו ולא נשאר בו רק בחי' נה\"י<sup data-n=\"1048\">67</sup> דהיינו כלי אברי הנש[י]מה בדפיק[ו] דלבא שהוא בחי' נפש בלבד כמ\"ש במ\"א, ולהיכן נסתלק כח השכל הרי בודאי נסתלק ונכלל השכל במקור השכל והוא בחי' עצ[מות] הנפש וכן המדות נכללו במקורן כו', וא\"כ ה\"ז בחי' עלי' גדולה לשכל ו[ל]מדות יותר הרבה מכמו שהן באדם כשניעור, שהרי בהיותן באדם כשניעור הן בבחי' ירידה ושפלות הצמצום דהיינו כאשר הן כבר נתצמצמו מאור עצ[מות] הנפש משא\"כ בהיותן כלולים בעצ[מות] הנפש [בשעת שינה] שהן בלא צמצום כלל, וכמ\"ש למעלה שאין ערך כלל בין כחות הנפש בהיותן כלולים בעצ[מותה] לכמו שהן מתפשטים בכלי אברי הגוף כו', עד שבעצ[מות] הנפש הן בבלתי התחלקות כלל ובבלתי מוגבל בבחי' כלי כלל כו'. והנמשל מב' ענינים הללו מבחי' עיבור ומבחי' שינה יובן למעלה שזהו סוד גלות למעלה, דתלת כלילן גו תלת כו' היינו שבחי' חג\"ת וגם בחי' המוחין חב\"ד דז\"א דאצי' מסתלקי' ונכללי' בעצמות המאציל כמו שהיו כלולים בו קודם שהאצילן והם נעשים בבחי' א\"ס ממש כו' עד שאין ערוך כלל כמו שהן בבחי' צמצום בכלים מכלים שונים כו' וד\"ל. וז\"ש פרעה העליון העומד אחורי בחי' כתר<sup data-n=\"1049\">68</sup> עליון דקדושה שנכללו בו האורות בשעת הגלות<sup data-n=\"e8\">ח</sup> כמ\"ש במ\"א, מי הוי' אשר אשמע",[["1045","64","<b>גלות. . שינה. . ועיבור</b>: ראה גם תו\"ח מקץ רטו, ג. מאמרי אדה\"א ויקרא ח\"א ס\"ע רלט. לקמן פ' וארא סז, ד. תצוה שלג, ד. לעיל יז, ג. וש\"נ. לקמן לא, ג. לז, ד. וש\"נ."],["1046","65","<b>עורה למה תישן</b>: תהלים מד, כב."],["1047","66","<b>תלת כלילן גו תלת</b>: נסמן לקמן לח, ד."],["1048","67","<b>נשאר בו רק בחי' נה\"י</b>: ראה [ובהבא בסמוך] לקמן שם. וש\"נ."],["1049","68","<b>פרעה. . אחורי בחי' כתר</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' קמד. לקמן לב, ד ובהנסמן שם. וראה גם אוה\"ת כאן ס\"ע ב'תקב ואילך (נוסח א').\n\n<b>ח</b>  <b>בשעת הגלות</b>: שם ליתא."]]],[2300540291,"בקולו, כלומר לפי שאז הרי<sup data-n=\"e9\">ט</sup> הוא למעלה מבחי' <span data-k=\"pg\">לה</span> ּ שם הוי'<sup data-n=\"1050\">*69</sup> דהיינו בבלתי גדר התחלקות כלל ובבלתי הגבלת כלים מכלים שונים אלא כלול בבחי' העצמות כו' וכנ\"ל, וע\"כ מי הוא שם הוי' לפי שאינו מכיר אותו כלל מפני שגבוה הרבה מאד ממנו מטעם הנ\"ל<sup data-n=\"e10\">י</sup> וד\"ל. והנה מבואר למעלה שהחיצוניות<sup data-n=\"1051\">69</sup> אינם רוצים כלל בבחי' התיקון דיושר בהמשכ' האורות בכלים מכלים שונים לפי שעי\"ז לא יגיע אליהם השפע כלל כו', וזהו ענין הגלות שרוצים שיהי' בחי' הסתלקות המוחין ויוכללו בעצמות המאציל מפני שמשם יקבלו גם הם יניקה מטעם הנ\"ל דשם הוא למעלה מבחי' הכלים ויכולים הכל לקבל וכענין אברהם שא' לו ישמעאל יחי' [לפניך ו]כנ\"ל וד\"ל.\n<b>ובכל</b> הנ\"ל יובן ענין<sup data-n=\"e11\">יא</sup> הנ\"ל דיניקת החיצונים בשרשם למעלה הוא מבחי' העיגולים המקיפים כו' ומעמדם בין או\"פ לאו\"מ פניהם אל האו\"פ ואחוריהם אל האו\"מ כו', כי הנה מבואר שכל תשוקתם שיוכללו בחי' האו\"פ באו\"מ כדי שגם הם יוכלו לקבל כו'. אמנם גם בבחי' או\"פ דיושר יש להם קצת יניקה דהיינו גם לפי סדר ההשתלשלו' האור[ות] בכלי[ם] כו' דהא גם הםיא קרו לי' אלקא דאלקייא ויש להם בחי' ביטול קצת שהרי אינם בעלי בחירה להיות עוברי רצונו כו', והגם שאינ[ם ב]בחי' ביטול אמיתי כביטול המלאכים ונשמות דקדושה כו'<sup data-n=\"e12\">יב</sup>, שהרי גם בלעם אמר<sup data-n=\"e13\">יג</sup> לא אוכל לעבור את פי' ה'<sup data-n=\"1052\">70</sup> לעשות קטנה או גדולה כו', וא\"כ<sup data-n=\"e14\">יד</sup> יש להם חיות מעט מזעיר מצומצם מאד גם בבחי' השתלשלו' דהיינו אחר שירד האור בכמה מיני צמצומי' למטה מטה בעשי' כו' שם יש<sup data-n=\"1053\">71</sup> להם אחיזה קצת, וזהו שפניהם שם אל האו\"פ דקצה האחרון בכל ההשתלשלו' כו' אלא<sup data-n=\"e15\">טו</sup> שהם בבחי' יש ודבר בפ\"ע אבל אין יכולים למרוד כלל כמ\"ש בבלעם וד\"ל.",[["1050","*69","<b>פרעה. . מי הוי'. . למעלה מבחי' שם הוי'</b>: ראה גם לקמן פ' בא קכז, ב."],["1051","69","<b>שהחיצוניות</b>: דה: שהחיצונים. א: מטושטש."],["1052","70","<b>לא אוכל לעבור את פי ה'</b>: בלק כב, יח [ושם: ה\"א]."],["1053","71","<b>כו' שם יש</b>: אה: דעשי' כו' שם יש. ד: גשמי כנ\"ל שיש.\n\n<b>ט</b>  <b>הרי</b>: שם ניתוסף: עליית הסתלקות האורות.\n<b>י</b>  <b>שגבוה. . הנ\"ל</b>: שם: דאסתלק לעילא שמוחין דז\"א בבחי' עיבור בבטן אימא ואינן מאירים כ\"כ למטה בעת הגלות כנ\"ל.\n<b>יא</b>  <b>ענין. . גם הם</b>: שם: מ\"ש האריז\"ל שמעמד הקליפות אחוריהם אל המקיף כי משם יוכל להגיע שפע גם אליהם דרך אחוריי' משא\"כ מבחי' הא\"פ דיושר שהאורות מלובשים תוך הכלים והכלי מגביל ומסתיר האור מכל צד אזי אין מקום להחיצוני' לקבל מהם מאחר שאור ושפע זו אינו יורד רק להתלבש בתוך הכלים שנמצא בהם בחי' הביטול הם נשמות ומלאכים וכל סט' דקדושה דוקא ולא סט\"א כנ\"ל.\nאמנם מ\"ש האריז\"ל שמעמד הקליפות פניהם אל הפנימי הענין כי עוד זאת יש מקום להחיצונים לינק גם מהפנימי. והיינו כאשר יורדת השפע עליונה להתלבש בכלים דבי\"ע בהגבלה וצמצומי' גדולי' כ\"כ עד שמתצמצמת מאד בכלים מכלים שונים בבחי' קטנות מאד אז יוכלו החיצוני' לינק דרך שערות דנוק' כו' כנודע דהא.\n<b>יב</b>  <b>כו'. . כו'</b>: שם ליתא.\n<b>יג</b>  <b>אמר</b>: שם ניתוסף: על שרשו ברוחניו' הסט\"א שאין יכול למרוד בה' וזהו.\n<b>יד</b>  <b>וא\"כ</b>: שם: אלא שאינו בחי' ביטול אמיתי כביטול הנשמו' ומלאכי' דקדושה כו' וא\"כ מ\"מ.\n<b>טו</b>  <b>אלא. . וד\"ל</b>: שם: רק בהיות שלא נתצמצמה השפע כ\"כ בבחי' קטנות כ\"א היא מלובשת בתוך הכלים בבחי' גדלות ממש אזי אין באפשרי להם לינק ממנה כלל כמשנ\"ת לעיל. נמצא העולה מזה שיש מקום ליניקת החיצונים בב' אופנים הא' הוא מבחי' המקיף עצמו שלמעלה מהכלים שז\"ס אחוריהם אל המקיף והב' מבחי' קטנות וצמצום השפע דא\"פ כאשר נתצמצמו בקטנות מאד שאז יונקים דרך השערות דנוק' וז\"ס פניהם אל הפנימי, זולתי מבחי' הממוצעת דהיינו כאשר השפע היא מלובשת בתוך הכלים רק היא שם עדיין בבחי' גדלות אזי אין יכולים לקבל חיות ויניקה משם כנ\"ל. והנה בזמן הגלות שהז\"א מעובר בבטן אימא כנ\"ל לכך הם אז מושלים על ישראל כי אז יוכלו לקבל היניקה מקדושה מב' אופנים הנ\"ל הא' מבחי' הקטנות דא\"פ המלובש בהכלים בקטנות וצמצום גדול מאד והיינו מאחר שז\"א מעובר בבטן א' תלת כלילן גו תלת שהוא בחי' קטנות מאד לכך יכולים אז לינק דרך שערות וצמצומי' מפני שהשפע בקטנות מאד וכנ\"ל. והב' הוא בהיות כי עיבור הז\"א בבטן אי' הוא בחי' ההסתלקו' שלו בבחי' א\"ח אל המקיף הוא אי' דאצי' לכך יכולים לינק אז מן המקיף ג\"כ כנ\"ל וד\"ל."]]],[2300540319,"[ג] וזהו ויאמר מלך מצרים למילדות העבריות כו', דהנה ידוע שהכלים הן האותיות<sup data-n=\"1054\">72</sup> כמו עד\"מ האהבה בלב האדם הרי היא פשוטה ותקועה בלב וכאשר יהרהר ויחשוב אותה התשוקה ו[ה]אהבה במחשבתו הנה נמשך [אור] האהבה הפשוט ונתחלק לחלקי' רבים דהיינו לכמה מיני המשכות רבות באותיות המח' בכמה מיני אופנים שונים כו'. ונמצא שזהו כמו שנעשו בחי' כלים רבים לאור האהבה שהיתה תחלה פשוטה בלב, והרי ענין הכלים וענין האותיות הכל אחד כי פי' אותיות ידוע מלשון אתא בקר<sup data-n=\"1055\">73</sup> כו' דהיינו שבא אור הפשוט ונעלם לידי גילוי והיינו<sup data-n=\"1056\">74</sup> אותיות המח' כנ\"ל וה\"ז ג\"כ בחי' הכלים, והכלל לשניהם אינו אלא שמחלקים [את] האור לחלקים רבים ומיני המשכות והתפשטות רבות בכמה מיני אופנים כו' וד\"ל. והנה מוכרח לומר שיש איזה כח במקור המדות שיוכל להוציא מן בחי' ההעלם לידי גילוי, דהיינו המשכות והתהוות בחי' האותיות מן המדות במח' וכדומה, דמצד עצמו לא הי' האור מתפשט ונחלק לחלקים כו'. וזהו הנק' בשם מילדות העבריות כו', פי' העבריות הן הן הויות האותיות מן ההעלם לגילוי ונק' בשם ולד כדוגמת הולד הגשמי כשנולד שהוא בא מן ההעלם לגילוי, והמילדות את העבריות היינו כחות המולידים וממשיכים את האותיות שיבואו מן ההעלם לידי בחי' גילוי כנ\"ל, והוא כח המקשר את המדות לבוא לידי אותיות, והיינו בחי' השרש והמקור להתהוות בחי' הכלים למעלה להיות בחי' התיקון דציור אדם [ב]בחי' <span data-k=\"pg\">72</span> ּ יושר הנ\"ל וד\"ל. והנה מבואר למעלה דבזמן הגלות אין<sup data-n=\"e16\">טז</sup> החיצוני' חפצים כלל בבחי' התיקון בריבוי הכלים שהן האותיות כו', ע\"כ צוה מלך מצרים הוא בחי' פרעה העליון כנ\"ל למילדות העבריות דהיינו אותם שרשים עליונים המילדות את המשכות האותיות והכלים שכל הבן הילוד ימיתו כו' וד\"ל<sup data-n=\"e17\">יז</sup>.\n<b>וענין</b> שמות המיילדות אשר שם האחת שפרה כו', הנה ידוע מארז\"ל שפרה שהיא משפרת את הולד פועה<sup data-n=\"1057\">75</sup> שפועה עם<sup data-n=\"1058\">76</sup> הולד כו', והענין הוא דיש ב' ההי\"ן בשם הוי' ה\"א [ה]ראשונה וה\"א [ה]אחרונה [כו'] כידוע, ושפרה הוא בחי' ה\"א [ה]ראשונה וזהו שם הא' שפרה שם ה\"א [ה]ראשונה ושם השנית",[["1054","72","<b>שהכלים הן האותיות</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"א. שהיחוה\"א ספ\"ד. לקמן לב, א. הנסמן לשע\"ת לח, ב הערה 13."],["1055","73","<b>אותיות. . אתא בקר</b>: ישעי' כא, יב. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' יג. ענינים ריש ע' סו. לקמן שם. פ' בשלח קמ, ד. [ושם: ואתא]. קמח, א. מאמרי אדה\"א שמות ח\"א ע' קנח. וש\"נ."],["1056","74","<b>והיינו</b>: אדה: והמה."],["1057","75","<b>שפרה. . פועה</b>: סוטה יא, ב."],["1058","76","<b>שפועה עם</b>: א: שפועה (מדברת) עם. ד: שפועה ומדברת עם. ה: כבפנים. — ראה רש\"י סוטה שם. עה\"פ כאן (שמות א, טו).\n\n<b>טז</b>  <b>דבזמן הגלות אין</b>: שם: שאין.\n<b>יז</b>  <b>כו' וד\"ל</b>: שם: וכמו שי' לקמן בעזר\"ה."]]],[2300540344,"פועה שם ה'<sup data-n=\"1059\">77</sup> [ה]אחרונה כו' והיינו בחי' עלמין סתימין שהוא בחי' [ה\"א] ראשונה ובחי' עלמין דאתגליין<sup data-n=\"1060\">78</sup> שבה\"א אחרונה כו'. וביאור הדברים הנה פי' עלמין הרי הוא בחי' כלים ואותיות הנ\"ל מאחר שנק' בשם עולם שכלול מו\"ק מעלה ומטה כו', והרי הוא מוגבל כמו שהאותיות מוגבלים מן המדות כנ\"ל [וד\"ל]. ויש ב' מיני עלמין עלמין סתימין ועלמין דאתגליין דהיינו ב' מיני כלים ואותיות כו', הענין הוא כך דידוע דיש בחי' כלים באצי' עצמו ועד רום המעלות כו', ובדרך כלל הן בחי' ת' עלמין דכסופין שנק' ד' מאות שקל כסף<sup data-n=\"1061\">81</sup> עובר לסוחר כמ\"ש בזהר וע\"ח כו'. והענין הוא ע\"ד מארז\"ל עתיד הקב\"ה להנחיל<sup data-n=\"1062\">82</sup> לכל צדיק ש\"י עולמות<sup data-n=\"1063\">80</sup> שנא' להנחיל אוהבי יש<sup data-n=\"1064\">83</sup> כו'. פי' כי הנה באמת לית מח' תפיסא<sup data-n=\"1065\">84</sup> בי' בעצמו' אוא\"ס ב\"ה אפי' מח' דא\"ק כו', ולכך נק' בזהר בשם סדכ\"ס<sup data-n=\"1066\">85</sup> כו' וכידוע, והנה ידוע דבדבר חכ' שאינו מושג בשכל אין התפעלות העונג כלל מאותו [ה]דבר חכמה מאחר שאינו משיגו ותופסו במוחו [מ]מה יתענג הגם ש[י]הי' שכל וחכמה נפלאה כו'. וכמו\"כ למעלה בעצמות אוא\"ס שנק' סדכ\"ס כו' מאחר שאינו מתלבש בשום השגה ומח' כנ\"ל לא יוכלו כל העולמות להתענג ממנו<sup data-n=\"e18\">יח</sup> ולהיות נהנין מזיו ממש כו' מטעם משל הנ\"ל. אך מה שאנו רואים שנהנין הנשמות בג\"ע וכדומה הנה הוא בא מחמת שנמשך אותו הזיו שנהנין ממנו [ב]בחי' ירידה והמשכה מאוא\"ס ב\"ה להיות בבחי' השגה ותפיסא לנשמות דאבי\"ע עד שיהנו ממש כו', וזאת הירידה הוא הנק' בשם עלמין דכסופי' כו', פי' כמו בחי' העולם הגשמי שהוא כלול מו\"ק גשמיות ממעלה ומטה כו' ובחי' ממוצעי'<sup data-n=\"1067\">86</sup> כמו<sup data-n=\"e19\">יט</sup> מזרח ומערב כו', כמו\"כ ההמשכה מבחי' עונג העליון שנמשך להיות תענוג הנשמות והוא להיות בבחי' כלים המקבלים האור והזיו שהוא בבחי' גבול ממש בהשגותיהם כו' נק' בשם עלמין דכסופין שכבר הוא בא בבחי' עולם ממש בשביל גדר הגבלה ממש כו', דהיינו לכל צדיק וצדיק כפום שיעורא דילי' כן מתענג כו', והיינו ש\"י עולמות ש\"י מיני מדרגות התענוג וכל אחד נק' עולם מטעם שבא העונג לפי השגתו כנ\"ל. וזהו שיש לכאו\"א ש\"י עולמות, אך כפי הבירורים שבירר בעוה\"ז כן ערך אותן העולמות כו', כי שכר מצוה מצוה<sup data-n=\"1068\">87</sup> כו' כידוע, וכמ\"ש להנחיל",[["1059","77","<b>ושפרה. . ה\"א. . פועה. . ה'</b>: ראה גם מאמרי אדה\"ז הקצרים ע' כח. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' ריג. לקמן לג, א."],["1060","78","<b>עלמין סתימין. . דאתגליין</b>: ת\"ז בהקדמה (יז, א)."],["1061","81","<b>ד' מאות שקל כסף</b>: ח\"ש כג, טז."],["1062","82","<b>עתיד הקב\"ה להנחיל</b>: ראה עוקצי' ספ\"ג."],["1063","80","<b>ת' עלמין. . ש\"י עולמות</b>: ראה גם אוה\"ת כאן ע' ב'תתמה."],["1064","83","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1065","84","<b>לית מח' תפיסא</b>: ראה ת\"ז בהקדמה (יז, ב)."],["1066","85","<b>סדכ\"ס</b>: לשון הזהר בהקדמה ב, א. ועוד."],["1067","86","<b>ממוצעי'</b>: א: ממוצעת."],["1068","87","<b>שכר מצוה מצוה</b>: נסמן לעיל ז, ב הערה 316.\n\n<b>יח</b>  <b>ממנו</b>: שם ניתוסף: בבחי' תענוג מורגש.\n<b>יט</b>  <b>כו' ובחי' ממוצעי' כמו</b>: שם ליתא."]]],[2300540367,"אוהבי יש, לפי שבחי' עולם נק' יש שהוא יש ודבר מה בבחי' השגה כנ\"ל וד\"ל. ואמנם בכלל הן ת' עלמין דכסופין<sup data-n=\"1069\">79</sup> למעלה בבחי' אצי' למעלה מעלה עדיין מהשגות הנשמות אך שיורדין ונמשכי' למטה להאיר [ב]נשמות בבחי' מקיפים וזהו שנק' עובר לסוחר<sup data-n=\"1070\">88</sup> כו' וכמ\"ש במ\"א וד\"ל, וז\"ש דוד לחזות בנועם ה'<sup data-n=\"1071\">89</sup> ולבקר בהיכלו, פי' לחזות בבחי' השגה וראי' ממש וזה אינו אלא בבחי' עלמין דוקא כנ\"ל הנק' עולם דוקא וזהו לבקר בהיכלו בחי' היכל דוקא וד\"ל. וזהו שם הא' שפרה שמשפרת את הולד כו', פי' הן בחי' ת' עלמין דכסופין שעדיין הן למעלה בבחי' האצי' ממש <span data-k=\"pg\">לו</span> ּ ונק' עלמין סתימין דלא אתגליין עדיין למטה בנשמות אלא הן [ה]מקוריי' לבחי' הגילוי שבנשמות כו' והמה בחי' אורות עליונים מצוחצחות מאד כו' עד שהן בבחי' היופי והתפארת ונק' שפרה מלשון שופרא<sup data-n=\"1072\">90</sup>, והוא שמשפרת ומיפה את הולד דהיינו שממשכת ג\"כ בחי' ת\"ת [ה]עונג העליון אל הנשמות הנק' וולדות כדי לצחצח האור והשגה דנשמות [אח\"כ] בהתענג על ה' כו' וד\"ל, והוא בחי' שם ה\"א ראשונה דשם הוי'. אך שם ה\"א אחרונה דשם הוי' פועה שמדברת עם הולד כו' היינו בחי' עלמין דאתגליין שהן בחי' כלים היותר נמוכים כו', [ו]הוא כמו ענין ש\"י עולמות [שיש] לכל צדיק כנ\"ל לאחר שכבר נהנה מזיו בבחי' השגה כו' והיינו פועה שמדברת כו', כלומר שמביאתו לידי בחי' אותיות שבדבור הנק' עלמין דאתגליין כידוע והוא מבחי' שם ה\"א אחרונה הנק' עולם הדבור כו' וד\"ל.\n<b>אם</b> בן הוא והמתן אותו ואם בת היא וחיה כו', הנה פי' בן מלשון בנין<sup data-n=\"1073\">91</sup> כמ\"ש אמרתי עולם חסד יבנה<sup data-n=\"1074\">92</sup> כו', והענין הוא דכתיב זכר חסדו<sup data-n=\"1075\">93</sup> כו' שהחסד נק' זכר בחי' דכר ולא בחי' נוק' כי מטבע הזכר להשפיע חסדים וטבע הנקבה בבחי' גבורות כו' כידוע, ולכך נק' בחי' אור חסד עליון שממנו עיקר כל הבנין של העולמות בשם בן בחי' דכר, ועוד לפי שהוא לשון בנין כמ\"ש עולם חסד יבנה כו'. וידוע דהבנין הזה הוא בחי' ירידה גדולה עד שיתצמצמו האורות בכלים מכלים שונים למעלה באצי' ומשם ולמטה עד בנין העולמות הנפרדי' דבי\"ע כנ\"ל, ואמנם ירידה זו לצורך עלי' היתה כדי שיבוא ויומשך בחי' הביטול בנשמות ומלאכים כנ\"ל. והנה מבואר למעלה דאין",[["1069","79","<b>ת' עלמין דכסופין</b>: ראה זהר (תוספתא) ח\"ש קכג, ב. (אד\"ר) נשא קכח, ב. (אד\"ז) האזינו רפח, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'קכה. וראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קד. תו\"א וירא יד, ג."],["1070","88","<b>עובר לסוחר</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' פב (נוסחא שני'). ע' פה (נוסח א'). תו\"א וישלח כד, ג. מג\"א צח, ג. לקו\"ת אחרי כט, סע\"א ואילך. תו\"ח וישלח קפד, ב."],["1071","89","<b>לחזות בנועם ה'</b>: תהלים כז, ד."],["1072","90","<b>שופרא</b>: ברכות ה, ב. ראה גם אוה\"ת כאן ע' ב'תק."],["1073","91","<b>בן מלשון בנין</b>: ראה לקמן לד, ב. וש\"נ."],["1074","92","<b>אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["1075","93","<b>זכר חסדו</b>: תהלים צח, ג. ראה גם מדרש שמואל פ\"ב וזכרתני בזכרים. קול בוכים — קינת סתרים (לר\"א גלאנטי) איכה א, ז (זכרה ירושלים) זכרה הוא מלשון זכר (ע\"ש). שם, ט (לא זכרה). ע\"ח (שער מ\"ן ומ\"ד) של\"ט, דרוש י בהגהת צמח (א). תניא פמ\"ג (סב, א) ובלקוטי הגהות לשם. לקמן פ' וארא פד, סע\"ד. בא פח, א. פט, רע\"ג. משפטים רצו, ד."]]],[2300540388,"החיצונים חפצים כלל בבחי' התיקון דאדם שהוא בבחי' או\"פ דיושר כנ\"ל מטעם שלא יגיע [א]ליהם השפע [כלל] כנ\"ל, והרי בחי' בן דזכר חסדו [ה]נ\"ל הרי הוא ג\"כ בבחי' או\"פ דיושר לבוא בבחי' כלים רבים שמחמת זה הוא עיקר הבנין כמ\"ש עולם חסד יבנה כו' כידוע. וע\"כ ציוה פרעה למילדות הנ\"ל אם בן הוא מבחי' או\"פ דיושר כנ\"ל והמיתן אותו פי' שלא יולידו אותו לבא בבחי' עלמין סתימין ועלמין דאתגליין בבחי' כלים רבים כו', כי זהו נגד רצון החיצונים, אלא ימיתו אותו כלומר שיחזור אותו האור שנאצל בבחי' בן דאו\"פ כו' ויסתלק למקור חוצבו בתחלה ויוכלל בעצמות המאציל, והיינו כ[דוגמת] משל בחי' המיתה הגשמי' שהוא הסתלקו' החיות כו', שאז יוכלו גם הם לקבל יניקה מטעם הנ\"ל וד\"ל, משא\"כ בת וחי' לפי שהנוק' ה[י]א מבחי' הגבורות כנ\"ל שה[י]אכ עולה למעלה בבחי' או\"ח למקורו כו' היפך בחי' דכר שטבעו מן החסדי' היורדי' מגבוה לנמוך כו', ואז יוכללו האורות במאציל ע\"י בחי' הגבורות דאו\"ח ויקבלו גם הם יניקה משם כנ\"ל. וגם מטעם שע\"י<sup data-n=\"e20\">כ</sup> בחי' [הגבורות שהוא בחי'] הצמצוצי' הרבים עד שמתצמצם האור למטה מטה מאד גם בחיצוני' ואחוריי' דאחוריי' די\"ס דעשי' כו' שאז גם הם יוכלו לקבל משם קצת יניקה כנ\"ל ד[שם] יש להם ג\"כ קצת אחיזה מבחי' או\"פ דיושר שבבחי' הרגליי' כו' לפי שאינם מורדי' ממש דהא קרו לי' אלקא דאלקיי' כו' וכמ\"ש בלעם לא אוכל לעבור את פי הוי' כו' וד\"ל<sup data-n=\"e21\">כא</sup>.\n<b>ותיראן</b> המילדות את האלקים, פי' מפני דשם אלקי' הוא המצמצם את כח האלקי באבי\"ע להיות עי\"ז בחי' ירידת השפע אח\"כ מאין ליש בין באצי' בין למטה בבי\"ע כידוע, ולהיות כי עיקר המכוון בצמצום הזה אינו אלא שיהי' אח\"כ ירידת אור החסד <span data-k=\"pg\">74</span> ּ דהיינו להיות להקב\"ה דירה בתחתונים דוקא, והוא ענין המשכות האורו' בכלים מכלים שונים (וכמ\"שכב ביום עשות ה' אלקי'<sup data-n=\"1076\">97</sup> ארץ, אלקים דוקא [כו'] וכמ\"ש במ\"א)<sup data-n=\"e22\">כב</sup>, ואין הצמצום [ענין צמצום] ממש אלא רק כדי שיהי' דוקא המשכות [ה]אורות בכלים אח\"כ, ע\"כ ותיראן המילדות מש' אלקי' הזה המצמצם [כו'] ולא עשו כדבר פרעה להמית את הבן [כנ\"ל] לפי שהוא היפך כוונת אלקי' [זה] כו' וד\"ל.",[["1076","97","<b>ביום עשות ה' אלקי'</b>: בראשית ב, ד. ראה גם לקמן ל, ב (ובהנסמן שם). לה, א.\n\n<b>כ</b>  <b>שה[י]א. . מטעם שע\"י</b>: שם: וידוע שהצמצומים באין ממדת הגבורה שזהו מדת גבורתו ית' להעלים ולהסתיר את האור שלא יתגלה כ\"כ וכמ\"ש בלק\"א ולכן ציוה להם אם בת היא וחי' כלומר אם השפע העוברת אליכם הוא מבחי' נוק' שהוא מבחי' גבורות תניחו אותה לירד למטה להתלבש בכלים דבי\"ע שאף שתתלבש בהן יוכלו גם החיצוני' לינק הימנה מטעם שע\"י בחי' הגבורות שהוא.\n<b>כא</b>  <b>וד\"ל</b>: שם: וכנ\"ל וד\"ל, ועיקר כוונת מלך מצרים הי' שיהי' מושל על ישראל והם יהיו אצלו בבחי' גלות לכך ציוה למיילדות כך כדי שלא תגיע השפע דחסד עליון לתוך הכלים דבי\"ע המה נש\"י רק מבחי' מדת הגבורה שלמעלה בלבד שאז יכולים ג\"כ לינק הימנה אבל כשתגיע השפע מחסד עליון לישראל שמתפשטי' בבחי' הרחבה וגדלות בתוך הכלים דנש\"י בלבד והם אינן יכולים לינק הימנה כלל אז יהיו נגאלים כו' וד\"ל.\n<b>כב</b>  <b>(וכמ\"ש. . במ\"א)</b>: שם ליתא."]]],[2300540408,"[ד] <b>ויצו</b> פרעה<sup data-n=\"1077\">98</sup> כו' כל הבן הילוד היאורה תשליכוהו כו', פי' פרעה העליון התחכם לבטל יראת המילדות את שם [ה]אלקי' כנ\"ל וציוה להשליך היאורה כו'. דהנה היאורה היינו הנילוס שהוא א' מד' הנהרות שיוצאות מעדן והוא נהר פרת כידוע, והנה ידוע פי' ונהר יוצא מעדן<sup data-n=\"1078\">103</sup> כו' שהוא ענין ראש ושרש כל ההשתלשלו' אוב\"כ<sup data-n=\"1079\">104</sup> והוא מבחי' אבא שרש כל האצי'<sup data-n=\"1080\">105</sup> שנק' בשם עדן כאשר בחי' עונג העליון הנק' עתיקא מאיר בו וממשיך השפע לבינה הנק' נהר<sup data-n=\"1081\">106</sup> כו', ומשם יפרד והי' לד' ראשים [כו'] היינו בחי' התחלקות הכלים פרטים יותר למטה לד' נהרות כו'. אך כל בחי' הד' נהרות עדיין הם אחוזים וקשורים בבחי' עדן העליון ואע\"פ שנא' ומשם יפרד כו' אינו פירוד ממש כו', וז\"שכג בכאו\"א שם האחד<sup data-n=\"1082\">107</sup>, פי' שם האחד הוא א' האמיתי הכללי שבבחי' עדן העליון והוא הוא [עצמו] כי בהשוואה א' כולם משתוים ונכללים באחד כו' ולכך על כאו\"א נא' שם האחד שאינו אלא אחד אע\"פ שהם ד' כו', וא\"כ גם הנילוס שהוא פישון שנא' בו שם הא' פישון כו' עדיין הוא אחוז וקשור בבחי' עדן העליון שיצא משם [וד\"ל], וע\"כ ציוה<sup data-n=\"e23\">כג</sup> היאורה שהוא הנילוס תשליכוהו לבחי' הולד הנולד בבחי' או\"פ דיושר הנ\"ל כו', והיינו שיוכלל להיות בבחי' עיבור במעי אימא עילאה דאצי' הנק' נהר שי[ו]צא מעדן העליון כו' ויגיע ויבא ל[ידי] בחי' ביטול והתכללות בפנימי' או\"א כו' כי עובר ירך אמו הוא<sup data-n=\"1083\">108</sup> והוא להיות בבחי' שינה [ה]נ\"ל, ובזאת יהי' לפרעה ועמו תוס' יניקה הרבה מטעם הנ\"ל כי בבחי' פנימי' אימא הוא עולם החירות ונק' יובלא עילאה<sup data-n=\"1084\">109</sup> כו' כמ\"ש בזהר ששם נק' דרור וחירות לכל העבדים לצאת חפשי כו', פי'כד עבדים הן יו\"ד כתרי[ן] דנוגה<sup data-n=\"1085\">110</sup>, ובעולם החירות דפנימי' בינה גם העבדים יוצאי' לחירות ויכולים לקבל רב טוב כו'<sup data-n=\"e24\">כד</sup>, מפני שהוא למעלה מעלה מבחי' ההשתלשלו' האוב\"כ מכלים שונים כו' אלא כלול בהתכללות לפי שאינו בגדר התחלקות כנ\"ל ע\"כ כחשיכה כאורה כו', וגם החיצונים יכולים לקבל השפע וכידוע ע\"פ",[["1077","98","<b>ויצו פרעה</b>: שמות א, כב."],["1078","103","<b>ונהר יוצא מעדן</b>: בראשית ב, י. ראה גם לקמן לו, ג. וש\"נ."],["1079","104","<b>אוב\"כ</b>: אה: האורות בכלים."],["1080","105","<b>אבא שרש כל האצי'</b>: ראה ע\"ח (שער סדר אבי\"ע) שמ\"ז, פ\"ב."],["1081","106","<b>לבינה הנק' נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["1082","107","<b>שם האחד</b>: בראשית ב, יא. ראה לקמן לה, ב."],["1083","108","<b>עובר ירך אמו הוא</b>: גיטין כג, ב."],["1084","109","<b>אימא. . החירות ונק' יובלא עילאה</b>: ראה זהר תצוה קפג, א. מאורי אור מערכת דרור יג. הנסמן במאמרי אדה\"א נ\"ך ע' שסד."],["1085","110","<b>עבדים הן יו\"ד כתרי[ן] דנוגה</b>: ראה זהר וישלח קסו, ב.\n\n<b>כג</b>  <b>וז\"ש. . וע\"כ ציוה</b>: שם: והנה כתיב שם האחד פישון והוא הנילוס כדפירש\"י ופי' שם האחד שהוא קשור בבחי' אחד האמיתי הכללי שבעדן העליון הנמשך לתוך הנהר היוצא ממנו הוא בחי' בינה טרם שמתחלק לד' נהרות כו' וע\"כ ציוה פרעה.\n<b>כד</b>  <b>פי'. . טוב כו'</b>: שם: (פי'. . טוב כו')."]]],[2300540428,"זכרנו את הדגה כו' במצרים חנם חנם בלא מצות<sup data-n=\"1086\">111</sup>, פי' לפי שאין המצו[ת] יכולין להעלות מ\"נ לשם ולא העבירות פוגמי' כמ\"ש אם צדקת מה תתן לו<sup data-n=\"1087\">112</sup> כו', והוא מפני עוצם בחי' הרוממות וההתנשאות בבחי' עצ[מות] אור המאציל כו' וד\"ל. והוא למעלה מעלה מבחי' שם אלקי' הנ\"ל המצמצם בשביל דירה בתחתונים כו' (אלאכה כמו שהוא בשבת שנא' ויכל אלקים<sup data-n=\"1088\">113</sup> שנכלל שם אלקי' זה למעלה ממנו דהיינו בבחי' עדן העליון העצ[מי] שרש הנהרות ששם עולם החירות כו')<sup data-n=\"e25\">כה</sup>, ולכך ציוה היאורה הזה תשליכוהו כו' ואזכו לא תיראנה המילדות את האלקי' כי הוא במדרגה [ש]למעלה משם האלקי' המצמצם כנ\"ל<sup data-n=\"e26\">כו</sup> וד\"ל.\n<b>אך</b> מה עשה הקב\"ה כדי להוציא את בנ\"י מפרעה ע\"י מושיע שא\"א להיות מחמת גזירת פרעה מבחי' ב\"ן דבחי' או\"פ דיושר כנ\"ל עשה חסד בלידת משה כו' וע\"י סיבת בת פרעה שתרד לרחוץ<sup data-n=\"1089\">114</sup> על היאור כו', ותקחנו ל[ה] לבן כו', דהנה שרש נשמת משה הי' מלמעלה <span data-k=\"pg\">לז</span> ּ מעלה מבחי' כל ההשתלשלו' דנהר שיוצא מעדן<sup data-n=\"e27\">כז</sup> כו', דהיינו שהי' מבחי' מזל ונוצר אותיות צנור<sup data-n=\"1090\">115</sup> ואותיות רצון<sup data-n=\"1091\">116</sup> כו' דבי' אחיד אבא ותליא<sup data-n=\"1092\">117</sup> שהוא בבחי' מזלא דא\"א שהוא מזל הח' כו', וז\"ש עליו כי מן המים משיתיהו<sup data-n=\"1093\">118</sup>, פי' מים הוא בחי' חסד עליון דנוצר חסד הנ\"ל כי מקוה המים הנ\"ל<sup data-n=\"1094\">119</sup> היינו<sup data-n=\"e28\">כח</sup> בחי' הכלי שמקבל את המים ומגביל אותן כו', אבל בחי' המים עצמן הן [ב]בלתי הגבלה כלל וכמו שאין למים שום גוון<sup data-n=\"1095\">120</sup> אלא היולי כו' להורות על בחי' פשיטותו שהוא פשוט בתכלית כו'. וכמו\"כ בבחי' מים העליונים שלמעלה עדיין מבחי' ההשתלשלו' כשיוצא לנהר דבינה כו' נק' בשם מים עצמ[ן] והוא בחי' [מזל] דונוצר כו' שהוא נגד ועובר על פשע<sup data-n=\"1096\">121</sup> כידוע שיכולין הכל לקבל יניקה גם מי שאינו ראוי כמ\"ש אם רבו פשעיך מה תעשה<sup data-n=\"1097\">122</sup> כו' כי הוא<sup data-n=\"e29\">כט</sup> עובר על פשע כו' מטעם שיש שם<sup data-n=\"e30\">ל</sup> מבחי' הארת עצמות המאציל והוא הנק' עדן עילאה",[["1086","111","<b>זכרנו את הדגה. . חנם בלא מצות</b>: בהעלותך יא, ה ובספרי שם. ראה ד\"ה אני חומה בשלח תקס\"ה נדפס בתוס' הגהות וכו' באוה\"ת שה\"ש (כרך ב) ע' תשנ־ (כרך ג) ע' א'ד [בשם הה\"מ. וכ\"ה גם בלקו\"ת ואתחנן ג, ג. אוה\"ת ואתחנן ע' ס]. לקמן לה, ג. מאמרי אדה\"א שמות ח\"א ע' קכט."],["1087","112","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["1088","113","<b>ויכל אלקים</b>: בראשית ב, ב."],["1089","114","<b>בת פרעה שתרד לרחוץ</b>: שמות ב, ה ואילך."],["1090","115","<b>מזל ונוצר אותיות צנור</b>: נסמן לעיל יב, ב הערה 544."],["1091","116","<b>ונוצר אותיות. . רצון</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'כו. וש\"נ."],["1092","117","<b>דבי' אחיד אבא ותליא</b>: ראה זהר במדבר קיח, ב. ע\"ח (שער או\"א) שי\"ד, פ\"א."],["1093","118","<b>כי מן המים משיתיהו</b>: שמות ב, י."],["1094","119","<b>הנ\"ל</b>: אדה: ליתא."],["1095","120","<b>שאין למים שום גוון</b>: ראה פרדס (שער עצמות וכלים) ש\"ד, פ\"ד."],["1096","121","<b>[מזל] דונוצר. . ועובר על פשע</b>: מיכה ז, יח. ראה גם אוה\"ת שמות כרך ז ס\"ע ב'תקט ואילך. כרך ח ע' ב'תתמז."],["1097","122","<b>אם רבו פשעיך מה תעשה</b>: איוב לה, ו [ושם: אם. . ורבו — ראה מאמרי אדה\"א שמות ח\"ב ע' תרסח. נ\"ך ע' רנב].\n\n<b>כה</b>  <b>(אלא. . החירות כו')</b>: שם ליתא.\n<b>כו</b>  <b>ואז. . כנ\"ל</b>: שם: (ואז. . כנ\"ל).\n<b>כז</b>  <b>מעדן</b>: שם: מן העדן.\n<b>כח</b>  <b>הנ\"ל היינו</b>: שם: הוא.\n<b>כט</b>  <b>כי הוא</b>: שם: והיינו לפי שהוא.\n<b>ל</b>  <b>שיש שם</b>: שם: שרשם."]]],[2300540448,"כו' [וד\"ל]. ולכך כשירדה בת פרעה העליון לרחוץ על היאור דנילוס הגם שהכירה בו שהוא מילדי העברים עכ\"ז נאמר ויהי לה לבן כו', פי' שנשמת משה הי' יכול להיות גם לבת פרעה לבחי' בן הנ\"ללא דהיינו בבחי' או\"פ דיושר שהוא ענין זכר חסדו בבחי' בנין וירידת האוב\"כ כו' מפני<sup data-n=\"e31\">לא</sup> שממנ[ו] יכולים הכל לקבל גם בת פרעה ע\"כ ויהי [גם] לה לבן כו' מאחר שהוא למעלה מעלה מכל ההשתלשלו'<sup data-n=\"e32\">לב</sup> אשר שם כחשיכה כאורה כנ\"ל<sup data-n=\"e33\">לג</sup> וד\"ל. ולכך נא' ויגדל משה<sup data-n=\"1098\">123</sup> [כו'] שגדלוהו אע\"פ שידע[ו] בו שהוא מילדי העברים לפי שלא חששו אליו מפני שאמרו שגם הם יכולים<sup data-n=\"1099\">124</sup> לקבל יניקה ממנו מצד שרש נשמתו כנ\"ל וד\"ל. וז\"ש משה כי כבד פה אנכי<sup data-n=\"1100\">125</sup> כו', פי' מפני שהי' שרש נשמתו למעלה מעלה מבחי' הכלים ומבחי' ההשתל' לגמרי כנ\"ל ע\"כ לא הי' לו בחי' כלי הדבור בפה כו', עד\"מ אדם שעמוקה מחשבת שכלו מאד ואי[נו] יכול להסביר אותו בדבור בפה לתלמידו כו' הרי זה מפני שלא יכיל בחי' כלי הדבור כלל את עומק השכל ההוא והיינו מפני שהוא למעלה מבחי' הכלי כו' לכך אינו יכול להוציא [מחשבתו מבחי' ההעלם לגילוי אור כו', כך נשמת משה מפני שהי' שרש נשמתו למעלה מבחי' הכלי כנ\"ל ע\"כ לא הי' יכול להוציא] כל מח[שבתו] להביא[ה] בבחי' כלי הדבור בפה מן ההעלם לגילוי [שה]דבור הוא הנק' עלמ[א] דאתגליי[א] כידוע, וז\"ש כבד פה אנכי מפני שהי' למעלה מבחי' פה העליון בחי' עלמ[א] דאתגליי[א] הנק' פה ודיבור כידוע וד\"ל. ומ\"ש עוד ותצפנהו שלשה ירחים כו' ותקח לו<sup data-n=\"1101\">126</sup> תיבת גומא כו', הנה מבואר בלק\"ת<sup data-n=\"1102\">127</sup> שזמן בחי' הסתר עליון דעלמ[א] דאתכסיי[א] שהוא שלשה ירחים כו', והטעם להסתר זה הי' מפני שראתה כי טוב הוא<sup data-n=\"1103\">128</sup> מבחי' טוב העליון דבחי' מזל ונוצר חסד כנ\"ל ולכך הוא בטי\"ת רבתי כו' ואח\"כ ותקח לו תיבת גומא כו' הכל לבחי' מכסה ולמסתור המעלים את האור כי טוב כו' [וד\"ל]. ותשם בסוף<sup data-n=\"1104\">129</sup> על שפת",[["1098","123","<b>ויגדל משה</b>: שמות ב, יא."],["1099","124","<b>שגם הם יכולים</b>: אדה: שיכולים גם הם."],["1100","125","<b>כי כבד פה אנכי</b>: שמות ד, י [בדילוג]."],["1101","126","<b>ותצפנהו. . ותקח לו</b>: שמות ב, ב. ג."],["1102","127","<b>בלקו\"ת</b>: ראה גם רמ\"ז לזהר (שמות יא, ב) עה\"פ. הדרת מלך סק\"כ."],["1103","128","<b>כי טוב הוא. . בטי\"ת רבתי</b>: נסמן לקמן מג, ד הערה 48."],["1104","129","<b>ותשם בסוף</b>: סיום הכתוב ותקח לו.\n\n<b>לא</b>  <b>הנ\"ל. . כו' מפני</b>: שם: מפני שהיו סבורים המצרי'.\n<b>לב</b>  <b>למעלה. . ההשתלשלו'</b>: שם: מבחי' המקיפי' שלמעלה מעלה מהשתלשלו' דא\"פ.\n<b>לג</b>  <b>כנ\"ל</b>: שם: וכנ\"ל שמעמד הקליפות אחוריהם אל המקיף כו'."]]],[2300540468,"היאור כו' בבחי' סכ\"ד הנק' סוף כי נעוץ תחב\"ס<sup data-n=\"1105\">131</sup> כו' וד\"ל<sup data-n=\"e34\">לד</sup>.",[["1105","131","<b>נעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז.\n\n<b>לד</b>  <b>וד\"ל</b>: שם ניתוסף: אך באמת טעו בזה פרעה והמצרים כי אע\"פ ששרשו של משה מבחי' המקיפי' שלמעלה מהשתלשלות מ\"מ הוא נמשך מבחי' המקיפי' להאיר בתוך הא\"פ כמ\"ש מן המים משיתיהו שנמשך משם להאיר העולם וכמשי\"ת לקמן ע\"פ מי שם פה לאדם כו'. וכיון שהמקיף מאיר דרך הפנימי אזי אין החיצוני' יכולי' לינק ממנו כמו שאין יכולין לינק מן הא\"פ (וע' מ\"ש בסידור ע\"פ מאמר עבדים היינו לפרעה במצרים ויוציאנו ה' אלקינו או\"א שהלבישו לזרועות דא\"א ויתבאר משם ענין זה). ולכן לא יוכלו לקבל יניקה ממשה כלל ואדרבה על ידם הי' עיקר מפלתם כי על ידו האיר ה' מבחי' שלמעלה מהשתלשלות שהוא למעלה מטבע ועשה נסי' ונפלאות בעשר מכות שהביא על המצרי' כי אע\"פ שההארה מבחי' שלמעלה מהשתלשלו' כיון שמאיר דרך הא\"פ וההשתלשלו' אין לחיצוני' יניקה ממנו ואדרבה דוחה אותם ומושיע לישראל וכנ\"ל וד\"ל."]]],[2300540046,"<b>פ' שמות תקפ\"ד בבא[ב]רוסק</b>\n<span data-k=\"pg\">76</span> ּ<b>ויאמר</b> מלך מצרים למילדות העבריות<sup data-n=\"1106\">1</sup> אשר שם האחת שפרה כו' עד אם בן הוא והמתן אותו כו' ותיראנה המילדות את האלקים כו' עד סוף הפרשה כל הבן הילוד<sup data-n=\"1107\">3</sup> היאורה תשליכוהו כו', הנה להבין כל סדר פרשה זו וגם ענין פרשה הסמוכה לזאת במה שמספר בלידת משה ותרד בת פרעה<sup data-n=\"1108\">4</sup> לרחוץ על היאור כו' ותקח אותו<sup data-n=\"1109\">5</sup> ויהי לה לבן ותקרא את<sup data-n=\"1110\">6</sup> שמו משה כי מן כו'. הנה תחלה יש להבין<sup data-n=\"1111\">7</sup> בשורש ענין בחי' עיגולים ויושר בכללות שהוא בחי' או\"מ ואו\"פ ונק'<sup data-n=\"1112\">8</sup> או\"י ואו\"ח דהיינו מקיף דאו\"י ומקיף דאו\"ח<sup data-n=\"1113\">9</sup> כו'. וידוע המשל בזה מציור אדם שהוא הנק' בחי' יושר כו', והענין הוא להיות שאנו רואים בנה\"א<sup data-n=\"1114\">10</sup> אע\"פ שהוא אור עצם [א'] פשוט ונק' נפש כללי', הנה [היא] באה בהתחלקות לחלקים רבים בפרטי פרטיות כחות שונות זה מזה בטבעם ומזגם, שאין זה נמצא בעצם הנפש חלקים רבים מיוחדי' ונפרדי' במהות ומציאות זה מזה. והוא במה שאנו רואים בהארת אור שפע הרוחני' של הנפש כאשר מתפשט[ת] באברי הגוף הרי מתפשטת בחלקים רבים של כלי האברים הפרטים בכ\"א באופן משונה מזולתו, כמו אור שפע כח הרוחניו' דראי' בכלי העין ושפע חוש כח השמיעה בכלי האוזן וכלי הריח בכלי החוטם וכה\"ג בכלי היד מתפשט כח התנועה למלאכה וברגל להילוך כו', שכל אלה וכה\"ג הן כחות רוחניי' מחולקי' ומופרדי' זה מזה בתכלית במהותם ומציאותם, שבודאי אינו דומה חוש השמיעה לחוש הראי' כלל וההילוך ברגל ותנועה בידים גם הם",[["1106","1","<b>ויאמר מלך מצרים למילדות העבריות</b>: מאמר זה הוא מיוסד על מאמר ד\"ה זה שנדפס לעיל לפנ\"ז. ועיין בהנרשם בריש המאמר שם. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["1107","3","<b>ותיראנה. . כל הבן הילוד</b>: שמות שם יז [ושם: ותיראן — וכ\"ה לקמן לד, ד]. כב."],["1108","4","<b>ותרד בת פרעה</b>: שם ב, ה."],["1109","5","<b>ותקח אותו</b>: גח: עד."],["1110","6","<b>ויהי לה לבן. . את </b>[גח: ליתא]: שמות ב, י [בדילוג]."],["1111","7","<b>להבין</b>: גח: להקדים."],["1112","8","<b>או\"מ ואו\"פ ונק'</b>: ג: אור פנימי ואור מקיף. כה: כבפנים."],["1113","9","<b>דאו\"י ומקיף דאו\"ח</b>: גח: דאו\"ח ומקיף דאו\"י."],["1114","10","<b>בנה\"א</b>: שם: בנפש האדם."]]],[2300540084,"מובדלים זה מזה כו', עד שכל כח וכח של כל אבר ואבר שבציור ניתוח האדם מראשו לרגלו הכל הן באים בהתחלקות שונות זה מזה כל אחד ואחד מובדל במהות ומציאות בפ\"ע לפעול כל א' כח פעולתו המיוחדת לו דוקא. ואף גם בכחות הכללים שכוללים כל פרטי ההתחלקות של כחות האברים החיצונים ופנימי' שהוא בחי' המוחי' חב\"ד שבראש כידוע, הרי גם הם נחלקים לג' חלקים בג' חדרים מיוחדים שנק' ג' חללי גלגלתא<sup data-n=\"1115\">11</sup> כו', מוח החכמה והוא כח המשכיל כל שכל כו' והוא הנק' מוח הזכרון<sup data-n=\"1116\">12</sup> בחדר מיוחד והוא בטבעו קר ולח<sup data-n=\"1117\">13</sup> כו', ומוח הבינה בחדר מיוחד והוא כח ההשגה להשיג ולהבין כל שכל וסברא שנק' תפיסא כו' והוא בטבעו חם ויבש<sup data-n=\"1118\">14</sup> כו', ומוח הדעת לצד האחוריים דעורף כלול מאמצעות שניהם בחדר מיוחד כו', ומבחי' מוח הדעת מתפשט ע[ו]ד לכח המח' וממח' למדות שבלב כו'. וכמו\"כ מתפשט מחו\"ב לעינים ואזנים בראי' ושמיעה כו', כידוע דראי' נמשך ממוח החכמה<sup data-n=\"1119\">15</sup> ושמיעה ממוח הבינה<sup data-n=\"1120\">16</sup> כו', ועד\"ז מתחלק גם בחיצוני' האברים כולם כו'. והנה בודאי א\"א לומר שכמו כל דמות ציור ניתוח האברים בכחות פרטים הנמצאים בהם כנ\"ל יש ג\"כ במהות ועצמות הנפש הרוחני' כמו שהיא בטרם התלבשותה בחומר גופני בהתחלקות כזאת ממש, שהרי הנפש עצמ[ה] ה[י]א רוחני' ממש וכל דבר רוחני ממש א\"א לומר בו התחלקות לחלקים ממש כמו ציור התחלקות ניתוח אברי הגוף, כידוע דכל רוחני לא יתחלק אלא כולו כלול בבחי' עצם א' פשוט. והגם שבודאי גם זה א\"א לומר שאין כל מיני כחות הללו הנמצאים באברי הגוף נמצאים כלל בעצם הנפש הרוחני' להיותה בחי' עצם [א'] פשוט לגמרי כו', דא\"כ מהיכן נמצא מציא[ות] כחות הללו [כ]ראי' ושמיעה והילוך וכה\"ג באברי' שבגוף, שהרי ודאי מאור שפע רוחני' שנשפע <span data-k=\"pg\">לח</span> ּ מן הנפש הן באים כי גם הן רוחני' שנמשכי' מרוחניות הנפש, כידוע שהרגשת כאב באיזה אבר הרי הנפש מרגיש ותתפעל כו'. אלא צ\"ל דודאי יש מציאת כחות הללו כולן בעצם הנפש ממש כראי' ושמיעה וגם דיבור והילוך וכה\"ג בכל פרטי הכחות הנמצאים באברים (כמו שאמר ששמע ב' רוחות מספרות זע\"ז<sup data-n=\"1121\">17</sup> כו', וכמו במלאכים שא' וקרא זה אל זה<sup data-n=\"1122\">18</sup> כו', שנק' רוח ממללא<sup data-n=\"1123\">19</sup> כו' וכה\"ג בפרטי הכחות כהילוך כמו ילכו מחיל<sup data-n=\"1124\">20</sup> כו' שהרי מלאכים אומרים שירה<sup data-n=\"1125\">21</sup> ומתפעלים במדות אהוי\"ר כו' ובכלי השגה דבינה וכן הנשמות נהנין<sup data-n=\"1126\">22</sup> בהשגה כו' וד\"ל), רק שבעצמות הנפש הרי כל הכחות שבה כלולים בתכלית ההתכללות בלתי ניכר[ת] במציא[ו]ת מובדלת הימנה כלל וכלל. וע\"כ ממילא מובן שאין בהם [בחי'] התחלקות לחלקים כאו\"א בפ\"ע כלל אלא כלולים כאחת ממש, רק בבואן לכלי הגוף הן באים שם בבחי'",[["1115","11","<b>ג' חללי גלגלתא</b>: נסמן לעיל כג, ד הערה 9."],["1116","12","<b>מוח החכמה. . הזכרון</b>: נסמן לעיל שם הערה 10."],["1117","13","<b>מוח החכמה. . קר ולח</b>: ראה גם מאמרי אדה\"א בראשית ע' תעא-ב. הנחות תקע\"ז ע' קמז ובהנסמן בהנ\"ל. שע\"ת לח, ג. לקמן לקמן פ' בא קא, ג. קד, א. בשלח קפז, ב. רי, ב. יתרו רסז, ג. תצוה שנג, א. שעז, רע\"ג. פקודי תנט, ב."],["1118","14","<b>ומוח הבינה. . חם ויבש</b>: נסמן בהערה שלפנ\"ז."],["1119","15","<b>דראי' נמשך ממוח החכמה</b>: ראה פרדס (שער ערה\"כ) שכ\"ג מערכת ראי'. מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרמז. מאמרי אדה\"א ויקרא ח\"ב ע' תעא. הנחות תקע\"ז ע' כז ובהנסמן בהנ\"ל. ש\"א מ, א. לקמן פ' וארא פד, ד. בא קב, א. בשלח רל, א."],["1120","16","<b>ושמיעה ממוח הבינה</b>: ראה זהר (אד\"ר) נשא קלח, ב. מאמרי אדה\"א הנחות תקע\"ז שם. וש\"נ. ש\"א שם. לקמן פ' וארא פה, א. בא קב, א. תצוה שמט, ג."],["1121","17","<b>ב' רוחות מספרות זע\"ז</b>: נסמן לקמן פ' בשלח קמד, ד."],["1122","18","<b>וקרא זה אל זה</b>: ישעי' ו, ג."],["1123","19","<b>רוח ממללא</b>: ת\"א לבראשית ב, ז."],["1124","20","<b>ילכו מחיל</b>: תהלים פד, ח."],["1125","21","<b>מלאכים אומרים שירה</b>: ראה שער האמונה מח, ב. מאמרי אדה\"א קונטרסים ס\"ע שעו ואילך. וש\"נ."],["1126","22","<b>הנשמות נהנין</b>: ראה ברכות יז, א."]]],[2300540122,"ההתחלקות בכל כלי לפי מזגו וטבעו ושם הן מחולקים ומופרדים זה מזה במהותם ומציאותם כנ\"ל, וזהו מצד בחי' הכלים והאברים דוקא. אבל מצד עצם מהותן הרוחני' כמו שהן קבועים בנפש הרוחני' ממש כלולים הן בנפש כולן כאחת ממש בלי שום התחלקות לחלקים פרטי' כלל (להיותם שם בערך מדריגת כח הרוחני' ממש שנבדל הרבה מערך כח חיות הגשמי בהיותן צורה לחומר כו' כמשי\"ת). וראי' לזה גם מכללות הכחות שכוללים כל כחות האברים הפרטיי' המסתעפי' מהן כו' שהן ג' מוחי' דחב\"ד המלובשים בג' חללי גלגלתא הנ\"ל, שהרי מה שהן נחלקים לג' מיני מוחי' מוח חכמה כו' זהו מפני שינוי מהות טבע הג' חדרים במוח ע\"כ נתחלק לג' חלקים [מ]אור השכל, א' במוח החכ' להשכיל כל שכל (שנק' התחכמות והבנה) להיות קר ולח כו' ע\"כ טבעו להוליד שכל כו', והב' מוח הבינה שהוא חם ויבש כו' ישכון בו חלק ב' מאור הנפש והוא כח ההשגה להשיגו ולתופסו כו', אבל טרם בא שפע זו מן הנפש בג' חדרים הללו דהיינו כמו שהוא בעצם הנפש ממש הרי עדיין לא נתחלק שם אור השכל לג' חלקי המדריגות דחב\"ד כלל, אלא הוא כח א' רוחני בלבד שנק' כח המשכיל ההיולי שהוא כח הרוחני' דחכ' שכלול בנפש וקבוע בה שהוא כח הפועל להשכיל כל השכלות וחכמ[ות] כו', ועדיין אינו בגדר חלקים דחו\"ב להיות במציאות הבנה והשגת שכל כלל, אלא רק הוא כח המשכיל כל שכל בכללות כו'. וע\"ש כח פעולה זאת נק' הנפש בשם נפש המשכלת<sup data-n=\"1127\">23</sup> בכלל כלומר שכחה להשכיל כל חכמה להיות נמשך בכמה מיני מדרגות שהן מתחלקים אח\"כ בג' חללים, והן בג' מוחין חב\"ד שכוללי' כל פרטי שכלי' בגילוי המציאות כו', וא\"כ הרי מובן עכ\"פ דמה שבא אור כח המשכיל שבנפש להתחלקות דג' חלקים דחב\"ד אינו אלא מצד הג' כלים דג' חללים דוקא, אבל לא מצ\"ע שהוא כח אחד פשוט ואינו מורכב בגדר חלקים כלל רק שכלול בו הכל כו' וד\"ל.\n[ב] <b>והנה</b> עד\"ז ממש יובן גם בציור הניתוח חלקי שארי כחות האברים המסתע[פים] מג' חללי' שבמוח שבראש הנ\"ל, כמו כח הראי' בעין וכח השמיעה באזן כו', שגם שבגוף הן בבחי' התחלקות במהות ומציאות כנ\"ל, אבל כמו שהן בנפש <span data-k=\"pg\">78</span> ּ הם כלולים בנפש כאחד ממש מבלי התחלקות ופירוד כלל. וכך בכללות כל מספר רמ\"ח כחות האברים הרי אינם באים בציור ניתוח גשמי רק מצד בחי' כלי האברים שעושין בחי' הבדלה והתחלקות בין כל כח וכח שהוא רק לפי מזג אותו האבר ולא יחובר [בכח] אבר זולתו כלל, אבל מצ\"ע הכחות הללו כמו שהן בנפש עצמ[ה] אינם בבחי' התחלקות במציאות ומהות בפ\"ע כלל",[["1127","23","<b>נפש המשכלת</b>: נסמן לעיל כד, א."]]],[2300540160,"וכלל, אלא הנפש היא כלולה מכל כחות האברים הרוחני' הללו בתכלית ההתכללות כולם כא' ממש בלי פירוד והתחלקות כלל מטעם הנ\"ל, שכל בחי' רוחני' לא יתחלק כלל אלא כולל הכל כו'<sup data-n=\"1128\">24</sup> וד\"ל (ומה שאנו מוצאים גם בנפש הרוחני' או מלאך רוחני בכח אחד מיוחד בפ\"ע כ[מו ב]מדות אוי\"ר בפרט ובהשגה דבינה לפ\"ע הכלי שלו [דוקא] כמו ובשתים יעופף<sup data-n=\"1129\">25</sup> כו', וכן וקרא זה אל זה וגם ילכו כמו בשתים יעופף וכתי' לא יסבו בלכתן<sup data-n=\"1130\">27</sup> כו'. הענין הוא משום דכלולים מצורה וחומר<sup data-n=\"1131\">28</sup> עכ\"פ רק שהחומר מעין הצורה<sup data-n=\"1132\">29</sup> כמ\"ש וקרסולי החיות שוק[י] החיות כו' בציור קומה שהרי נאמר ופני אדם לארבעתן<sup data-n=\"1133\">31</sup> כו'. וגם אם הם ב[בחי'] פני ארי' או שור ונשר כו', הרי אמר שש כנפיים לאחד<sup data-n=\"1134\">32</sup> בשתים יכסה פניו ובשתים יכסה רגליו וכתיב ורגליהם ישרות<sup data-n=\"1135\">33</sup> כו'. וכן בנשמות יש חומר לצורה בג\"ע<sup data-n=\"1136\">34</sup> שעי\"ז יבא האור הרוחני' בהתחלקות כחות פרטי' אם בציור אדם או בציור חי' ובהמה כמו ציור ניתוח אברי [ה]אדם ממש רק שהוא בבחי' הרוחני' יותר (ועכ\"ז הרי מה שנחלק הנפש לג' מדרגות חב\"ד הוא מצד הג' חללי' ולא מצ\"ע הנפש שנק' נפש השכליי' כנ\"ל, כך גם בנשמות ומלאכים הגם שהן בבחי' חומר [ו]צורה כנ\"ל מ\"מ כלולים בהם כל הכחות דמוחין ומדות וכל האברים יחד להיות[ם] בבחי' רוחני' כו').\n[ג] <b>והנה</b> המופת היותר אמיתי לענין הנ\"ל שאין צי[ו]ר התחלקות כחות בנפש עצמ[ה] הרוחני', שאם הי' בה ציור התחלקות הכחות ג\"כ איך היו שוכנים בה ב' הפכי' מנגדי' מאד כא', כמו כח הקרירות שהוא יסוד המים שמשכנו בכלי המוח עם כח החמימות שהוא יסוד האש שבלב שהן ב' הפכים ממש, או ממוצע שכלול מאש ומים שהוא הרוח<sup data-n=\"1137\">37</sup>, שהאש ומים הן מנגדים ממש ואיך יוסבל בנפש עצמ[ה]. דבשלמא בכלי הגוף יוכל להיות ב' הפכים דחו\"ג כאש ומים וממוצע דרוח כו' לפי שיש לכאו\"א כלי מיוחד בפ\"ע שישכון בו האור לבדו, וכמו כח הקרירות ביסוד המים ולחלוחי' שבכלי המוח שכלי המוח הוא כמו חומר לצורה זו וכלי הלב הוא כלי מיוחדת לכח החמימות כו'. וכך יש טבע מיוחד' לכל כלי ואבר שישכון בו אור וכח החיות הרוחני' שהוא אופן הצורה לפי אופן מזג טבע הכלי שהוא החומר כו', והרי האברים חלוקים במיני הרכבתם וגם רחוקים ונבדלים זמ\"ז במקומות מיוחדים כו'. אבל בנפש הרוחני' אין שם בחי' כלים ואברים מיוחדים כו' רק כחות רוחני' לבד א\"כ איך ישכנו בה ב' כחות הפכיי' מנגדיי' בתכלית יחדיו יהיו תמים",[["1128","24","<b>כו'</b>: גח: כא'."],["1129","25","<b>ובשתים יעופף</b>: ישעי' ו, ב."],["1130","27","<b>לא יסבו בלכתן</b>: יחזקאל א, יב. יז."],["1131","28","<b>דכלולים מצורה וחומר</b>: ראה תניא פ\"מ. שע\"ת ו, ב. מאמרי אדה\"א בראשית ע' קיב־ נ\"ך ע' שלה־ קונטרסים ע' רצב ובהנסמן בהנ\"ל."],["1132","29","<b>שהחומר מעין הצורה</b>: ראה גם מאמרי אדה\"א נ\"ך שם. וש\"נ."],["1133","31","<b>ופני אדם לארבעתן</b>: ראה יחזקאל א, י. מאמרי אדה\"ז תקע\"א ע' צג. מאמרי אדה\"א ויקרא ח\"א ע' ג. וש\"נ. שע\"ת יג, א ובהערה 6. לקמן קיג, ד. קיט, ד. רמט, סע\"ד ואילך. רפו, ד. שיא, ד. שטו, ג."],["1134","32","<b>שש כנפיים לאחד</b>: ישעי' ו, ב."],["1135","33","<b>ורגליהם ישרות</b>: יחזקאל א, ז [ושם: ורגליהם רגל ישרה — ראה שה\"א סד, א]."],["1136","34","<b>חומר לצורה בג\"ע</b>: ראה גם לעיל ז, ג. ח, א. לקמן פ' וארא סב, ג. וש\"נ."],["1137","37","<b>שכלול מאש ומים שהוא הרוח</b>: ראה זהר (רע\"מ) בא מג, ב. תצוה קפד, ב. תו\"ח בראשית לט, ד ובהערה 26. לקמן פ' ויקהל שצד, א."]]],[2300540197,"(ככח האהוי\"ר כח החסד וכח הדין יחדיו ישכנו, וכמו רצון של חסד ושכל המטה כלפי חסד שוכן יחד עם רצון ושכל של דין היפוכו בתכלית, ולא עוד אלא שכלולי' זע\"ז בתכלית כנ\"ל<sup data-n=\"1138\">38</sup>. אלא צ\"ל שכחות <span data-k=\"pg\">לט</span> ּ האברים כמו שהן בגוף שמורכבים בדם ובשר החומרי' אין להם ערך כלל וכלל לגבי מהו\"ע הנפש כמו שה[י]א עם כחותי' הכלולי' בה שהן ג\"כ רוחניות כמוה ממש, שהרי אור וכח החיות של כל האברים הגם שנק' רוחני' אבל הן [רק] רוחניו' שבגשמיות שנק' חיי בשר בכלל ואין ערוך לחיות הנפש המתפשט' להחיות האברים לגבי עצם רוחניות הנפש שא\"ז רק הארה וגילוי בעלמא, גם לא ככח התנועה שמניע בגילוי ביד כך יהי' גילוי אור החיות באברים שהרי כח התנועה בבחי' החי עצם א' הוא שהרי כל חי יש לו תנועה בעצם, גם לא כגילוי האור מן השמש שמחויב מציאותו בהכרח להיות שזיו זה ישנו בשמש בעצם מהותו ממש, והרי אם ילקה גוף היד לא יחסר כח התנועה בעצם החי להיותו כלול בעצם החי וכן הזיו ואור כלול בעצם המאור (וראי' מקיטע וסומא שמוליד שלם<sup data-n=\"1139\">40</sup> שכח השכל המוליד מוליד בדומה לעצם הנפש שכחותי' כלולי' בה בעצם אע\"פ שנחסר כח הראי' שבעין וכח התנועה שביד. וכן ראי' מן הגלגולים<sup data-n=\"1140\">42</sup> שהנפש עצמה עם כחותי' מתגלגלי' באבן ובהמה וחי' ולא נעשים בבחי' אדם כלל. ומה שהנפש עצמ[ה] תתפעל ממאורעות הגוף כמו ביסורי הגוף תתייסר הנפש בצער רוחני שבנפש ומתענוגי הגוף תתענג הנפש בעונג רוחני שבה, וכן מוכרח לומר שרצון ותענוג שבגוף גם כרצון שבהילוך בא ונמשך מרצון שבנפש עצמ[ה] וכן התפעלות אוי\"ר ומחדו\"מ, וא\"כ גם כחות של חיצוני' האברי' כולם הן באים מעצם הנפש כו'. הנה [כ\"ז הוא רק מצד התלבשות כחות הנפש באברי הגוף, אבל מצד מהותה עם כוחותי' הכלולים בה] אינם מתייחסי' ביחוס וערך סוג א' עם הכחות הגשמיי' כלל ונבדלים מהם לגמרי עד שלא תתפעל כלל [מהתפעלות מאורעות הגוף, שבודאי אא\"ל שאותה האהבה שבאה במורגש בלב בשר ישנה בנפש] באותו אופן ממש, וכן היראה ופחד כו', וכ\"ש ההילוך גשמי שברגל וראי' העין תראה הנפש ותלך כו', וגם השכל הרוחני שבמוח אין לו דמיון לעצם כח השכל כמו שכלול בנפש כו', וגם התפעלות התענוג והרצון שבגוף אין לו דמיון וערך להתפעלות התענוג ורצון שבעצם הנפש (ואעפ\"י שאנו רואים שמהתפעלות תענוג שבנפש נמשך התפעלות תענוג שבגוף כמו מבשורה טובה שיחי' רוחו ממש וכמו ותחי רוח יעקב ולהיפך [בשורה רעה כמו] בשרה שפרחה נפשה מרוב צער כו', וכן מפחד רוחני דנפש",[["1138","38","<b>כנ\"ל</b>: כנצ\"ל: כנ\"ל)."],["1139","40","<b>וסומא שמוליד שלם</b>: ראה גם לקמן פ' תצוה שכו, ג. מאמרי אדה\"א נ\"ך ע' תמב. וש\"נ."],["1140","42","<b>הגלגולים</b>: ראה גם מאמרי אדה\"א קונטרסים ס\"ע ה ואילך."]]],[2300540231,"יתפעל בפחד זה בלב גשמי כמו בחברי דניאל שנפחדו משום דמזלייהו חזי כו', וכמו תענוג רוחני שבנפש נמשך טפה רוחני' להוליד גוף בדומה לו כו' וככח צומח הרוחני ממש מצמיח עשב ותבואה גשמי' כו'. הנה כ\"ז הוא ג\"כ [רק] בחי' התלבשות בדילוג הערך מעצם הרוחני' שבנפש לבא מן ההעלם לגילוי שזהו כמו הנק' מאין ליש כו', וכמו שבצלם יתהלך איש<sup data-n=\"1141\">49</sup> דגידול המוחין חב\"ד ג\"כ בא מעצ[ם] הנפש שהוא מקיף דחי' [ויחידה] שזהו כמו צמיחה גשמיי' דעשב מכח הצומח הרוחני<sup data-n=\"1142\">50</sup> (אך עכ\"ז גם בנפש יש גדלות וקטנות כמו התינוק ששכלו ומדותיו קטנים גופו קטן וממילא גם נפשו הגם שכלולה מגדלות השכל ומדות אבל נק' נפש דקטנות עכ\"פ (כמו בחי' אנפי זוטרי<sup data-n=\"1143\">51</sup> למעלה שנק' נער כו'), א\"כ גם בנפש יש צמיחה מקטנות לגדלות ברוחני' שבה עצמ[ה] כמ\"ש בוצין בוצין<sup data-n=\"1144\">52</sup> כו' וע\"י צמיחת הנפש יצמח ממילא גם בחי' נר\"נ ע\"פ הגדלת הכלים דמוח ולב כו' (רק<sup data-n=\"1145\">53</sup> ע\"י גידול המוחין גשמיי' יבא יותר מן ההעלם לגילוי מצלם דנפש כו' שבנין הכלים קודם עד<sup data-n=\"1146\">54</sup> שגידול החומר ממשיך לגילוי הצורה בחומר, אבל גידול הצורה קודם כמו לפי שכלו<sup data-n=\"1147\">55</sup> כו' וז\"ש <span data-k=\"pg\">80</span> ּ אך בצלם<sup data-n=\"1148\">56</sup> כו', ונמצא בקטנות הנפש הגם שכלול בה כל מה שעתיד לגדל זהו בהעלם גדול ביותר, משא\"כ התכללות דכחות הנפש בעצ[מה] שהם בשלימות מציאותם רק שכלולים בעצם ואינם ניכרים במציאות בפ\"ע שהרי הנפש עצמ[ה] תתפעל בתענוג ורצון [ו]שכל כו'). וכ\"ז טעם ותירוץ לענין התכללות ב' כחות הפכיי' מנגדי' בעצ[ם] הנפש, משא\"כ בכחות המתפשטי' באברי הגוף שא\"א שישכון גם<sup data-n=\"1149\">57</sup> בהתכללו' אחד ב' כחות הפכיי' מנגדי' כחסד ודין אוי\"ר חדוה ומרירות יחד בלב אלא כל א' יש לו עת מיוחד בכלי הלב, וכן ב[ה]טבע של המוח בקרירות לא יסבול החמימות שבלב וכן להיפוך כו', והוא מצד התחלקות האברי' שבהן בא גילוי אור החיות בפירוד והתחלקות, אבל אין להם ערך ויחוס כלל לכחות הכלולי' בעצם הנפש לא מיני' כו' ע\"כ ישכנו בנפש ב' מנגדים ממש עד שלא ימצאו במציאו' מנגדים כלל מטעם כל הנ\"ל וד\"ל.\n[ד] <b>והדוגמא</b> מכ\"ז יובן למשכיל למעלה מאחר שבצלם אלקים<sup data-n=\"1150\">58</sup> עשה את האדם התחתון אע\"פ שאין לו גוף<sup data-n=\"1151\">59</sup> [ולא] כו' עכ\"ז אמר על הכסא דמות<sup data-n=\"1152\">60</sup> כמראה אדם כו', והוא כללות ע\"ס דאצי' שהן בציור אדם חב\"ד חג\"ת [נה\"י] כו' כידוע. וכללותם הראשון הוא בחי' הקו\"ח שהוא מקור כל או\"פ ומקיפים שבאים בהשתל' בב' בחי' דעיגולים ויושר כידוע. והנה",[["1141","49","<b>שבצלם יתהלך איש</b>: נסמן בהערה 56."],["1142","50","<b>הרוחני</b>: אוצ\"ל: הרוחני)."],["1143","51","<b>אנפי זוטרי</b>: ראה חגיגה יג, ב. הנסמן לקמן פ' משפטים רפז, ג."],["1144","52","<b>בוצין בוצין</b>: ברכות מח, א."],["1145","53","<b>(רק</b>: גח: רק. אויא: כבפנים."],["1146","54","<b>עד</b>: גדחט: ע\"י. אויא: כבפנים."],["1147","55","<b>לפי שכלו</b>: משלי יב, ח. ראה גם תו\"ח ח\"ש קכג, א ואילך."],["1148","56","<b>אך בצלם</b>: תהלים לט, ז."],["1149","57","<b>שישכון גם</b>: ג: שישכנו שם. ח: שישכנו."],["1150","58","<b>שבצלם אלקים</b>: נח טו, ו."],["1151","59","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל."],["1152","60","<b>על הכסא דמות</b>: יחזקאל א, כו [ושם ועל דמות — ראה מאמרי אדה\"ז תקע\"א ע' עז [ושם: ועל]. ע' צג. לקמן רמט, ד [ושם: על — בדילוג]. שיד, ד. תמג, א [ושם נדפס מגוכתי\"ק]. תמו, ד. תמז, א [כנ\"ל]. שע\"ת צב, ג. מאמרי אדה\"א קונטרסים ע' תקסה. וש\"נ]."]]],[2300540263,"בחי' אורות דע\"ס הבאים בכלים כמו חכ' מוחא<sup data-n=\"1153\">61</sup> חסד דרועא ימינא<sup data-n=\"1154\">62</sup> וכה\"ג, זהו כמו דמיון התפשטות הכחות של הנפש בכלים ואברי הגוף כנ\"ל, וכמ\"ש אי אנת תסתלק<sup data-n=\"1155\">63</sup> מנייהו אשתארו כגופא בלא נשמתא כו' (הגם שיש שרש להתהוות הכלים קודם לשרש התהוות האורות כנ\"ל) שמבואר למעלה שאין להם דמיון וערך כלל וכלל לגבי כחות הרוחני' הכלולים בעצ[ם] הנפש כו', כך אין ערוך כלל לאורות הנאצלים בכלים לגבי ע\"ס הגנוזות<sup data-n=\"1156\">64</sup> ונעלמות בעצמות המאציל ממש, לפי שאין זה רק בחי' התפשטו' ההארה וגילוי אור בעלמא מבחי' העלמם בעצמו' בדילוג ערך מאד כו', דהיינו שבעצמות המאציל אינם נק' בשם ע\"ס במציאות ומהות כמ\"ש ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"1157\">65</sup>, וכמו משל שלהבת הקשורה בהעלם בגחלת<sup data-n=\"1158\">66</sup> כו', כי כלולים בתכלית ההתכללות כנ\"ל בעצ[ם] הנפש שה[י]א רוחני שא\"א שיחולק לחלקים במציאות בפ\"ע כו'. וע\"כ מובן שאין שום התחלקות בע\"ס הגנוזות וכלולים בעצמות, כי [עצמות] א\"ס ב\"ה פשוט בתכלית וגם כחות דע\"ס כרצון ותענוג וחכמה ומדות כו' הכל כלולים במהו\"ע ית' בתכלית הפשיטות [ו]בלי התחלקות כלל כו', ומה שבא בגילוי אור חכמה בכלי המוח ונק' חכמה מוחא כו' אין לו ערך לגבי עצם כח החכ' שבעצמות ממש דע\"ז אמר לתבונתו אין מספר<sup data-n=\"1159\">67</sup> שא\"א שיבא בכלי ומדה ולא במציאות ומהות חכ' וכמ\"ש חכים ולא בחכ'<sup data-n=\"1160\">68</sup> ידיעא כלל כו', וכה\"ג בשאר הספי' ומדות אמר לאו דאית לך צדק ידיעא<sup data-n=\"1161\">69</sup> דאיהו דין כו' עד ולאו מכא\"מ כלל, ומטעם הנ\"ל כמשל כחות המתפשטי' בכלים שנק' מורכבים במציאות דבר מה לפי הגבלת הכלי כו', משא\"כ כחות הכלולים בעצ[ם] הנפש שבלתי מוגבלים כלל כנ\"ל<sup data-n=\"1162\">70</sup>. וע\"כ יכול להיות שם התכללו' מב' הפכיי' מנגדיים ממש כמו חו\"ג דיסוד המים שבמוח עם גבורה דאש כו', משא\"כ באורות וכחות שמלובשי' בכלים ואברים שבגוף כו'. <span data-k=\"pg\">מ</span> ּ וכך יובן ע\"ד דוגמא למעלה שכל אורות דע\"ס דאצי' בכלים הרי יש לכל אור כלי מיוחד בפ\"ע כמו בחי' החסד במוח דחכ' ובחי' הגבורה במוח בינה בלב כו' וא\"א שישכנו כא' חסד ודין כמו מים ואש יחד כו', משא\"כ טרם שבאו האורות דע\"ס בכלים רק כמו שהן כלולים בתכלית בעצ[מות] שם כלולים חו\"ג כו' ב' הפכים בתכלית כאלו אינם במציאות ב' הפכים כלל מטעם הנ\"ל וד\"ל.\n[ה] <b>וכך</b> הוא גם בכללות ההתחלקו' דג' חללי גלגלתא דחב\"ד הנ\"ל שכמו שהחכמה בעצ[מות] ממש אין שם בחי' התחלקות לג' אלה כלל (כמו שהנפש נק' נפש השכלית כנ\"ל),",[["1153","61","<b>חכ' מוחא</b>: זהר (רע\"מ) פינחס רלה, ב. ת\"ז בהקדמה (יז, א). ת\"ע (קכג, א)."],["1154","62","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה שם."],["1155","63","<b>אי אנת תסתלק</b>: ראה ת\"ז שם (יז, ב)."],["1156","64","<b>ע\"ס הגנוזות</b>: ראה פרדס (שער סדר האצילות) ש\"ה, פ\"ד. (שער הצחצחות) שי\"א. וראה שם פ\"ג. הנסמן במאמרי אדה\"א דברים ח\"א ע' שמו־ שעה\"י — לקו\"ב — קפט, ג-ד הערה 2."],["1157","65","<b>ע\"ס. . בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["1158","66","<b>שלהבת הקשורה. . בגחלת</b>: ס\"י שם, מ\"ז. ראה זהר אחרי ע, א. מאמרי אדה\"ז תקס\"ט ע' קצא."],["1159","67","<b>לתבונתו אין מספר</b>: תהלים קמז, ה."],["1160","68","<b>חכים ולא בחכ'</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה יז, ב."],["1161","69","<b>לאו דאית לך צדק ידיעא</b>: ראה ת\"ז שם."],["1162","70","<b>כנ\"ל</b>: גח: וד\"ל."]]],[2300540292,"דאין חכ' הכלולה בעצמות א\"ס רק בחי' כח ומקור כל שפע [ו]אור דחכ' כמו כח המשכיל שכלול בעצ[ם] הנפש כו' (ועכ\"ז הרי א' חכים כו' מבין ולא כו' וכמ\"ש לתבונתו כו' רק שכלולים כאחד ממש מראש לסוף מבלי שימצאו במציאות כלל כו'). ועד\"ז הוא עד רום המעלות גם בחב\"ד דא\"ק כו', ואע\"פ שאין שם בחי' כלים דחב\"ד כמו בז\"א מ\"מ שורש או\"כ דז\"א שם הוא<sup data-n=\"1163\">71</sup> כידוע דא\"ק נק' אדם דבריאה<sup data-n=\"1164\">72</sup> בכלל וז\"א נק' אדם דעשי' כו'. וכך הוא בכל פרטי האורות וכלים דאצי' שנאצלו מעצמות א\"ס ב\"ה שבא<sup data-n=\"1165\">73</sup> בבחי' פני<sup data-n=\"1166\">74</sup> אדם דבחי' יושר בכלל ובפרט כו', הרי מצד בחי' הכלים שעושי' בחי' התחלקות ימצא בהן ב' הפכים דחו\"ג ומעלה ומטה כמו ראש ורגל כו' משא\"כ ע\"ס שבעצמות כנ\"ל (וכנ\"ל במשל התלבשות כחות הנפש באברים [כ]רצון ותענוג וחכ' ומדות שעכ\"ז בצלם יתהלך איש כו', כך הוא למעלה באיש העליון כו' כמו ויתעצב אל לבו<sup data-n=\"1167\">75</sup> כו' ולהיפך וינחם על הרעה<sup data-n=\"1168\">76</sup> כו' הרי יש שינוי רצון מחסד לדין ומדין לחסד, וכתי' כי לא אדם הוא להנחם<sup data-n=\"1169\">77</sup> כו', ושניהם אמת דבעצמות כלולים הכל כא' נאמר כי לא אדם כו' ובהתלבשותם בכלים יש שינוי דחו\"ג מצד בחי' הכלים כו' כנ\"ל וד\"ל). וכ\"ז מצד בחי' הקו\"ח שנק' קו המדה<sup data-n=\"1170\">78</sup> שמודד כל או\"כ לבא בהשתלשלו' בבחי' עו\"ע עד שכאו\"א יש לו מקום [ו]מדריגה בפ\"ע דוקא וע\"כ הוא מקור כל או\"פ<sup data-n=\"1171\">79</sup> בכלי בכלל (ומקור המקיפי' הוא בעצמות א\"ס שלפני הקו\"ח כו' ובאמת גם הקו\"ח מתעגל וחוזר<sup data-n=\"1172\">80</sup> כו'), כי הקו\"ח כלול מבחי' [חו\"ג] שבעצמות א\"ס ממש וע\"כ יש בכחו לאכללא<sup data-n=\"1173\">81</sup> כו' להאיר אור החסד בכלי הגבו' כו' כמ\"ש במ\"א בוי\"ו דוהנורא<sup data-n=\"1174\">82</sup> כו'). ובדרוש<sup data-n=\"1175\">83</sup> דמי שם פה לאדם<sup data-n=\"1176\">84</sup> כו' מבואר להיפך דמצד בחי' הכלים דוקא בא בחי' ההתכללות דבר והיפוכו ובראש וסוף עד שיש ברגל מה שאין בראש ומקבלים זה מזה כו', והוא העיקר הנק' אדם אדמה לעליון ממש שהוא מהו\"ע ית' דלאו מכא\"מ כלל כו'. ומפני זה הטעם הוא מה שאנו רואים שיש בקו\"ח זה שנמשך מעצמות א\"ס ממש לאכללא שמאלא כו' ולהחליף האור בכלי היפוכו כו'. וגם מבואר שם דהתכללות זאת שבבחי' הכלים גבוה יותר מהתכללו' דע\"ס בעצמות שהגם שהן כלולים זה עם זה והיו לאחדים ממש מ\"מ אין א' מקבל מזולתו עד שבאמצעות כולם יחד דוקא נק' מציאות א' כו', אבל בבחי' אדם אין לא' שלימות בלא זולתו כלל רק באמצעות חיבורם יחד נק' אדם כו' והיינו אדמה לעליון<sup data-n=\"1177\">85</sup> ממש שהוא למעלה גם מע\"ס הגנוזות כו', הרי כ\"ז סתירה גמורה לכל ענין הנ\"ל. הענין הוא דשניהם אמת דמצד בחי' <span data-k=\"pg\">82</span> ּ ריבוי ההתחלקות שבא מצד הכלים דוקא כנ\"ל,",[["1163","71","<b>שורש או\"כ </b>[ג: לאו\"כ]<b> דז\"א שם הוא</b>: נסמן לעיל כד, ב הערה 30."],["1164","72","<b>דא\"ק נק' אדם דבריאה</b>: נסמן לקמן פ' בשלח קמה, ג."],["1165","73","<b>שבא</b>: ג: שהוא."],["1166","74","<b>פני</b>: גח: פרצוף."],["1167","75","<b>ויתעצב אל לבו</b>: בראשית ו, ו."],["1168","76","<b>וינחם על הרעה</b>: דבהי\"א כא, טו."],["1169","77","<b>כי לא אדם הוא להנחם</b>: שמואל-א טו, כט. ראה גם לקמן פ' בא צא, ד."],["1170","78","<b>הקו\"ח שנק' קו המדה</b>: נסמן לקמן מא, א."],["1171","79","<b>הקו\"ח. . או\"פ</b>: ראה גם לעיל כד, א ובהנסמן לשם."],["1172","80","<b>הקו\"ח מתעגל וחוזר</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב. ראה גם שעה\"י פט\"ז ואילך. ש\"א עט, ב."],["1173","81","<b>הקו\"ח. . לאכללא</b>: נסמן לקמן מח, ב."],["1174","82","<b>בוי\"ו דוהנורא</b>: ראה מאמרי אדה\"ז תקס\"ז ע' כו ואילך. תו\"ח בראשית מא, ד ובהערה 50. לקמן פ' בשלח קנה, סע\"א ואילך."],["1175","83","<b>כו'). ובדרוש</b>: גח: כו' (ובדרוש."],["1176","84","<b>ובדרוש דמי שם פה לאדם</b>: ראה לקמן מה, ב ואילך ובהנסמן לריש המאמר שם."],["1177","85","<b>אדם. . אדמה לעליון</b>: נסמן לקמן מו, ב."]]],[2300540320,"הרי [י]ש שינוי רצון ושכל ומדות מדבר להיפוכו כנ\"ל זהו למטה הרבה מבחי' ע\"ס הכלולים בעצמות שהוא כמו כחות הרוחני' הכלולים בנפש עצמ[ה] הנ\"ל ששם נאמר כי לא אדם הוא להנחם בשינוי רצון וחכמה כו'. אבל מצד בחי' ההתכללו' אמיתי' דראש וסוף ודבר והיפוכו שיש בכלים, זהו הרבה יותר גדול במעלה מהתכללות דע\"ס בעצמות עד שהוא דומה לעליון ממש שהוא אח\"פ ממש (ומה שאנו אומרים יהי רצון<sup data-n=\"1178\">86</sup> מלפניך שיכבשו כו' הרי יש שינוי רצון [מ]עצמות[ו] שהוא מלפניך ממש כו' אעפ\"י שנא' כי לא אדם הוא להנחם כו', הענין הוא דגם שינוי רצון זה ה\"ז בא דוקא מבחי' ההתכללו' שבכלים דאדם עד שישתנה מקור הרצון שבראש מצד סוף מעשה דנעוץ תחב\"ס וסוב\"ת<sup data-n=\"1179\">87</sup> כמ\"ש שם. וז\"ש יה\"ר מלפניך דוקא ששם הוא שרש ההתכללו' דאדם ע\"כ בא השינוי בכלים דאדם להנחם מרצון לרצון היפוכו אע\"פ שמצד עצמו לא אדם הוא להנחם וד\"ל) (ושרש הענין ידוע שיש ג' מדרגות יש האמיתי ומיש זה האמיתי לבחי' אין ומאין ליש, ושרש יש מאין הוא ביש האמיתי, וז\"ש אל דעות<sup data-n=\"1180\">88</sup> כו', ודיעה העליונה שמיש האמיתי לאין נמצא דוקא בבחי' יש גמור דהיינו בחי' אדם בכלים שדומה לעליון ממש שלמעלה מבחי' אדם<sup data-n=\"1181\">89</sup> אין של היש שהן ע\"ס הכלולים בעצמות. ולכך האדם בעל בחירה ורודה ומושל בכל להיות[ו] דומה לעליון ממש שהוא בחי' יש האמיתי כמ\"ש<sup data-n=\"1182\">90</sup> בענין משיח דכתי' בי' וגבה מאד<sup data-n=\"1183\">91</sup> כנ\"ל<sup data-n=\"1184\">92</sup>, וזהו ההפרש בין מ\"ה דמשה מה שמו ומה שם בנו<sup data-n=\"1185\">93</sup> דמשיח כו' וד\"ל).\n[ו] <b>והנה</b> בדרך כלל יובן מכל הנ\"ל דמצד בחי' הכלים מכלים שונים בא ריבוי ההתחלקות של המדרגות בריבוי אופנים שונים מאד כמו שאנו רואים בציור ניתוח האברים באדם מראשו לרגלו כו', שבא האור ושפע בדרך ירידה מלמעלה למטה בסדר והדרגה מעליון לתחתון והוא מה שנעשה בבחי' פנימי' וחיצוני' וחיצוניות דחיצוניות שנק' ראש תוך סוף ויורד ומשתלשל עד\"ז עד בחי' חיצוניות דחיצוניות היותר אחרון מהכל כמו צפורן הרגל ושערות כו', ואם נעריך ערך הצפרנים ושערות לגבי בחי' ההתחלה וראש הכל שהוא המקור של הרצון וחכמה, לא ישוער שיכול לבוא בהשתלשלו' זה מזה. אך מצד ריבוי הכלים בהתחלקות פנימי' וחיצוניות דחיצוניות עד עקב הרגל יצמח גם המותרות דחיות הצפורן וכמו<sup data-n=\"1186\">94</sup> יניקת השערות וכה\"ג, לפי שהחיות שיוצאי' בהשתלשלו' בכחות האברים נבדל הפנימי' מן החיצוני' עד היותר חיצוני' כו'. וזהו הנק' בשם השתלשלו' דוקא כמו השלשלת<sup data-n=\"1187\">95</sup> שטבעת התחתונה קשורה",[["1178","86","<b>שאנו אומרים יהי רצון</b>: בסדר תקיעת שופר בסידור האריז\"ל [בדילוג]."],["1179","87","<b>דנעוץ תחב\"ס וסוב\"ת</b>: ראה ס\"י פ\"א, מ\"ז."],["1180","88","<b>אל דעות</b>: שמואל-א ב, ג. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11."],["1181","89","<b>אדם</b>: גח: ליתא."],["1182","90","<b>כמ\"ש</b>: ג: וכמ\"ש במ\"א. ח: וכ\"ז נאמר."],["1183","91","<b>משיח. . וגבה מאד</b>: ישעי' נב, יג. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתיז. מאמרי אדה\"א קונטרסים ע' רלד. תו\"ח נח עו, א. לקמן מז, ד. פ' בשלח רכד, ב. רכה, א."],["1184","92","<b>כנ\"ל</b>: גח: כו'."],["1185","93","<b>מה שמו ומה שם בנו</b>: משלי ל, ד. ראה גם לקמן מט, ב. וש\"נ."],["1186","94","<b>וכמו</b>: גח: וכן."],["1187","95","<b>השתלשלו'. . השלשלת</b>: נסמן לעיל פ' שמות כד, ב הערה 36."]]],[2300540345,"בעליונה בסופה וכן עליונה בעליונה הימנה וכמו משלשלין פירות<sup data-n=\"1188\">96</sup> כו' [ש]זהו ענין דבר שהורד ממדריגה למדריגה מהעליון יותר עד התחתון יותר כו'. וכך הוא בענין השתלשלו' עו\"ע דמקור הרצון ברצון ומרצון לשכל ומשכל למח' ולמדות כו' עד המעשה והתנועה ברגל שתלוי וקשור בתחילת מקור הרצון וחכ', וכ\"ז ע\"י ריבוי התחלקות הכלים לבד כו'. וכך יובן למעלה בכללות כל ההשתלשלו' דקו\"ח הנ\"ל שגם שהוא העליון יותר מכל היינו כמו השלשלת ממש שיורד ומשתלשל בבחי' עו\"ע כאו\"א על מקומו יבא אחוז וקשור בעליון הימנו זה תחת זה עד שנמשך למטה מטה <span data-k=\"pg\">מא</span> ּ בסוף עולם העשי' (דעקב דא\"ק מסתיים<sup data-n=\"1189\">97</sup> בסוף העשי'<sup data-n=\"1190\">98</sup> וראשו בראשית [ה]קו\"ח כו'), וכ\"ז רק מצד בחי' ריבוי הכלים מכלים שונים באצי' עצמו, עד שמזה נסתעף ונשתלשל משם בחי' הארה דהארה גם למטה מטה שהן ג' עולמות דבי\"ע כידוע בע\"ח שמבחי' למ\"ד כלים דז\"א<sup data-n=\"1191\">99</sup> דאצי' להיותם בג' מדרגות ראש תוך סוף פנימי ואמצעי וחיצון כו', ע\"כ מהם נעשה שורש ומקור להתהוות הג\"ע<sup data-n=\"1192\">100</sup> דבי\"ע היינו שמבחי' יו\"ד כלים הפנימיים נעשה בחי' נשמה לבריאה ומן האמצעי נעשה בחי' רוח ליצי' וחיצוניות נעשה נפש בעשי'. וכל עולם ועולם מג' עולמות אלו כלול מבי\"ע<sup data-n=\"1193\">101</sup>, דהיינו נר\"ן ששרשם הכללי הוא בלמ\"ד כלים דז\"א כו' (וכמו נר\"ן דכנ\"י הרי גם בחי' נפש דעשי' כלול מנר\"נ<sup data-n=\"1194\">102</sup> כו' וכמ\"ש בראתיו יצרתיו אף עשיתיו<sup data-n=\"1195\">103</sup> דקאי הכל בניצוץ א' שנברא וגם נוצר כו' וגם<sup data-n=\"1196\">104</sup> בראת יצרת ונפחת<sup data-n=\"1197\">105</sup> כו'<sup data-n=\"1198\">106</sup> כידוע).\n<b>וביאור</b> הענין הוא לפי שגם בבחי' עשי' בפו\"מ יש מבחי' כמה מדרגות חלוקות ז[ו] למעלה מזו, כמו ההפרש בין יד לרגל שהרגל פעולתו בהילוך לבד והיד פעולתו במלאכה שיש בה חכמה כמו הציור והכתיבה לכתוב דבר שכל וחכמה או לרמז ברמז על עומק איזה שכל כו'. ונמצא יש בעשי' דיד עצמו חב\"ד חג\"ת נה\"י שהן ג' מדרגות דאורות כמו השכל שבעשי' לציור ולכתיבה כו' וחסד הנשפע מן היד וגוף פעולת מלאכת היד, ולנגד זה ג' מיני כלים שהן ג' פרקין דיד, וכך הוא גם ברגל<sup data-n=\"1199\">107</sup> ג' פרקין עד עקב הרגל בהילוך לבד, שכל זה אינו בא רק מצד חילוקי הכלים פנימי אמצעי חיצון כו', עד גם בחכ' שבראש יש ג' מדרגות דחב\"ד חג\"ת נה\"י שהוא חכ' שבחכ' עצ[ם] השכל ומדות שבו להטות כלפי דין וחסד<sup data-n=\"1200\">108</sup> חג\"ת ונה\"י שבו הוא מה שדן ע\"פ שכלו למעשה, ויש לזה ג' מיני כלים וכלי פנימי הוא לחכ' עצמ[ה] ואמצעי למדות שבה וחיצוני' לנה\"י שבה שהוא בחי' עשי' שבשכל כו', ואם לא ג' מיני כלים אלה לא הי' בא עצם כח השכל בהתחלקות פרטיות למדות ומעשה כלל. וכך עד\"ז בכל",[["1188","96","<b>משלשלין פירות</b>: ביצה לה, ב: משילין פירות. ובר\"ח שם פי' משילין משלשלין."],["1189","97","<b>דעקב א\"ק מסתיים בסוף עשי'</b>: ראה אגה\"ק ס\"כ (קלא, ב). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו."],["1190","98","<b>בסוף העשי'</b>: גח: בעשי'."],["1191","99","<b>למ\"ד כלים דז\"א</b>: נסמן לעיל כד, ב."],["1192","100","<b>הג\"ע</b>: גח: הג' עולמות."],["1193","101","<b>וכל עולם. . כלול מבי\"ע</b>: ראה ע\"ח (שער כללות אבי\"ע) שמ\"ב, פ\"ד."],["1194","102","<b>נפש דעשי' כלול מנר\"נ</b>: ראה תניא פ\"ב."],["1195","103","<b>בראתיו יצרתיו אף עשיתיו</b>: ישעי' מג, ז. ראה גם מאמרי אדה\"א שמות ח\"א ע' צה."],["1196","104","<b>וגם</b>: גח: וכמ\"ש אתה."],["1197","105","<b>בראת יצרת ונפחת</b>: ברכת אלקי נשמה [בדילוג]."],["1198","106","<b>ונפחת כו'</b>: גח: נפחת בי."],["1199","107","<b>ג' פרקין דיד. . ברגל</b>: ראה גם לקמן מה, א. וש\"נ."],["1200","108","<b>דין וחסד</b>: גח: חסד ודין."]]],[2300540368,"אברי האדם מה שיורד האור ומשתלשל ממוחין למדות עד בחי' נה\"י שבנה\"י שהוא עקב הרגל וכה\"ג עד שיתהווה גם בחי' חיצוניות דחיצוניות [כ]צפרנים ושערות בחי' מותרי השפע, כמו בגידי' ובשר ועצמות שהן ג' מיני כלים בגשמיות האברים שהעצמות כלים הפנימים והבשר כלים חיצונים כמ\"ש עור ובשר תלבישני<sup data-n=\"1201\">109</sup> והגידים הם כלים האמצעים המחברם כו' וד\"ל. וכ\"ז דמיון להבין למעלה בבחי' התחלקות ריבוי הכלים שמזה נסתעף ההשתלשלו' שיומשך השפע האלקי' להיות ג\"ע<sup data-n=\"1202\">110</sup> בי\"ע שהוא בא מבחי' התחלקות דלמ\"ד כלים דז\"א שהן בג' מדרגות דראש תוך סוף פנימי ואמצעי וחיצון כנ\"ל. והענין הוא שגם שבחי' למ\"ד כלים הללו הן רק בבחי' עשי' בכלל לגבי אורות דאצי' להיותם כמו ציור אברי האדם, הרי יש בהם ג' מדרגות דכלים פנימי ואמצעי וחיצון כו' ע\"ד הנ\"ל בעשי' שביד ורגל כו', שמג' אלה נעשה ג' מקוריי' לג' עולמות בי\"ע, כלי הפנימי' דאצי' נעשה מקור לעולם הבריא' כו' כנ\"ל עד שחיצוני' הכלים [דז\"א] דאצי' נעשה מקור לכל עולם העשי' כנ\"ל וד\"ל.\n[ז] <b>וביאור</b> ענין זה יובן ע\"פ הנ\"ל בג' מיני כלים לג' מיני אורות גם בחכ' שבראש כו', שבחי' חכ' שבעשי' [ש]נק' שכל שבעשי' [דאצי'] נעשה מקור לנשמות ומלאכים דעולם הבריאה דאימא מקננא<sup data-n=\"1203\">111</sup> כו' בחי' נשמה שהוא התהוות החכ' וההשגה האלקי' המוגבלת בנשמות ומלאכים דבריאה מאין ליש כו', <span data-k=\"pg\">84</span> ּ וזהו מבחי' כלים פנימי' דעשי' שבאצי'. ומבחי' אמצעות הכלים היינו מבחי' כלי המדות חג\"ת דעשי' שבאצי' נעשה מקור להתהוות המדות דאוי\"ר דמלאכי' ונשמות דעולם היצי' שהוא בחי' רוח כו'. ומבחי' חיצוני' הכלים דעשי' שבאצי' (שנק' עשי' דעשי' דאצי' או נה\"י שבנה\"י כו' כפרק הג' עקב דרגל להילוך וכעשי' שביד כנ\"ל) שהוא בחי' סוף מעשה דעשי' דאצי' נעשה מקור להתהוות עולם העשי' כו' (וכנ\"ל בג' מדרגות דיד ורגל). ועד\"ז יש גם בכל עולם דבי\"ע התכללות מג' מדרגות דבי\"ע עד בחי' עשי' דסוף עולם העשי' כו' (שהוא בחי' מל' דמל' דעשי'<sup data-n=\"1204\">112</sup> שנק' עקב ורגל בחי' רגלי השכינה<sup data-n=\"1205\">113</sup> כו', וכמ\"ש והארץ הדום [רגלי<sup data-n=\"1206\">114</sup> כו', משום דגם בי\"ס דעשי' יש ג' מדריגות הנ\"ל, בג' מיני כלים רת\"ס עד בחי' עשי' דעשי' שנק' הדום] רגלי כו').\n<b>ויובן</b> זה בתוס' ביאור ע\"ד אחר הידוע בשרש התהוות ג' עולמות בי\"ע שהוא ג' מדרגות דמחדו\"מ<sup data-n=\"1207\">115</sup> שהן נק' ג' לבושים פנימי ואמצעי וחיצון וכל א' כלול מג' אלה כו', שבחי' המח' הוא המקור ל[התהוות] עולם הבריאה והדבור מקור לעולם",[["1201","109","<b>עור ובשר תלבישני</b>: איוב י, יא."],["1202","110","<b>ג\"ע</b>: גח: ג' עולמות."],["1203","111","<b>דאימא מקננא</b>: נסמן לעיל ה, ד הערה 264."],["1204","112","<b>דעשי'</b>: ג: ניתוסף: בגלגלתא כו'. ח: ניתוסף: בגלגלים כו'."],["1205","113","<b>רגלי השכינה</b>: נסמן לעיל כד, ג."],["1206","114","<b>והארץ הדום [רגלי</b>: ישעי' סו, א."],["1207","115","<b>בי\"ע. . דמחדו\"מ</b>: נסמן לקמן פ' בשלח קמד, סע\"ב."]]],[2300540389,"היצי' והמעשה לעולם העשי' והן ענין למ\"ד כלים דז\"א שכלולים ג' אלה במדות ומוחין דז\"א ומתפשטים למטה בשביל התהוות ג' עולמות הללו וכמ\"ש לבושין תקינת לון<sup data-n=\"1208\">116</sup> כו' וכמ\"ש במ\"א. ויובן זה עד\"מ באדם למטה שיש במח' עצמ[ה] ג' מדרגות דמחדו\"מ<sup data-n=\"1209\">117</sup>, היינו מח' דמח' שזהו כמו מחשבת שכל שחושבו בצירופי אותיות המח' כו' והדבור שבמח' שחושב מה שידבר כו' ומעשה שבמח' שחושב איך לעשות כו' (והוא ג\"כ בחי' דמיון שבמח' כמו שמדמה במח' איזה ציור אות כו' כידוע), ובחי' ג' אלה במח' נק' כלים ראש תוך סוף. ועשי' שבמח' הוא למעלה ממח' שבדבור כו', כי הדיבור גם הוא כלול מג' אלה מח' שבדבור שמלובשת המחשבה באותיות שמדבר כו' ודבור שבדבור הוא גופי אותיות הדבור ועשי' שבדבור מה שמצוה בדבור לעשות (והוא עקימת שפתיו דהוא מעשה שבדבור) שהן ג\"כ ג' כלים שבדבור ראש תוך סוף (נגד ג' מדרגות דחב\"ד חג\"ת נה\"י שבדבור כו'). ועשי' שבדבור למעלה מן המעשה, ובמעשה עצמו יש ג' מדרגות מחשבה שבמעשה כמו החושב במעשה הציור ובנין או כתיבה שנק' שכל שבעשי' כנ\"ל ודבור שבמעשה הוא בחי' מדות שבמעשה שהוא החשק לעשות דבר מה לטובתו ולשמור מהיפוכו כו' וגוף המעשה עצמ[ה] שנק' עשי' שבעשי' כו' שהוא האחרון מכולם ונק' סוף מעשה כו' וד\"ל. וכך יובן בג' מדרגות דמחדו\"מ למעלה אעפ\"י שנא' כי לא מחשבותי<sup data-n=\"1210\">118</sup> [מחשבותיכם] כו', שמחדו\"מ דאצי' נעשים מקורים לג' עולמות וכל א' כלול מג' כלים דמחדו\"מ, והוא מה שע\"ס דבריאה כלול מג' אלה עד עשי' [דבריאה, וכן ע\"ס דיצירה כלול ממחדו\"מ שהן בי\"ע דיצירה עד עשי' דיצירה, אך בחי' עשי'] דעשי' שהוא מל' דמל' דעולם העשי' שנק' רגלי השכינה כנ\"ל שזהו חיצוני' הכלים דמל' דעשי' שנא'<sup data-n=\"1211\">119</sup> הארץ הדום רגלי כו'. והוא בכנס\"י בירור דעקבות משיחא<sup data-n=\"1212\">120</sup> נשמות שברגלי השכינה בדור האחרון שזהו רק בחי' עשי' דעשי' היינו רק המעשה דמצוה מצד עצמו לבד כמו מעשה הצדקה דכתי' צדקה תרומם גוי<sup data-n=\"1213\">121</sup> כו' ובצדקה תכונני<sup data-n=\"1214\">122</sup> כו' לפי שנתחב\"ס, וזהו עד דמטי רגלין ברגלין<sup data-n=\"1215\">123</sup> כו' כידוע וד\"ל.\n[ח] <b>והנה</b> ידוע שאע\"פ שענין ההשתלשלו' <span data-k=\"pg\">מב</span> ּ בכלל הוא ענין הצמצום והירידה<sup data-n=\"1216\">124</sup> האור מעילה לעלול במיעוט",[["1208","116","<b>לבושין תקינת לון</b>: ת\"ז בהקדמה (יז, א)."],["1209","117","<b>במח'. . דמחדו\"מ</b>: ראה גם אגה\"ק סו\"ס יט. ביאוה\"ז וישב כא, ד. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרעז. מאמרי אדה\"א הנחות תקע\"ז ע' רפב. דרושי חתונה ח\"א ע' עט ואילך."],["1210","118","<b>כי לא מחשבותי</b>: ישעי' נה, ח. ראה גם שע\"ת קט, ג."],["1211","119","<b>שנא'</b>: גח: שעז\"א."],["1212","120","<b>דעקבות משיחא</b>: ראה גם שה\"א קא, ב ובהערה 21. תו\"א מקץ מא, א. ש\"א ה, א. וש\"נ. לקמן פ' וארא עח, ג. תצוה שלד, א."],["1213","121","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["1214","122","<b>ובצדקה תכונני</b>: ישעי' נד, יד [ושם: בצדקה — ראה שע\"ת עב, ג]."],["1215","123","<b>עד דמטי רגלין ברגלין</b>: נסמן לעיל כד, ג."],["1216","124","<b>ענין. . והירידה</b>: ח: בחי'. גח: ויריד[ו]ת."]]],[2300540409,"אחר מיעוט מצמצום הראשון שבקו\"ח עד צמצום היותר אחרון שהוא בחי' עשי' דעשי' (שהוא בחי' עקב דא\"ק עד סוף<sup data-n=\"1217\">125</sup> עולם העשי' כנ\"ל), הנה עיקר הכוונה הי' בעצמות המאציל בירידה זו בשביל עלי', וירידה זו לצורך עלי' היתה שיהי' לו דירה בתחתונים כו' (היינו שיהי' בחי' ביטול היש לאין בכל המדרגות מראש לסוף עד נשמות ומלאכים דבי\"ע כו'). וזהו עיקר בחי' הקו המדה שהוא הקו\"ח הנ\"ל שהוא הנותן מדה ושיעור לכל המשכות ושפע דאו\"כ דאצי' כמה יהי' במציאות [יש] שהוא הכלים וכמה יהי' בחי' הביטול שלו לבחי' אין שהוא האור שזהו ענין אור בכלי<sup data-n=\"1218\">126</sup> בכלל, שאם הי' ההארה יותר מכפי המדה מעט הי' בבחי' הביטול במציאות לגמרי כענין הושיט אצבעו<sup data-n=\"1219\">127</sup> קטנה ביניהם ושרפן כו', וכך הוא גם עד רום המעלות בע\"ס דאצי' ולמעלה כו' וז\"ש בראשית ברא אלקים<sup data-n=\"1220\">128</sup> דוקא כמ\"ש במ\"א. וזהו כללות ענין הצמצום דקו\"ח שיומשך בבחי' גילוי אוב\"כ דוקא והכל במדה לפי בחי' ההשתלשלו' ברוב הצמצומי' עד ג' עולמות דבי\"ע שיש שם בחי' ביטול היש לאין ג\"כ וכמ\"ש והחיות רצוא ושוב<sup data-n=\"1221\">129</sup> כו', ובא בחילוקי מדרגות בכלל מעולם העליון לעולם שלמטה הימנו, כמו בעולם הבריאה שם הביטול דנשמות ומלאכים בהתפעלו' וביטול פנימי יותר בהשגה ומוחי' דאור אימא כו', ובעולם היצי' בביטול במדות דאוי\"ר שלמטה מביטול המוחי' כו', עד מלאכים דעשי' כאופנים וצבא השמים שהן משתחוים בבחי' הודאה<sup data-n=\"1222\">130</sup> לבד כו'. ועד\"ז יש כמה חילוקי מדריגות בכל עולם בכמה מיני אופנים שונים כמו ד' מחנות שכינה<sup data-n=\"1223\">131</sup> מחנה מיכאל בביטול דאהבה ותשוקה וכן פני ארי' להימין<sup data-n=\"1224\">132</sup> כו', ומחנה גבריאל הביטול [לאין] שלהם ביראה ופחד כו', וכן פני שור<sup data-n=\"1225\">133</sup> כו'. ובכאו\"א לפי מדריגתו בפרט יש לו מס\"נ בהעלאת מ\"ן באופן מיוחד, כמו גם במחנה מיכאל יש קפ\"א<sup data-n=\"1226\">134</sup> מדריגות שונות כו' כמ\"ש בזהר פקודי<sup data-n=\"1227\">135</sup>. ויש עד\"ז רבוא רבבות אלפים מדרגות שונות זה למטה מזה<sup data-n=\"1228\">136</sup> במדריגת הביטול לאין האלקי כו' לפי ערך ריבוי ההשתל' בצמצומי' רבים כו'<sup data-n=\"1229\">137</sup> עד צבא השמים בגלגלים וכה\"ג שמקבלים מחיצוני' דחיצוני' דאופנים דעשי', גם הם משתחוים ואומרים שירה כו' כענין שמש בגבעון דום<sup data-n=\"1230\">138</sup> כו' עד גם הע\"ש דנוגה דעשי' שמקבלים מבחי' אחוריי' וחיצוני' דמ\"ח צירופי' האחרונים דשם האלקי'<sup data-n=\"1231\">139</sup> כו', גם בהם יש בחי' ביטול אין האלקי כמ\"ש מלך אלקים על גוים<sup data-n=\"1232\">140</sup> כו' וכן מי לא יראך<sup data-n=\"1233\">141</sup>",[["1217","125","<b>עד סוף</b>: גח: בסוף."],["1218","126","<b>אור בכלי</b>: שם: או\"כ."],["1219","127","<b>הושיט אצבעו</b>: סנהדרין לח, ב. ראה לקמן פ' וארא עה, ג. בא צט, ב. בשלח קמד, א. מאמרי אדה\"א ויקרא ח\"א ע' קסא. וש\"נ. שערי אורה כה, א. כו, א. תו\"ח בראשית יז, ב ובהערה 9."],["1220","128","<b>בראשית ברא אלקים</b>: בראשית א, א. ראה גם לקמן לד, סע\"ב ואילך. פ' בשלח קנ, ב. יתרו רסו, ב. תרומה שה, א. פקודי תנד, א. מאמרי אדה\"א דברים ח\"ג ע' א'כב. ח\"ד ע' א'תכט. ע' א'תמב."],["1221","129","<b>והחיות רצוא ושוב</b>: יחזקאל א, יד."],["1222","130","<b>כאופנים וצבא השמים. . הודאה</b>: נחמי' ט, ו. ראה גם מאמרי אדה\"א קונטרסים ע' תלז."],["1223","131","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["1224","132","<b>פני ארי' להימין </b>[ח: אל הימין]: יחזקאל א, י [ושם: ופני]. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רכד."],["1225","133","<b>פני שור</b>: נסמן בהערה שלפנ\"ז."],["1226","134","<b>קפ\"א</b>: ג: ק\"פ אלף. ח: קפ\"א אלף. ראה מאמרי אדה\"א ויקרא שם. וש\"נ. הנחות תקע\"ז ע' לד. וש\"נ."],["1227","135","<b>בזהר פקודי</b>: ג: בזוה\"ק (פ' פקודי). ראה גם לעיל כד, ג. מאמרי אדה\"א ויקרא שם ובהנסמן שם."],["1228","136","<b>זה למטה מזה</b>: גח: זו למטה מזו."],["1229","137","<b>כו'</b>: ג: שונים."],["1230","138","<b>כענין </b>[ח: כידוע בענין]<b> שמש בגבעון דום</b>: יהושע י, יב וברש\"י שם ובע\"ז כה, א (ד\"ה וידום הב'). ראה סידור שער המילה קמב, ב ואילך."],["1231","139","<b>דמ\"ח צירופי'. . האלקי'</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ה. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיג ובהנסמן במ\"מ לשם. תו\"ח נח סד, ד ובהערה 52."],["1232","140","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["1233","141","<b>מי לא יראך</b>: ירמי' י, ז."]]]]});
